window.COURSE_CODE = "IT4785E";
window.CHAPTERS = [{"number": 1, "title": "20231 · Lượt 1 (tr. 1–14)", "questions": [{"id": "20231-1-1", "text": "The res folder does not include which following resources?", "type": "single", "options": [{"id": "A", "text": "file to define dependence libraries used in project"}, {"id": "B", "text": "file to define strings, colors used in project"}, {"id": "C", "text": "file to define demensions used in project"}, {"id": "D", "text": "file to define the menu structure used in project"}], "answers": ["A"], "source": {"term": "20231", "pages": [1], "number": 1, "code": "c8998a"}, "plain": true, "explanation": "res chứa layout, drawable, menu và các giá trị như strings, colors, dimens. Thư viện phụ thuộc được khai báo trong cấu hình Gradle của module, không phải một tài nguyên trong res.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}, {"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-2", "text": "What is the purpose of using RadioGroup?", "type": "multi", "options": [{"id": "A", "text": "to group RadioButton objects"}, {"id": "B", "text": "to arrange RadioButton objects by rows or by columns"}, {"id": "C", "text": "to replace the LinearLayout"}, {"id": "D", "text": "to make a RadioButton acts like a CheckBox"}, {"id": "E", "text": "to identify which RadioButton is selected"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [1], "number": 2, "code": "3dc7d2"}, "note": "", "plain": true, "explanation": "RadioGroup gom các RadioButton để chỉ chọn một nút trong nhóm; getCheckedRadioButtonId() cho biết nút đang chọn. Nó kế thừa LinearLayout nên có thể bố trí ngang hoặc dọc. Nó không biến RadioButton thành CheckBox và không phải phương án thay thế LinearLayout nói chung.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-3", "text": "How to handle the event that user press the button and hold for a while?", "type": "single", "options": [{"id": "A", "text": "setLongClickListener"}, {"id": "B", "text": "setOnLongClickListener"}, {"id": "C", "text": "setOnClickListener"}, {"id": "D", "text": "setOnLongTouchListener"}], "answers": ["B"], "source": {"term": "20231", "pages": [1], "number": 3, "code": "fd9ca3"}, "plain": true, "explanation": "Nhấn giữ được xử lý bằng setOnLongClickListener. onLongClick(view) trả về true nếu sự kiện đã được xử lý. setOnClickListener xử lý thao tác nhấn thông thường; các tên setLongClickListener và setOnLongTouchListener trong đề không phải API tương ứng.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-4", "text": "Which of the following tasks can be performed in onCreate()?", "type": "multi", "options": [{"id": "A", "text": "Configuring views, such as setting the layout manager of a recycler view"}, {"id": "B", "text": "Determining the items to be shown in the options menu."}, {"id": "C", "text": "Setting the onClickListener for items in the options menu."}, {"id": "D", "text": "Getting extras from the intent that launched the activity."}], "answers": ["A", "D"], "source": {"term": "20231", "pages": [2], "number": 4, "code": "2adffe"}, "plain": true, "explanation": "Theo cách tổ chức vòng đời chuẩn, onCreate() khởi tạo view, cấu hình RecyclerView và đọc intent.extras. Options menu được tạo trong onCreateOptionsMenu(), còn thao tác chọn menu được xử lý qua onOptionsItemSelected() hoặc listener của MenuItem. Cụm “can be performed” trong đề được hiểu là nơi thích hợp theo quy ước, không phải giới hạn kỹ thuật tuyệt đối.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}, {"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-5", "text": "What is the default return type of any functions defined in Kotlin?", "type": "single", "options": [{"id": "A", "text": "Unit"}, {"id": "B", "text": "Double"}, {"id": "C", "text": "void"}, {"id": "D", "text": "Int"}], "answers": ["A"], "source": {"term": "20231", "pages": [2], "number": 5, "code": "ba6075"}, "plain": true, "explanation": "Unit là kiểu trả về mặc định của hàm có thân khối khi không khai báo kiểu trả về, ví dụ fun log() { println(\"Hi\") }. Đề dùng từ “any” quá rộng: hàm thân biểu thức như fun twice(x: Int) = x * 2 được suy ra kiểu Int. Kotlin dùng Unit thay cho cách viết void của Java.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-6", "text": "When is the current Activity reset, i.e., the onCreate callback is called again?", "type": "multi", "options": [{"id": "A", "text": "user rotates the phone"}, {"id": "B", "text": "user changes the language of the phone"}, {"id": "C", "text": "user presses the home button and opens another app"}, {"id": "D", "text": "the phone is going to out of battery"}], "answers": ["A", "B"], "source": {"term": "20231", "pages": [2], "number": 6, "code": "a73d85"}, "plain": true, "explanation": "Theo hành vi mặc định, xoay màn hình hoặc đổi ngôn ngữ là thay đổi cấu hình và có thể làm Activity bị hủy rồi tạo lại, gọi lại onCreate(). Bấm Home thường chỉ đưa Activity về nền. Ngoại lệ: ứng dụng tự xử lý cấu hình qua configChanges hoặc hệ thống khôi phục sau khi tiến trình bị hủy; vì vậy các lựa chọn được chấm theo trường hợp mặc định của đề.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-7", "text": "Which of the following is false about intents?", "type": "single", "options": [{"id": "A", "text": "Intents are performed using the startActivity method."}, {"id": "B", "text": "An implicit intent always results in the system asking the user which app to open"}, {"id": "C", "text": "Explicit intents require you to specify the class of the activity you want to show."}, {"id": "D", "text": "Both implicit and explicit intents allow your app to launch another activity."}], "answers": ["B"], "source": {"term": "20231", "pages": [2, 3], "number": 7, "code": "1d1720"}, "plain": true, "explanation": "Phát biểu sai theo ngữ cảnh mở Activity là “implicit intent luôn hỏi người dùng chọn ứng dụng”. Hệ thống có thể mở thẳng ứng dụng mặc định hoặc ứng dụng duy nhất phù hợp. Explicit intent chỉ định component; implicit intent mô tả action/data. Intent còn dùng cho service và broadcast, nên startActivity() không phải API cho mọi loại Intent.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-8", "text": "Which widget view could be used to make a clickable object with image content?", "type": "multi", "options": [{"id": "A", "text": "Button"}, {"id": "B", "text": "ImageButton"}, {"id": "C", "text": "Image View"}, {"id": "D", "text": "Image"}, {"id": "E", "text": "TextView"}], "answers": [], "source": {"term": "20231", "pages": [3], "number": 8, "code": "be7dd2"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "ImageButton là widget chuyên dùng cho nút có ảnh. Tuy nhiên ImageView cũng có thể nhận click listener, còn Button và TextView hỗ trợ compound drawable. Vì câu hỏi dùng “could be used” và không nói chỉ widget chuyên dụng nên có nhiều cách hiểu; không gán một đáp án duy nhất để chấm.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}, {"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}, {"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-9", "text": "Suppose we write an application to survey the hobby of people (there are 5 hobbies to be\nsurveyed), one person may have several hobbies. Which input controls is suitable for this\npurpose?", "type": "single", "options": [{"id": "A", "text": "RadioButton"}, {"id": "B", "text": "Recycler View"}, {"id": "C", "text": "DropDownList"}, {"id": "D", "text": "ListView"}, {"id": "E", "text": "Checkbox"}], "answers": ["E"], "source": {"term": "20231", "pages": [3], "number": 9, "code": "9d90db"}, "plain": true, "explanation": "CheckBox cho phép chọn độc lập nhiều sở thích cùng lúc. RadioButton trong một RadioGroup chỉ cho một lựa chọn, phù hợp câu hỏi loại trừ lẫn nhau. Số lượng sở thích không quyết định widget; điều quyết định ở đây là người dùng được chọn nhiều mục.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-10", "text": "Which value of the property scaleType of the ImageView allows us to keep remaining the\naspect ratio (the image will not be croped)?", "type": "single", "options": [{"id": "A", "text": "centerinside"}, {"id": "B", "text": "fitXY"}, {"id": "C", "text": "centerCrop"}, {"id": "D", "text": "center"}], "answers": ["A"], "source": {"term": "20231", "pages": [3], "number": 10, "code": "39fb6d"}, "plain": true, "explanation": "centerInside giữ tỉ lệ và thu nhỏ ảnh khi cần để toàn bộ ảnh nằm trong vùng hiển thị. fitXY có thể kéo méo; centerCrop phủ kín vùng nhìn bằng cách cắt ảnh; center giữ kích thước gốc nên ảnh lớn có thể bị cắt. Tên XML chính xác là centerInside, phân biệt chữ hoa chữ thường.", "references": [{"url": "https://developer.android.com/reference/android/widget/ImageView.ScaleType", "title": "ImageView.ScaleType"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-11", "text": "Which is the direct parent class of the Button class?", "type": "single", "options": [{"id": "A", "text": "android.widget.View"}, {"id": "B", "text": "android.view.TextView"}, {"id": "C", "text": "android.view.View"}, {"id": "D", "text": "android.widget.TextView"}], "answers": ["D"], "source": {"term": "20231", "pages": [4], "number": 11, "code": "2599de"}, "plain": true, "explanation": "android.widget.Button kế thừa trực tiếp android.widget.TextView. TextView lại kế thừa android.view.View. Chú ý cả tên lớp và package: android.view.TextView và android.widget.View trong các phương án là tên không đúng.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-12", "text": "In the fragment lifecycle, which of the following tasks should be performed in\nonViewCreated() ?", "type": "multi", "options": [{"id": "A", "text": "Inflating the layout"}, {"id": "B", "text": "Binding view objects to properties in your fragment"}, {"id": "C", "text": "Configuring the options menu"}, {"id": "D", "text": "Setting properties of individual views, such as a recycler view's adapter"}], "answers": ["B", "D"], "source": {"term": "20231", "pages": [4], "number": 12, "code": "698a49"}, "plain": true, "explanation": "onCreateView() tạo cây view; onViewCreated() được gọi sau khi cây view đã tồn tại. Vì vậy có thể lấy tham chiếu view, gắn dữ liệu và đặt adapter cho RecyclerView trong onViewCreated(). Không inflate layout lần nữa ở callback này; menu có cơ chế callback hoặc MenuProvider riêng.", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-13", "text": "If we have some buttons in one Activity, and all the buttons set the event onClickListener to\nthe Activity by calling setOnClickListener(this). So, in the callback function onClick of the\nActivity, how do you know which button is clicked?", "type": "single", "options": [{"id": "A", "text": "based on the order of buttons inside the xmi layout file"}, {"id": "B", "text": "based on the name of each button"}, {"id": "C", "text": "based on the position of each button"}, {"id": "D", "text": "based on the id of each button"}], "answers": ["D"], "source": {"term": "20231", "pages": [4], "number": 13, "code": "6b8296"}, "plain": true, "explanation": "onClick nhận chính View đã phát sinh sự kiện. Dùng view.id rồi so sánh với R.id của từng nút để xác định nút được nhấn. Vị trí, thứ tự trong XML hay tên biến Kotlin không phải định danh sự kiện ổn định.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-14", "text": "Which is a possible way/language to develop Android application?", "type": "multi", "options": [{"id": "A", "text": "Native approach: Java/Kotlin"}, {"id": "B", "text": "Web-based approach"}, {"id": "C", "text": "Universal Windows Platform (UWP) approach"}, {"id": "D", "text": "Object C"}, {"id": "E", "text": "Flutter"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [4, 5], "number": 14, "code": "0af446"}, "plain": true, "explanation": "Java/Kotlin là hướng native thông dụng; giao diện web có thể được đóng gói hoặc tích hợp qua WebView; Flutter cũng hỗ trợ xuất ứng dụng Android. UWP là nền tảng của Microsoft, còn Objective-C không phải lựa chọn Android native được hỏi ở đây. Các phương án đúng mô tả nhiều hướng phát triển, không chỉ một ngôn ngữ.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}, {"url": "https://developer.android.com/develop/ui/views/layout/webapps/webview", "title": "WebView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-15", "text": "An activity contains the following code in onCreate(). What will happen when this code is\nexecuted, if the intent property is null?\nval message = intent.extras?.getString(\"message\").toString()", "type": "single", "options": [{"id": "A", "text": "The app will not crash because the extras property is accessed safely using?."}, {"id": "B", "text": "The app will crash because it attempted to access a null object."}, {"id": "C", "text": "The app will not crash because the extras property is accessed unsafely using?."}, {"id": "D", "text": "The app will crash because it attempted to access the extras property on a null object."}], "answers": [], "source": {"term": "20231", "pages": [5], "number": 15, "code": "7be67c"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Nếu intent thực sự null như giả thiết, intent.extras truy cập receiver null trước khi gặp dấu ?. nên có thể lỗi. Muốn bảo vệ cả chuỗi phải dùng intent?.extras?.getString(\"message\"). toString() trên giá trị nullable có thể tạo chuỗi \"null\". Hai lựa chọn mô tả crash trong đề trùng nghĩa, nên không chấm ép một lựa chọn.", "references": [{"url": "https://kotlinlang.org/docs/null-safety.html", "title": "Kotlin · Null safety"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-16", "text": "Overdiding the callback onSavelnstanceState is not suitable in which situation?", "type": "single", "options": [{"id": "A", "text": "save some states of Activity and restore latter when there is a device configuration changed"}, {"id": "B", "text": "save some states of Activity and restore latter when user rotates the device screen"}, {"id": "C", "text": "save some states of Activity and restore latter when user changes the language of the device"}, {"id": "D", "text": "store data into SD card to permanently use latter"}], "answers": ["D"], "source": {"term": "20231", "pages": [5], "number": 16, "code": "Obd251"}, "plain": true, "explanation": "onSaveInstanceState() lưu trạng thái UI nhỏ để tái tạo Activity, chẳng hạn sau khi xoay màn hình. Nó không thay thế cơ sở dữ liệu, file hay DataStore để lưu dữ liệu lâu dài, và không bảo đảm được gọi trong mọi tình huống đóng ứng dụng. Vì vậy lưu dữ liệu vĩnh viễn ra thẻ nhớ không phải mục đích phù hợp.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle#saras", "title": "Lưu và khôi phục trạng thái"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-17", "text": "What is the function to open new activity from the current activity?", "type": "single", "options": [{"id": "A", "text": "newActivity"}, {"id": "B", "text": "beginActivity"}, {"id": "C", "text": "startActivity"}, {"id": "D", "text": "openActivity"}], "answers": ["C"], "source": {"term": "20231", "pages": [5], "number": 17, "code": "7addd1"}, "plain": true, "explanation": "startActivity(intent) yêu cầu Android mở Activity được Intent xác định hoặc phân giải. Với explicit intent có thể viết Intent(this, TargetActivity::class.java). Các tên newActivity(), beginActivity() và openActivity() không phải phương thức mở Activity chuẩn của ngữ cảnh này.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-18", "text": "In case the activity has too many input controls so that the layout height is over the height\nof the phone's screen, which ViewGroup should be used?", "type": "single", "options": [{"id": "A", "text": "ScrollView"}, {"id": "B", "text": "LinearLayout"}, {"id": "C", "text": "HorizontalScrollView"}, {"id": "D", "text": "VerticalScrollView"}], "answers": ["A"], "source": {"term": "20231", "pages": [6], "number": 18, "code": "000ae4"}, "plain": true, "explanation": "ScrollView cho phép cuộn nội dung theo chiều dọc khi nội dung cao hơn màn hình. Nó chỉ có một view con trực tiếp; thường đặt một LinearLayout chứa các trường nhập bên trong. HorizontalScrollView dùng cho chiều ngang, còn LinearLayout tự nó không cung cấp cuộn.", "references": [{"url": "https://developer.android.com/reference/android/widget/ScrollView", "title": "ScrollView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-19", "text": "If you activity has the name: SampleActivity, what is the name of the binding class which is\ngenerated automatically by Android when you configure your application as data binding enable?", "type": "single", "options": [{"id": "A", "text": "sample_activity_binding"}, {"id": "B", "text": "ActivitySampleBinding"}, {"id": "C", "text": "activity_sample_binding"}, {"id": "D", "text": "SampleActivityBinding"}], "answers": [], "source": {"term": "20231", "pages": [6], "number": 19, "code": "eeb70a"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Tên lớp binding được suy ra từ tên file layout, không phải tên Activity. activity_sample.xml tạo ActivitySampleBinding; sample_activity.xml tạo SampleActivityBinding. Vì đề chỉ cho SampleActivity mà không cho file XML nên không đủ dữ kiện để chọn giữa hai lớp binding này.", "references": [{"url": "https://developer.android.com/topic/libraries/data-binding/generated-binding", "title": "Lớp binding sinh tự động"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-20", "text": "Which of following components belong to android native library?\n1) Webkit\n2) OpenGL\n3) SQLite\n4) Dalvik\n5) OpenUI", "type": "single", "options": [{"id": "A", "text": "1,3,4"}, {"id": "B", "text": "1,2,3"}, {"id": "C", "text": "1,2,5"}, {"id": "D", "text": "3,4,5"}], "answers": ["B"], "source": {"term": "20231", "pages": [6], "number": 20, "code": "8401ed"}, "plain": true, "explanation": "Theo mô hình kiến trúc Android truyền thống của đề, OpenGL ES, SQLite và các thư viện web thuộc nhóm thư viện native. Dalvik là máy ảo thực thi bytecode, không phải một thư viện native trong cách phân lớp này; Android hiện đại dùng ART. OpenUI không phải thành phần chuẩn trong danh sách được hỏi.", "references": [{"url": "https://source.android.com/docs/core/architecture", "title": "Kiến trúc Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-21", "text": "To make the EditText allows password characters (e.g., display * instead of the real character), you have to set the value of the inputType property as (type your answer with case sensitive) ___", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [7], "number": 21, "code": "b9bc89"}, "fields": [["textPassword"]], "plain": true, "explanation": "Giá trị XML cần điền là textPassword, ví dụ android:inputType=\"textPassword\". Nó cấu hình kiểu nhập văn bản mật khẩu và cách che ký tự; numberPassword dùng cho mật khẩu dạng số. Che ký tự trên màn hình không đồng nghĩa với mã hóa hay lưu mật khẩu an toàn.", "references": [{"url": "https://developer.android.com/develop/ui/views/touch-and-input/keyboard-input/style", "title": "Kiểu nhập liệu"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-22", "text": "The 'when' statement in Kotlin is similar to which statement in other programming\nlanguages?", "type": "single", "options": [{"id": "A", "text": "continue"}, {"id": "B", "text": "break"}, {"id": "C", "text": "switch"}, {"id": "D", "text": "if"}], "answers": ["C"], "source": {"term": "20231", "pages": [7], "number": 22, "code": "76c978"}, "plain": true, "explanation": "when là cấu trúc phân nhánh gần với switch trong Java, nhưng mạnh hơn: có thể kiểm tra khoảng, kiểu và dùng như biểu thức trả về giá trị. Nó không tự rơi xuống nhánh tiếp theo như switch kiểu cũ; không cần break để kết thúc mỗi nhánh.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Điều khiển luồng"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-23", "text": "What is the flexible point of Android devices compare to iOS ones?", "type": "single", "options": [{"id": "A", "text": "user data is more secured"}, {"id": "B", "text": "can connect to multiple peripheral devices such as mouse or keyboard"}, {"id": "C", "text": "backup and restore data easily with cloud services"}, {"id": "D", "text": "allow to install apps from third party sources (not from Google play store)"}], "answers": ["D"], "source": {"term": "20231", "pages": [7], "number": 23, "code": "15c61a"}, "note": "", "plain": true, "explanation": "Trong bối cảnh đề năm 2023, lựa chọn được hỏi là Android cho cài APK từ nguồn ngoài Google Play khi người dùng cho phép. Đây không phải khẳng định Android luôn bảo mật hơn iOS hoặc iOS không bao giờ có phân phối ngoài cửa hàng trong mọi khu vực/thời điểm. Cài từ nguồn ngoài cũng đòi hỏi đánh giá độ tin cậy của ứng dụng.", "references": [{"url": "https://developer.android.com/distribute/marketing-tools/alternative-distribution", "title": "Phân phối ứng dụng ngoài Google Play"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-24", "text": "If you override onCreateOptionMenu callback in your activity, which menu are you going to\ncreate?", "type": "single", "options": [{"id": "A", "text": "Popup Menu"}, {"id": "B", "text": "ActionBar Menu"}, {"id": "C", "text": "Context Menu"}, {"id": "D", "text": "Navigation Drawer Menu"}], "answers": ["B"], "source": {"term": "20231", "pages": [7], "number": 24, "code": "Obcca0"}, "plain": true, "explanation": "Callback đúng tên là onCreateOptionsMenu(), dùng để tạo options menu, thường hiển thị trên app bar/action bar hoặc overflow. Context menu gắn với ngữ cảnh của một view; popup menu neo vào một view. Đề viết thiếu chữ s trong tên callback nhưng ý hỏi là options menu.", "references": [{"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-25", "text": "Suppose we have an image named \"mobile.png\" in the res/drawable folder, and we have an\nImageView in the activity layout, which method could be used to set the image source for\nthe ImageView as the image mobile.png", "type": "single", "options": [{"id": "A", "text": "setImageResource(R.id.mobile)"}, {"id": "B", "text": "setImageResource(R.drawable.mobile)"}, {"id": "C", "text": "setImageDrawable(R.drawable.mobile)"}, {"id": "D", "text": "setImageResource(R.drawable.mobile.png)"}], "answers": ["B"], "source": {"term": "20231", "pages": [8], "number": 25, "code": "65acb4"}, "plain": true, "explanation": "setImageResource(R.drawable.mobile) nhận ID tài nguyên drawable dạng số nguyên. Không thêm đuôi .png trong R.drawable.mobile. R.id.mobile là ID view, còn setImageDrawable() cần một đối tượng Drawable, không nhận trực tiếp số ID tài nguyên như phương án trong đề.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-26", "text": "Which of the following are true about abstract classes?", "type": "multi", "options": [{"id": "A", "text": "They can be extended by subclasses and implementations can be provided for abstract members of the class."}, {"id": "B", "text": "They have an implementation for all of their properties and functions."}, {"id": "C", "text": "They may have abstract properties or abstract functions."}, {"id": "D", "text": "They can be instantiated"}, {"id": "E", "text": "They are not fully implemented and cannot be instantiated."}, {"id": "F", "text": "They need to be marked with the open keyword to be extended."}], "answers": ["A", "C"], "source": {"term": "20231", "pages": [8], "number": 26, "code": "716dd3"}, "note": "", "plain": true, "explanation": "Theo nghĩa chặt của các phát biểu, chọn các ý: lớp con có thể kế thừa và triển khai thành viên abstract; lớp abstract có thể khai báo thuộc tính hoặc hàm abstract. Lớp abstract không khởi tạo trực tiếp và tự cho phép kế thừa, không cần open. Phương án ghép “not fully implemented and cannot be instantiated” quá mạnh: một lớp abstract có thể không có thành viên abstract, nên phần “not fully implemented” không luôn đúng.", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-27", "text": "Given following code, select the correct:\nval address = ___.parse(\"https://soict.hust.edu.vn\")\nval intent: Intent = Intent(Intent.ACTION_VIEW, ___)\nstartActivity(intent)", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [8], "number": 27, "code": "64fbf3"}, "note": "", "fields": [["Uri"], ["address"]], "plain": true, "explanation": "Hai chỗ trống lần lượt là Uri và address: Uri.parse(...) biến URL thành Uri; Intent(Intent.ACTION_VIEW, address) yêu cầu mở địa chỉ đó. Trong ứng dụng thực tế cần xử lý trường hợp không có Activity nhận Intent. Tên Uri phải viết đúng hoa/thường và biến address phải khớp biến đã khai báo.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-28", "text": "Fill in the blank\nThe ___ is called when you create an instance of a class.", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [9], "number": 28, "code": "7977ca"}, "fields": [["constructor"]], "plain": true, "explanation": "Constructor được dùng khi tạo instance của lớp và khởi tạo các giá trị cần thiết. Kotlin có primary constructor và có thể có secondary constructor; các khối init cũng chạy trong quá trình khởi tạo. Đây không phải lời gọi một phương thức Activity như onCreate().", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-29", "text": "Which activity lifecycle method would be called if a dialog appears onscreen, partially\nobscuring an activity?", "type": "single", "options": [{"id": "A", "text": "onDestroy because the activity does not need to exist so long as it doesn't have focus."}, {"id": "B", "text": "onStop) because the activity does not need to respond to user input while the dialog is onscreen."}, {"id": "C", "text": "onResume) because the activity needed to respond to user input to display the dialog."}, {"id": "D", "text": "onPause) because the activity is still displayed, but no longer has focus."}], "answers": [], "source": {"term": "20231", "pages": [9], "number": 29, "code": "311261"}, "plain": true, "explanation": "Đáp án onPause() chỉ đúng khi một Activity khác, chẳng hạn Activity có giao diện dạng dialog, mở lên và làm Activity hiện tại mất trạng thái resumed trong mô hình của đề. Dialog hoặc DialogFragment hiển thị ngay trong chính Activity không mặc nhiên gọi onPause() của Activity. Câu hỏi không phân biệt hai trường hợp nên không chấm một đáp án bắt buộc.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích."}, {"id": "20231-1-30", "text": "Both Toast and Logcat can be used to debug the program, which expression bellow is\nwrong?", "type": "single", "options": [{"id": "A", "text": "Toast displays information at device while Logcat displays information at the host"}, {"id": "B", "text": "Logcat only display information that developer logs out"}, {"id": "C", "text": "Logcat can not be shown on computer without connection between the computer and the Android device"}, {"id": "D", "text": "Toast can be used to display some guidelines for user"}], "answers": ["B"], "source": {"term": "20231", "pages": [9], "number": 30, "code": "5421c"}, "plain": true, "explanation": "Logcat hiển thị log từ ứng dụng và hệ thống trên máy phát triển, có thể lọc theo tag, package và mức độ. Nó không chỉ chứa các dòng do lập trình viên tự ghi. Toast là thông báo ngắn trên thiết bị. “Cần kết nối” ở đây bao gồm thiết bị/emulator đang kết nối; file log đã lưu vẫn có thể xem về sau.", "references": [{"url": "https://developer.android.com/studio/debug/logcat", "title": "Logcat"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-31", "text": "Which kind of menu will be opened if user presses and hold for a while?", "type": "single", "options": [{"id": "A", "text": "Instant Menu"}, {"id": "B", "text": "Context Menu"}, {"id": "C", "text": "Drawer Menu"}, {"id": "D", "text": "Option Menu"}], "answers": ["B"], "source": {"term": "20231", "pages": [9, 10], "number": 31, "code": "6300"}, "plain": true, "explanation": "Context menu thường mở khi người dùng nhấn giữ một view đã đăng ký context menu. Options menu nằm trên app bar/overflow; navigation drawer là ngăn điều hướng. Nhấn giữ không tự động sinh context menu cho mọi view: ứng dụng cần cấu hình hành vi này.", "references": [{"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-32", "text": "Where to configure the home activity - the first activity to be run in your application?", "type": "single", "options": [{"id": "A", "text": "in the AndroidManifest.xml"}, {"id": "B", "text": "in the project level gradle file"}, {"id": "C", "text": "in the MainActivity.kt"}, {"id": "D", "text": "in the module level gradle file"}], "answers": ["A"], "source": {"term": "20231", "pages": [10], "number": 32, "code": "f2e"}, "plain": true, "explanation": "Activity khởi chạy từ biểu tượng ứng dụng được khai báo trong AndroidManifest.xml với intent-filter kết hợp android.intent.action.MAIN và android.intent.category.LAUNCHER. MainActivity.kt chứa mã thực thi, còn Gradle cấu hình build; chúng không thay thế khai báo launcher component trong manifest.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-33", "text": "What is the language to program Android natively (select all correct answers)?", "type": "multi", "options": [{"id": "A", "text": "Java"}, {"id": "B", "text": "HTML, CSS, Javascript"}, {"id": "C", "text": "Kotlin"}, {"id": "D", "text": "C/C++"}], "answers": ["A", "C", "D"], "source": {"term": "20231", "pages": [10], "number": 33, "code": "45"}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-34", "text": "What are lambdas in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A lambda is an expression that describes a function. But instead of declaring a named function, you declare a function that has no name"}, {"id": "B", "text": "A lambda is a Class type in Kotlin"}, {"id": "C", "text": "A lambda is an Interface in Kotlin"}, {"id": "D", "text": "A lambda is a Data Type in Kotlin"}], "answers": ["A"], "source": {"term": "20231", "pages": [10], "number": 34, "code": "3"}, "plain": true, "explanation": "Lambda là biểu thức mô tả một hàm không có tên, ví dụ { x: Int -> x * 2 }. Có thể lưu nó trong biến kiểu hàm hoặc truyền làm đối số cho hàm bậc cao. Khi chỉ có một tham số và suy ra được kiểu, Kotlin cho phép dùng tên ngầm định it.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-35", "text": "True or False: onCreateView is only called once for a fragment's entire lifecycle?", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["B"], "source": {"term": "20231", "pages": [11], "number": 35, "code": "70431a"}, "plain": true, "explanation": "Sai: vòng đời view của Fragment tách biệt vòng đời bản thân Fragment. View có thể bị hủy trong onDestroyView() rồi tạo lại, khiến onCreateView() được gọi nhiều lần trên cùng một Fragment. Cần tránh giữ tham chiếu binding của view cũ sau onDestroyView().", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-36", "text": "Which of the following is true about Gradle?", "type": "multi", "options": [{"id": "A", "text": "Gradle is an automated build system used by Android Studio to build your apps."}, {"id": "B", "text": "Gradle handles installing your app on a device"}, {"id": "C", "text": "Your app's build.gradle file is written in XML."}, {"id": "D", "text": "You can configure Android-specific options for your project in your app's build. gradle file."}, {"id": "E", "text": "The gradle configuration for your project cannot change after you initially create the project."}], "answers": ["A", "B", "D"], "source": {"term": "20231", "pages": [11], "number": 36, "code": "5775e0"}, "plain": true, "explanation": "Gradle tự động hóa build Android và có các task như installDebug để cài bản debug lên thiết bị phù hợp. build.gradle dùng Groovy DSL; build.gradle.kts dùng Kotlin DSL, không phải XML. Cấu hình module chứa các tùy chọn Android và dependencies, và có thể chỉnh sửa sau khi tạo dự án.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-37", "text": "Which of the following statements about app icons are true?", "type": "multi", "options": [{"id": "A", "text": "It is sufficient to provide a single bitmap image of your app icon in your project to make it appear high quality on a range of Android devices."}, {"id": "B", "text": "mdpi, hdpi, xhdpi, xxhdpi, and xxxhdpi are density qualifiers for resource directories to indicate that these are resources to be used on devices with a specific screen density."}, {"id": "C", "text": "Adaptive icons are made up of a foreground and background layer, and an OEM mask will be applied on top of them."}, {"id": "D", "text": "Vector drawables only work for a certain screen density and should not be scaled."}], "answers": ["B", "C"], "source": {"term": "20231", "pages": [11], "number": 37, "code": "167926"}, "plain": true, "explanation": "Nhóm mật độ đúng là mdpi, hdpi, xhdpi, xxhdpi, xxxhdpi; “dpi” đứng riêng trong bản OCR là lỗi mất chữ x. Adaptive icon có các lớp foreground/background và có thể được launcher áp mặt nạ; thiết bị mới còn hỗ trợ lớp monochrome. Bitmap cần xét mật độ màn hình, còn vector có thể co giãn. Phương án đã được sửa lỗi OCR trước khi chấm các ý về mật độ và lớp adaptive icon.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}, {"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-38", "text": "What is the advantage of Android development environment compare to iOS development\nenvironment?", "type": "multi", "options": [{"id": "A", "text": "the Ul experience is better"}, {"id": "B", "text": "can develop app on several operating systems"}, {"id": "C", "text": "easier to test on real devices"}, {"id": "D", "text": "can use several IDEs for app development"}], "answers": [], "source": {"term": "20231", "pages": [11, 12], "number": 38, "code": "da12a7"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Android Studio chạy trên nhiều hệ điều hành máy tính, nên đây là một ưu điểm khách quan có thể kiểm chứng. Tuy nhiên “dễ thử thiết bị”, “dễ tiếp cận người dùng” hay trải nghiệm UI tốt hơn là so sánh phụ thuộc tiêu chí. Đề không nêu đủ tiêu chí và có thể có nhiều nhận định phù hợp; giữ câu để học kiến thức nhưng không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-39", "text": "Which of the following is not a challange for Android application development?", "type": "single", "options": [{"id": "A", "text": "The deverloper may have to use different development tools in different OS"}, {"id": "B", "text": "The application must have compatibility with several different versions of Android"}, {"id": "C", "text": "The application mus be designed for multiple resolutions"}, {"id": "D", "text": "Source code and user's data must be secured"}], "answers": ["A"], "source": {"term": "20231", "pages": [12], "number": 39, "code": "53c0b3"}, "plain": true, "explanation": "Android Studio có bản cho nhiều hệ điều hành máy tính; việc bắt buộc dùng các công cụ khác nhau theo hệ điều hành, hoặc chỉ được lập trình trên một hệ điều hành, không phải hạn chế Android trong đề. Tương thích phiên bản Android, kích thước/độ phân giải màn hình và bảo vệ dữ liệu đều là các vấn đề thực tế cần xử lý.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-40", "text": "Why use the Material Components for Android library?", "type": "multi", "options": [{"id": "A", "text": "It provides widgets that follow the Material Design guidelines such as text fields and switches."}, {"id": "B", "text": "It makes your code compile faster."}, {"id": "C", "text": "It provides default Material themes that you can use directly or extend and then customize."}, {"id": "D", "text": "It automatically suggests ways for your app to look better."}, {"id": "E", "text": "It helps you more quickly build beautiful user experiences."}], "answers": ["A", "C", "E"], "source": {"term": "20231", "pages": [12], "number": 40, "code": "729666"}, "plain": true, "explanation": "Material Components cung cấp widget và theme theo Material Design, giúp triển khai giao diện nhất quán và tùy biến màu, hình dạng, kiểu chữ. Thư viện không bảo đảm biên dịch nhanh hơn và không tự động thiết kế lại giao diện cho bạn. Câu này nói về thư viện Material cho hệ View, cần phân biệt với các composable Material trong Compose.", "references": [{"url": "https://github.com/material-components/material-components-android/blob/master/docs/getting-started.md", "title": "Material Components for Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-41", "text": "What are correct callback functions of Android activity life cycle?", "type": "single", "options": [{"id": "A", "text": "onCreate(), onInit(), onStart(), onPause(), onStop(), onDestroy(), onResume()"}, {"id": "B", "text": "onCreate(), onStart(), onResume(), onPause(), onStop(), onRestart(), onDestroy()"}, {"id": "C", "text": "onCreate(), onStart(), onPause(), onResume(), onFinish(), onStop(), onDestroy()"}, {"id": "D", "text": "onCreate(), onStart(), onActivityStarted(), onResume(), onPause(), onStop(), onActivityDestroy(), onDestroy()"}], "answers": ["B"], "source": {"term": "20231", "pages": [12], "number": 41, "code": "9f8f5el"}, "plain": true, "explanation": "Các callback trong lựa chọn đúng là onCreate, onStart, onResume, onPause, onStop, onRestart và onDestroy. onRestart dùng khi Activity đã stopped quay lại. Danh sách trong đáp án là tập callback, không phải thứ tự chạy từ trái sang phải; onInit, onFinish và onActivityDestroy không thuộc tập callback Activity chuẩn đó.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-42", "text": "What is the purpose of implicit intent?", "type": "single", "options": [{"id": "A", "text": "to close an activity in other application"}, {"id": "B", "text": "to open an service in current application"}, {"id": "C", "text": "to open an activity in other application"}, {"id": "D", "text": "to open an activity in current application"}], "answers": [], "source": {"term": "20231", "pages": [13], "number": 42, "code": "869042"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Implicit intent mô tả action/data mà không chỉ định lớp đích. Android tìm component phù hợp theo intent-filter, có thể ở cùng ứng dụng hoặc ứng dụng khác. Vì C và D đều có thể xảy ra trong khi đề yêu cầu một lựa chọn nên không chấm ép C; để mở màn hình nội bộ xác định, explicit intent thường phù hợp hơn.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-1-43", "text": "The (fill in the blank with case sensitive) ___ method needs to be overridden in the host activity to ensure your app’s fragment-based navigation responds to the app’s \"Up\" button?", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [13], "number": 43, "code": "17dc5e"}, "fields": [["onSupportNavigateUp", "onSupportNavigateUp()"]], "plain": true, "explanation": "Trong Activity dùng Navigation Component với app bar, ghi đè onSupportNavigateUp() và gọi NavController.navigateUp(appBarConfiguration), có thể fallback về super. Đây là xử lý nút Up trên app bar, khác với thao tác Back của hệ thống. Tên hàm cần điền là onSupportNavigateUp.", "references": [{"url": "https://developer.android.com/guide/navigation/integrations/ui#appbarconfiguration", "title": "NavigationUI · Nút Up"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-44", "text": "How to shutdown/finish an activity?", "type": "single", "options": [{"id": "A", "text": "destroy()"}, {"id": "B", "text": "finish()"}, {"id": "C", "text": "dispose()"}, {"id": "D", "text": "finishActivity()"}], "answers": ["B"], "source": {"term": "20231", "pages": [13], "number": 44, "code": "0d0692"}, "plain": true, "explanation": "finish() yêu cầu kết thúc Activity hiện tại. Không gọi trực tiếp onDestroy(); hệ thống quản lý các callback vòng đời. finishActivity(requestCode) là API khác dành cho Activity con đã mở theo requestCode, không thay thế finish() trong câu hỏi này.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-1-45", "text": "Given following code:\nval intent = Intent([ ], Uri.parse(\"123456789\"))\nintent.putExtra(\"sms_body\", \"hello\")\nstartActivity(intent)\nwhat could be filled in the [ ]?", "type": "single", "options": [{"id": "A", "text": "Intent.ACTION_SEND_SMS"}, {"id": "B", "text": "Intent.ACTION_SEND"}, {"id": "C", "text": "Intent.ACTION_SEND_MULTIPLE"}, {"id": "D", "text": "Intent.ACTION_SENDTO"}], "answers": [], "source": {"term": "20231", "pages": [13, 14], "number": 45, "code": "0f1c53"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Để mở ứng dụng nhắn SMS, dùng ACTION_SENDTO cùng Uri có scheme smsto:, ví dụ Uri.parse(\"smsto:123456789\"), rồi thêm sms_body. Chuỗi \"123456789\" trong đề thiếu scheme nên không bảo đảm tìm được ứng dụng xử lý. ACTION_SENDTO là ý định của câu hỏi, nhưng nguyên đoạn code chưa đủ đúng nên không dùng làm câu chấm điểm.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}]}, {"number": 2, "title": "20231 · Lượt 2 (tr. 15–27)", "questions": [{"id": "20231-2-1", "text": "What is the intent action to open a web page?", "type": "single", "options": [{"id": "A", "text": "Intent.ACTION_ACCESS_INTERNET"}, {"id": "B", "text": "Intent.ACTION_WEB_VIEW"}, {"id": "C", "text": "Intent.ACTION_MAIN"}, {"id": "D", "text": "Intent.ACTION_GET_CONTENT"}, {"id": "E", "text": "Intent.ACTION_VIEW"}], "answers": ["E"], "source": {"term": "20231", "pages": [15], "number": 1, "code": "674b3e"}, "note": "", "plain": true, "explanation": "Mở trang web bằng Intent.ACTION_VIEW cùng Uri http:// hoặc https://. ACTION_GET_CONTENT yêu cầu người dùng chọn dữ liệu, còn ACTION_MAIN mô tả điểm vào chính chứ không mở URL cụ thể. Một số bản OCR làm mất dấu gạch dưới hoặc dính lựa chọn; chỉ bản có lựa chọn đọc được rõ mới được chấm.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-2", "text": "Which of following is wrong about implicit intent?", "type": "single", "options": [{"id": "A", "text": "To call implicit, you have to know the class name of the destination activity"}, {"id": "B", "text": "Android runtime will open the app chooser if there exists more than one candidate for the implicit intent"}, {"id": "C", "text": "Android runtime receive the requests and try to find the matched application"}, {"id": "D", "text": "Android runtime keeps list of application registering to run the implicit intent"}], "answers": [], "source": {"term": "20231", "pages": [15], "number": 2, "code": "865ffe"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Implicit intent không cần biết tên lớp Activity đích, nên nhận định yêu cầu tên lớp là sai. Nhưng nhận định “có nhiều ứng dụng phù hợp thì luôn hiện chooser” cũng không đúng tuyệt đối: có thể đã có ứng dụng mặc định. Đề yêu cầu một lựa chọn trong khi có hơn một ý sai, và một bản OCR còn dính lựa chọn vào câu hỏi; không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-3", "text": "An activity contains the following code in onCreate(). What will happen when this code is\nexecuted, if the intent property is null?\nval message = intent.extras?.getString(\"message\").toString()", "type": "single", "options": [{"id": "A", "text": "The app will not crash because the extras property is accessed safely using?."}, {"id": "B", "text": "The app will crash because it attempted to access a null object."}, {"id": "C", "text": "The app will not crash because the extras property is accessed unsafely using?."}, {"id": "D", "text": "The app will crash because it attempted to access the extras property on a null object."}], "answers": [], "source": {"term": "20231", "pages": [15], "number": 3, "code": "f1db78"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Nếu intent thực sự null như giả thiết, intent.extras truy cập receiver null trước khi gặp dấu ?. nên có thể lỗi. Muốn bảo vệ cả chuỗi phải dùng intent?.extras?.getString(\"message\"). toString() trên giá trị nullable có thể tạo chuỗi \"null\". Hai lựa chọn mô tả crash trong đề trùng nghĩa, nên không chấm ép một lựa chọn.", "references": [{"url": "https://kotlinlang.org/docs/null-safety.html", "title": "Kotlin · Null safety"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-4", "text": "What is the purpose of implicit intent?", "type": "single", "options": [{"id": "A", "text": "to close an activity in other application"}, {"id": "B", "text": "to open an service in current application"}, {"id": "C", "text": "to open an activity in other application"}, {"id": "D", "text": "to open an activity in current application"}], "answers": [], "source": {"term": "20231", "pages": [16], "number": 4, "code": "f1d872"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Implicit intent mô tả action/data mà không chỉ định lớp đích. Android tìm component phù hợp theo intent-filter, có thể ở cùng ứng dụng hoặc ứng dụng khác. Vì C và D đều có thể xảy ra trong khi đề yêu cầu một lựa chọn nên không chấm ép C; để mở màn hình nội bộ xác định, explicit intent thường phù hợp hơn.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-5", "text": "Overdiding the callback onSavelnstanceState is not suitable in which situation?", "type": "single", "options": [{"id": "A", "text": "save some states of Activity and restore latter when there is a device configuration changed"}, {"id": "B", "text": "save some states of Activity and restore latter when user rotates the device screen"}, {"id": "C", "text": "save some states of Activity and restore latter when user changes the language of the device"}, {"id": "D", "text": "store data into SD card to permanently use latter"}], "answers": ["D"], "source": {"term": "20231", "pages": [16], "number": 5, "code": "3811af"}, "plain": true, "explanation": "onSaveInstanceState() lưu trạng thái UI nhỏ để tái tạo Activity, chẳng hạn sau khi xoay màn hình. Nó không thay thế cơ sở dữ liệu, file hay DataStore để lưu dữ liệu lâu dài, và không bảo đảm được gọi trong mọi tình huống đóng ứng dụng. Vì vậy lưu dữ liệu vĩnh viễn ra thẻ nhớ không phải mục đích phù hợp.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle#saras", "title": "Lưu và khôi phục trạng thái"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-6", "text": "Which is a possible way/language to develop Android application?", "type": "multi", "options": [{"id": "A", "text": "Native approach: Java/Kotlin"}, {"id": "B", "text": "Web-based approach"}, {"id": "C", "text": "Universal Windows Platform (UWP) approach"}, {"id": "D", "text": "Object C"}, {"id": "E", "text": "Flutter"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [16], "number": 6, "code": "7df36e"}, "plain": true, "explanation": "Java/Kotlin là hướng native thông dụng; giao diện web có thể được đóng gói hoặc tích hợp qua WebView; Flutter cũng hỗ trợ xuất ứng dụng Android. UWP là nền tảng của Microsoft, còn Objective-C không phải lựa chọn Android native được hỏi ở đây. Các phương án đúng mô tả nhiều hướng phát triển, không chỉ một ngôn ngữ.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}, {"url": "https://developer.android.com/develop/ui/views/layout/webapps/webview", "title": "WebView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-7", "text": "Which of the following are true about abstract classes?", "type": "multi", "options": [{"id": "A", "text": "They can be extended by subclasses and implementations can be provided for abstract members of the class."}, {"id": "B", "text": "They have an implementation for all of their properties and functions."}, {"id": "C", "text": "They may have abstract properties or abstract functions."}, {"id": "D", "text": "They can be instantiated"}, {"id": "E", "text": "They are not fully implemented and cannot be instantiated."}, {"id": "F", "text": "They need to be marked with the open keyword to be extended."}], "answers": ["A", "C"], "source": {"term": "20231", "pages": [17], "number": 7, "code": "85f45a"}, "note": "", "plain": true, "explanation": "Theo nghĩa chặt của các phát biểu, chọn các ý: lớp con có thể kế thừa và triển khai thành viên abstract; lớp abstract có thể khai báo thuộc tính hoặc hàm abstract. Lớp abstract không khởi tạo trực tiếp và tự cho phép kế thừa, không cần open. Phương án ghép “not fully implemented and cannot be instantiated” quá mạnh: một lớp abstract có thể không có thành viên abstract, nên phần “not fully implemented” không luôn đúng.", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-8", "text": "Both Toast and Logcat can be used to debug the program, which expression bellow is\nwrong?", "type": "single", "options": [{"id": "A", "text": "Toast displays information at device while Logcat displays information at the host"}, {"id": "B", "text": "Logcat only display information that developer logs out"}, {"id": "C", "text": "Logcat can not be shown on computer without connection between the computer and the Android device"}, {"id": "D", "text": "Toast can be used to display some guidelines for user"}], "answers": ["B"], "source": {"term": "20231", "pages": [17], "number": 8, "code": "2d341d"}, "plain": true, "explanation": "Logcat hiển thị log từ ứng dụng và hệ thống trên máy phát triển, có thể lọc theo tag, package và mức độ. Nó không chỉ chứa các dòng do lập trình viên tự ghi. Toast là thông báo ngắn trên thiết bị. “Cần kết nối” ở đây bao gồm thiết bị/emulator đang kết nối; file log đã lưu vẫn có thể xem về sau.", "references": [{"url": "https://developer.android.com/studio/debug/logcat", "title": "Logcat"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-9", "text": "Which of the following is a benefit of using fragments?", "type": "multi", "options": [{"id": "A", "text": "Navigation between fragments allows for more sophisticated user interface patterns, such as tab bars."}, {"id": "B", "text": "Using multiple fragments within an activity allows for an adaptive layout across multiple screen sizes."}, {"id": "C", "text": "The same fragments can be reused across multiple activities."}, {"id": "D", "text": "Fragment is more lightweight than ACtivity sothat we should use Fragment rather than"}], "answers": [], "source": {"term": "20231", "pages": [17], "number": 9, "code": "8293fe"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Fragment cho phép tái sử dụng phần giao diện, kết hợp nhiều phần trong layout thích ứng và tổ chức các luồng điều hướng. Các ý về điều hướng, layout thích ứng và tái sử dụng mô tả các lợi ích đó. Fragment không thay thế Activity trong mọi trường hợp. Vì phương án D bị cắt giữa câu ở bản đang có, chưa đủ thông tin để chấm toàn bộ câu nhiều lựa chọn.", "references": [{"url": "https://developer.android.com/guide/fragments", "title": "Fragment"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-10", "text": "What is the advantage of Android development environment compare to iOS development\nenvironment?", "type": "multi", "options": [{"id": "A", "text": "the Ul experience is better"}, {"id": "B", "text": "can develop app on several operating systems"}, {"id": "C", "text": "easier to test on real devices"}, {"id": "D", "text": "can use several IDEs for app development"}], "answers": [], "source": {"term": "20231", "pages": [17], "number": 10, "code": "a55108"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Android Studio chạy trên nhiều hệ điều hành máy tính, nên đây là một ưu điểm khách quan có thể kiểm chứng. Tuy nhiên “dễ thử thiết bị”, “dễ tiếp cận người dùng” hay trải nghiệm UI tốt hơn là so sánh phụ thuộc tiêu chí. Đề không nêu đủ tiêu chí và có thể có nhiều nhận định phù hợp; giữ câu để học kiến thức nhưng không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-11", "text": "Which of the following is true about Gradle?", "type": "multi", "options": [{"id": "A", "text": "Gradle is an automated build system used by Android Studio to build your apps."}, {"id": "B", "text": "Gradle handles installing your app on a device"}, {"id": "C", "text": "Your app's build.gradle file is written in XML."}, {"id": "D", "text": "You can configure Android-specific options for your project in your app's build. gradle file."}, {"id": "E", "text": "The gradle configuration for your project cannot change after you initially create the project."}], "answers": ["A", "B", "D"], "source": {"term": "20231", "pages": [18], "number": 11, "code": "b0491d"}, "plain": true, "explanation": "Gradle tự động hóa build Android và có các task như installDebug để cài bản debug lên thiết bị phù hợp. build.gradle dùng Groovy DSL; build.gradle.kts dùng Kotlin DSL, không phải XML. Cấu hình module chứa các tùy chọn Android và dependencies, và có thể chỉnh sửa sau khi tạo dự án.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-12", "text": "Which of the following statements about app icons are true?", "type": "multi", "options": [{"id": "A", "text": "It is sufficient to provide a single bitmap image of your app icon in your project to make it appear high quality on a range of Android devices."}, {"id": "B", "text": "mdpi, hdpi, xhdpi, xxhdpi, and xxxhdpi are density qualifiers for resource directories to indicate that these are resources to be used on devices with a specific screen density."}, {"id": "C", "text": "Adaptive icons are made up of a foreground and background layer, and an OEM mask will be applied on top of them."}, {"id": "D", "text": "Vector drawables only work for a certain screen density and should not be scaled."}], "answers": ["B", "C"], "source": {"term": "20231", "pages": [18], "number": 12, "code": "febc95"}, "plain": true, "explanation": "Nhóm mật độ đúng là mdpi, hdpi, xhdpi, xxhdpi, xxxhdpi; “dpi” đứng riêng trong bản OCR là lỗi mất chữ x. Adaptive icon có các lớp foreground/background và có thể được launcher áp mặt nạ; thiết bị mới còn hỗ trợ lớp monochrome. Bitmap cần xét mật độ màn hình, còn vector có thể co giãn. Phương án đã được sửa lỗi OCR trước khi chấm các ý về mật độ và lớp adaptive icon.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}, {"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-13", "text": "Suppose we have an image named \"mobile.png\" in the res/drawable folder, and we have an\nImageView in the activity layout, which method could be used to set the image source for\nthe ImageView as the image mobile.png", "type": "single", "options": [{"id": "A", "text": "setImageResource(R.id.mobile)"}, {"id": "B", "text": "setImageResource(R.drawable.mobile)"}, {"id": "C", "text": "setImageDrawable(R.drawable.mobile)"}, {"id": "D", "text": "setImageResource(R.drawable.mobile.png)"}], "answers": ["B"], "source": {"term": "20231", "pages": [18], "number": 13, "code": "8ba9db"}, "plain": true, "explanation": "setImageResource(R.drawable.mobile) nhận ID tài nguyên drawable dạng số nguyên. Không thêm đuôi .png trong R.drawable.mobile. R.id.mobile là ID view, còn setImageDrawable() cần một đối tượng Drawable, không nhận trực tiếp số ID tài nguyên như phương án trong đề.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-14", "text": "Which value of the property scaleType of the ImageView allows us to keep remaining the\naspect ratio (the image will not be croped)?", "type": "single", "options": [{"id": "A", "text": "centerinside"}, {"id": "B", "text": "fitXY"}, {"id": "C", "text": "centerCrop"}, {"id": "D", "text": "center"}], "answers": ["A"], "source": {"term": "20231", "pages": [18, 19], "number": 14, "code": "05bb2f"}, "note": "", "plain": true, "explanation": "centerInside giữ tỉ lệ và thu nhỏ ảnh khi cần để toàn bộ ảnh nằm trong vùng hiển thị. fitXY có thể kéo méo; centerCrop phủ kín vùng nhìn bằng cách cắt ảnh; center giữ kích thước gốc nên ảnh lớn có thể bị cắt. Tên XML chính xác là centerInside, phân biệt chữ hoa chữ thường.", "references": [{"url": "https://developer.android.com/reference/android/widget/ImageView.ScaleType", "title": "ImageView.ScaleType"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-15", "text": "Which of the following is not a challange for Android application development?", "type": "single", "options": [{"id": "A", "text": "The deverloper may have to use different development tools in different OS"}, {"id": "B", "text": "The application must have compatibility with several different versions of Android"}, {"id": "C", "text": "The application mus be designed for multiple resolutions"}, {"id": "D", "text": "Source code and user's data must be secured"}], "answers": ["A"], "source": {"term": "20231", "pages": [19], "number": 15, "code": "d7c1b1"}, "plain": true, "explanation": "Android Studio có bản cho nhiều hệ điều hành máy tính; việc bắt buộc dùng các công cụ khác nhau theo hệ điều hành, hoặc chỉ được lập trình trên một hệ điều hành, không phải hạn chế Android trong đề. Tương thích phiên bản Android, kích thước/độ phân giải màn hình và bảo vệ dữ liệu đều là các vấn đề thực tế cần xử lý.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-16", "text": "Which of the following tasks can be performed in onCreate()?", "type": "multi", "options": [{"id": "A", "text": "Configuring views, such as setting the layout manager of a recycler view"}, {"id": "B", "text": "Determining the items to be shown in the options menu."}, {"id": "C", "text": "Setting the onClickListener for items in the options menu."}, {"id": "D", "text": "Getting extras from the intent that launched the activity."}], "answers": ["A", "D"], "source": {"term": "20231", "pages": [19], "number": 16, "code": "c4ad85"}, "plain": true, "explanation": "Theo cách tổ chức vòng đời chuẩn, onCreate() khởi tạo view, cấu hình RecyclerView và đọc intent.extras. Options menu được tạo trong onCreateOptionsMenu(), còn thao tác chọn menu được xử lý qua onOptionsItemSelected() hoặc listener của MenuItem. Cụm “can be performed” trong đề được hiểu là nơi thích hợp theo quy ước, không phải giới hạn kỹ thuật tuyệt đối.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}, {"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-17", "text": "The (fill in the blank with case sensitive) ___ method needs to be overridden in the host activity to ensure your app’s fragment-based navigation responds to the app’s \"Up\" button?", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [19], "number": 17, "code": "aaga37"}, "fields": [["onSupportNavigateUp", "onSupportNavigateUp()"]], "plain": true, "explanation": "Trong Activity dùng Navigation Component với app bar, ghi đè onSupportNavigateUp() và gọi NavController.navigateUp(appBarConfiguration), có thể fallback về super. Đây là xử lý nút Up trên app bar, khác với thao tác Back của hệ thống. Tên hàm cần điền là onSupportNavigateUp.", "references": [{"url": "https://developer.android.com/guide/navigation/integrations/ui#appbarconfiguration", "title": "NavigationUI · Nút Up"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-18", "text": "The 'when' statement in Kotlin is similar to which statement in other programming\nlanguages?", "type": "single", "options": [{"id": "A", "text": "continue"}, {"id": "B", "text": "break"}, {"id": "C", "text": "switch"}, {"id": "D", "text": "if"}], "answers": ["C"], "source": {"term": "20231", "pages": [19], "number": 18, "code": "1e1bf6"}, "note": "", "plain": true, "explanation": "when là cấu trúc phân nhánh gần với switch trong Java, nhưng mạnh hơn: có thể kiểm tra khoảng, kiểu và dùng như biểu thức trả về giá trị. Nó không tự rơi xuống nhánh tiếp theo như switch kiểu cũ; không cần break để kết thúc mỗi nhánh.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Điều khiển luồng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-19", "text": "If you activity has the name: SampleActivity, what is the name of the binding class which is\ngenerated automatically by Android when you configure your application as data binding enable?", "type": "single", "options": [{"id": "A", "text": "sample_activity_binding"}, {"id": "B", "text": "ActivitySampleBinding"}, {"id": "C", "text": "activity_sample_binding"}, {"id": "D", "text": "SampleActivityBinding"}], "answers": [], "source": {"term": "20231", "pages": [20], "number": 19, "code": "226241"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Tên lớp binding được suy ra từ tên file layout, không phải tên Activity. activity_sample.xml tạo ActivitySampleBinding; sample_activity.xml tạo SampleActivityBinding. Vì đề chỉ cho SampleActivity mà không cho file XML nên không đủ dữ kiện để chọn giữa hai lớp binding này.", "references": [{"url": "https://developer.android.com/topic/libraries/data-binding/generated-binding", "title": "Lớp binding sinh tự động"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-20", "text": "The RadioGroup class is directly inherited from which class?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "RelativeLayout"}, {"id": "C", "text": "android.widget.view"}, {"id": "D", "text": "ConstrainLayout"}, {"id": "E", "text": "ViewGroup"}], "answers": ["A"], "source": {"term": "20231", "pages": [20], "number": 20, "code": "10afe5"}, "note": "", "plain": true, "explanation": "RadioGroup kế thừa trực tiếp android.widget.LinearLayout; LinearLayout tiếp tục kế thừa ViewGroup. Vì hỏi lớp cha trực tiếp nên chọn LinearLayout, không chọn ViewGroup. Điều này cũng giải thích tại sao RadioGroup có thuộc tính orientation để sắp nút ngang hoặc dọc.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-21", "text": "In the fragment lifecycle, which of the following tasks should be performed in\nonViewCreated() ?", "type": "multi", "options": [{"id": "A", "text": "Inflating the layout"}, {"id": "B", "text": "Binding view objects to properties in your fragment"}, {"id": "C", "text": "Configuring the options menu"}, {"id": "D", "text": "Setting properties of individual views, such as a recycler view's adapter"}], "answers": ["B", "D"], "source": {"term": "20231", "pages": [20], "number": 21, "code": "8e524e"}, "plain": true, "explanation": "onCreateView() tạo cây view; onViewCreated() được gọi sau khi cây view đã tồn tại. Vì vậy có thể lấy tham chiếu view, gắn dữ liệu và đặt adapter cho RecyclerView trong onViewCreated(). Không inflate layout lần nữa ở callback này; menu có cơ chế callback hoặc MenuProvider riêng.", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-22", "text": "If you override onCreateOptionMenu callback in your activity, which menu are you going to\ncreate?", "type": "single", "options": [{"id": "A", "text": "Popup Menu"}, {"id": "B", "text": "ActionBar Menu"}, {"id": "C", "text": "Context Menu"}, {"id": "D", "text": "Navigation Drawer Menu"}], "answers": ["B"], "source": {"term": "20231", "pages": [20, 21], "number": 22, "code": "a5de4f"}, "note": "", "plain": true, "explanation": "Callback đúng tên là onCreateOptionsMenu(), dùng để tạo options menu, thường hiển thị trên app bar/action bar hoặc overflow. Context menu gắn với ngữ cảnh của một view; popup menu neo vào một view. Đề viết thiếu chữ s trong tên callback nhưng ý hỏi là options menu.", "references": [{"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-23", "text": "Given following code, select the correct:\nval address = ___.parse(\"https://soict.hust.edu.vn\")\nval intent: Intent = Intent(Intent.ACTION_VIEW, ___)\nstartActivity(intent)", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [21], "number": 23, "code": "abf1d1"}, "note": "", "fields": [["Uri"], ["address"]], "plain": true, "explanation": "Hai chỗ trống lần lượt là Uri và address: Uri.parse(...) biến URL thành Uri; Intent(Intent.ACTION_VIEW, address) yêu cầu mở địa chỉ đó. Trong ứng dụng thực tế cần xử lý trường hợp không có Activity nhận Intent. Tên Uri phải viết đúng hoa/thường và biến address phải khớp biến đã khai báo.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-24", "text": "What is the language to program Android natively (select all correct answers)?", "type": "multi", "options": [{"id": "A", "text": "Java"}, {"id": "B", "text": "HTML, CSS, Javascript"}, {"id": "C", "text": "Kotlin"}, {"id": "D", "text": "C/C++"}], "answers": ["A", "C", "D"], "source": {"term": "20231", "pages": [21], "number": 24, "code": "d757ef"}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-25", "text": "Suppose we write an application to survey the hobby of people (there are 5 hobbies to be\nsurveyed), one person may have several hobbies. Which input controls is suitable for this\npurpose?", "type": "single", "options": [{"id": "A", "text": "RadioButton"}, {"id": "B", "text": "Recycler View"}, {"id": "C", "text": "DropDownList"}, {"id": "D", "text": "ListView"}, {"id": "E", "text": "Checkbox"}], "answers": ["E"], "source": {"term": "20231", "pages": [21], "number": 25, "code": "5268g6"}, "note": "", "plain": true, "explanation": "CheckBox cho phép chọn độc lập nhiều sở thích cùng lúc. RadioButton trong một RadioGroup chỉ cho một lựa chọn, phù hợp câu hỏi loại trừ lẫn nhau. Số lượng sở thích không quyết định widget; điều quyết định ở đây là người dùng được chọn nhiều mục.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-26", "text": "Fill in the blank\nThe ___ is called when you create an instance of a class.", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [22], "number": 26, "code": "ccbe41"}, "fields": [["constructor"]], "plain": true, "explanation": "Constructor được dùng khi tạo instance của lớp và khởi tạo các giá trị cần thiết. Kotlin có primary constructor và có thể có secondary constructor; các khối init cũng chạy trong quá trình khởi tạo. Đây không phải lời gọi một phương thức Activity như onCreate().", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-27", "text": "When is the current Activity reset, i.e., the onCreate callback is called again?", "type": "multi", "options": [{"id": "A", "text": "user rotates the phone"}, {"id": "B", "text": "user changes the language of the phone"}, {"id": "C", "text": "user presses the home button and opens another app"}, {"id": "D", "text": "the phone is going to out of battery"}], "answers": ["A", "B"], "source": {"term": "20231", "pages": [22], "number": 27, "code": "adfce"}, "plain": true, "explanation": "Theo hành vi mặc định, xoay màn hình hoặc đổi ngôn ngữ là thay đổi cấu hình và có thể làm Activity bị hủy rồi tạo lại, gọi lại onCreate(). Bấm Home thường chỉ đưa Activity về nền. Ngoại lệ: ứng dụng tự xử lý cấu hình qua configChanges hoặc hệ thống khôi phục sau khi tiến trình bị hủy; vì vậy các lựa chọn được chấm theo trường hợp mặc định của đề.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-28", "text": "Android typically takes name of some popular cakes to name the Android version.\nFrom which version, cakes' name is not taken for Android version?", "type": "single", "options": [{"id": "A", "text": "Android 11"}, {"id": "B", "text": "Android 9"}, {"id": "C", "text": "Android 10"}, {"id": "D", "text": "Android 8"}], "answers": ["C"], "source": {"term": "20231", "pages": [22], "number": 28, "code": "bd37a0"}, "note": "", "plain": true, "explanation": "Google chuyển cách gọi phiên bản công khai sang số bắt đầu từ Android 10, sau Android 9 Pie. Điều này không có nghĩa mọi tên mã nội bộ liên quan món tráng miệng đều biến mất. Một bản OCR có “Android 11” lẫn vào phần câu hỏi; bản đó được giữ để đối chiếu và không chấm.", "references": [{"url": "https://blog.google/products-and-platforms/platforms/android/evolving-android-brand/", "title": "Google · Tên Android 10"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-29", "text": "How to shutdown/finish an activity?", "type": "single", "options": [{"id": "A", "text": "destroy()"}, {"id": "B", "text": "finish()"}, {"id": "C", "text": "dispose()"}, {"id": "D", "text": "finishActivity()"}], "answers": ["B"], "source": {"term": "20231", "pages": [22], "number": 29, "code": "8faed3"}, "note": "", "plain": true, "explanation": "finish() yêu cầu kết thúc Activity hiện tại. Không gọi trực tiếp onDestroy(); hệ thống quản lý các callback vòng đời. finishActivity(requestCode) là API khác dành cho Activity con đã mở theo requestCode, không thay thế finish() trong câu hỏi này.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-30", "text": "Which widget view could be used to make a clickable object with image content?", "type": "multi", "options": [{"id": "A", "text": "Button"}, {"id": "B", "text": "ImageButton"}, {"id": "C", "text": "Image View"}, {"id": "D", "text": "Image"}, {"id": "E", "text": "TextView"}], "answers": [], "source": {"term": "20231", "pages": [23], "number": 30, "code": "e5a25"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "ImageButton là widget chuyên dùng cho nút có ảnh. Tuy nhiên ImageView cũng có thể nhận click listener, còn Button và TextView hỗ trợ compound drawable. Vì câu hỏi dùng “could be used” và không nói chỉ widget chuyên dụng nên có nhiều cách hiểu; không gán một đáp án duy nhất để chấm.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}, {"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}, {"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-31", "text": "If we have some buttons in one Activity, and all the buttons set the event onClickListener to\nthe Activity by calling setOnClickListener(this). So, in the callback function onClick of the\nActivity, how do you know which button is clicked?", "type": "single", "options": [{"id": "A", "text": "based on the order of buttons inside the xmi layout file"}, {"id": "B", "text": "based on the name of each button"}, {"id": "C", "text": "based on the position of each button"}, {"id": "D", "text": "based on the id of each button"}], "answers": ["D"], "source": {"term": "20231", "pages": [23], "number": 31, "code": "0c26"}, "plain": true, "explanation": "onClick nhận chính View đã phát sinh sự kiện. Dùng view.id rồi so sánh với R.id của từng nút để xác định nút được nhấn. Vị trí, thứ tự trong XML hay tên biến Kotlin không phải định danh sự kiện ổn định.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-32", "text": "Which is the direct parent class of the Button class?", "type": "single", "options": [{"id": "A", "text": "android.widget.View"}, {"id": "B", "text": "android.view.TextView"}, {"id": "C", "text": "android.view.View"}, {"id": "D", "text": "android.widget.TextView"}], "answers": ["D"], "source": {"term": "20231", "pages": [23], "number": 32, "code": "51f"}, "plain": true, "explanation": "android.widget.Button kế thừa trực tiếp android.widget.TextView. TextView lại kế thừa android.view.View. Chú ý cả tên lớp và package: android.view.TextView và android.widget.View trong các phương án là tên không đúng.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-33", "text": "Which of following components belong to android native library?\n1) Webkit\n2) OpenGL\n3) SQLite\n4) Dalvik\n5) OpenUI", "type": "single", "options": [{"id": "A", "text": "1,3,4"}, {"id": "B", "text": "1,2,3"}, {"id": "C", "text": "1,2,5"}, {"id": "D", "text": "3,4,5"}], "answers": ["B"], "source": {"term": "20231", "pages": [23, 24], "number": 33, "code": "c7"}, "note": "", "plain": true, "explanation": "Theo mô hình kiến trúc Android truyền thống của đề, OpenGL ES, SQLite và các thư viện web thuộc nhóm thư viện native. Dalvik là máy ảo thực thi bytecode, không phải một thư viện native trong cách phân lớp này; Android hiện đại dùng ART. OpenUI không phải thành phần chuẩn trong danh sách được hỏi.", "references": [{"url": "https://source.android.com/docs/core/architecture", "title": "Kiến trúc Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-34", "text": "What are correct callback functions of Android activity life cycle?", "type": "single", "options": [{"id": "A", "text": "onCreate(), onInit(), onStart(), onPause(), onStop(), onDestroy(), onResume()"}, {"id": "B", "text": "onCreate(), onStart(), onResume(), onPause(), onStop(), onRestart(), onDestroy()"}, {"id": "C", "text": "onCreate(), onStart(), onPause(), onResume(), onFinish(), onStop(), onDestroy()"}, {"id": "D", "text": "onCreate(), onStart(), onActivityStarted(), onResume(), onPause(), onStop(), onActivityDestroy(), onDestroy()"}], "answers": ["B"], "source": {"term": "20231", "pages": [24], "number": 34, "code": "7"}, "note": "", "plain": true, "explanation": "Các callback trong lựa chọn đúng là onCreate, onStart, onResume, onPause, onStop, onRestart và onDestroy. onRestart dùng khi Activity đã stopped quay lại. Danh sách trong đáp án là tập callback, không phải thứ tự chạy từ trái sang phải; onInit, onFinish và onActivityDestroy không thuộc tập callback Activity chuẩn đó.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-35", "text": "To make the EditText allows password characters (e.g., display * instead of the real character), you have to set the value of the inputType property as (type your answer with case sensitive) ___", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [24], "number": 35, "code": "955737"}, "fields": [["textPassword"]], "plain": true, "explanation": "Giá trị XML cần điền là textPassword, ví dụ android:inputType=\"textPassword\". Nó cấu hình kiểu nhập văn bản mật khẩu và cách che ký tự; numberPassword dùng cho mật khẩu dạng số. Che ký tự trên màn hình không đồng nghĩa với mã hóa hay lưu mật khẩu an toàn.", "references": [{"url": "https://developer.android.com/develop/ui/views/touch-and-input/keyboard-input/style", "title": "Kiểu nhập liệu"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-36", "text": "Why use the Material Components for Android library?", "type": "multi", "options": [{"id": "A", "text": "It provides widgets that follow the Material Design guidelines such as text fields and switches."}, {"id": "B", "text": "It makes your code compile faster."}, {"id": "C", "text": "It provides default Material themes that you can use directly or extend and then customize."}, {"id": "D", "text": "It automatically suggests ways for your app to look better."}, {"id": "E", "text": "It helps you more quickly build beautiful user experiences."}], "answers": ["A", "C", "E"], "source": {"term": "20231", "pages": [24, 25], "number": 36, "code": "30a624"}, "note": "", "plain": true, "explanation": "Material Components cung cấp widget và theme theo Material Design, giúp triển khai giao diện nhất quán và tùy biến màu, hình dạng, kiểu chữ. Thư viện không bảo đảm biên dịch nhanh hơn và không tự động thiết kế lại giao diện cho bạn. Câu này nói về thư viện Material cho hệ View, cần phân biệt với các composable Material trong Compose.", "references": [{"url": "https://github.com/material-components/material-components-android/blob/master/docs/getting-started.md", "title": "Material Components for Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-37", "text": "What is the flexible point of Android devices compare to iOS ones?", "type": "single", "options": [{"id": "A", "text": "user data is more secured"}, {"id": "B", "text": "can connect to multiple peripheral devices such as mouse or keyboard"}, {"id": "C", "text": "backup and restore data easily with cloud services"}, {"id": "D", "text": "allow to install apps from third party sources (not from Google play store)"}], "answers": ["D"], "source": {"term": "20231", "pages": [25], "number": 37, "code": "da65fd"}, "note": "", "plain": true, "explanation": "Trong bối cảnh đề năm 2023, lựa chọn được hỏi là Android cho cài APK từ nguồn ngoài Google Play khi người dùng cho phép. Đây không phải khẳng định Android luôn bảo mật hơn iOS hoặc iOS không bao giờ có phân phối ngoài cửa hàng trong mọi khu vực/thời điểm. Cài từ nguồn ngoài cũng đòi hỏi đánh giá độ tin cậy của ứng dụng.", "references": [{"url": "https://developer.android.com/distribute/marketing-tools/alternative-distribution", "title": "Phân phối ứng dụng ngoài Google Play"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-38", "text": "Which kind of menu will be opened if user presses and hold for a while?", "type": "single", "options": [{"id": "A", "text": "Instant Menu"}, {"id": "B", "text": "Context Menu"}, {"id": "C", "text": "Drawer Menu"}, {"id": "D", "text": "Option Menu"}], "answers": ["B"], "source": {"term": "20231", "pages": [25], "number": 38, "code": "1f9817"}, "plain": true, "explanation": "Context menu thường mở khi người dùng nhấn giữ một view đã đăng ký context menu. Options menu nằm trên app bar/overflow; navigation drawer là ngăn điều hướng. Nhấn giữ không tự động sinh context menu cho mọi view: ứng dụng cần cấu hình hành vi này.", "references": [{"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-39", "text": "Given following code:\nval intent = Intent([ ], Uri.parse(\"123456789\"))\nintent.putExtra(\"sms_body\", \"hello\")\nstartActivity(intent)\nwhat could be filled in the [ ]?", "type": "single", "options": [{"id": "A", "text": "Intent.ACTION_SEND_SMS"}, {"id": "B", "text": "Intent.ACTION_SEND"}, {"id": "C", "text": "Intent.ACTION_SEND_MULTIPLE"}, {"id": "D", "text": "Intent.ACTION_SENDTO"}], "answers": [], "source": {"term": "20231", "pages": [25], "number": 39}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Để mở ứng dụng nhắn SMS, dùng ACTION_SENDTO cùng Uri có scheme smsto:, ví dụ Uri.parse(\"smsto:123456789\"), rồi thêm sms_body. Chuỗi \"123456789\" trong đề thiếu scheme nên không bảo đảm tìm được ứng dụng xử lý. ACTION_SENDTO là ý định của câu hỏi, nhưng nguyên đoạn code chưa đủ đúng nên không dùng làm câu chấm điểm.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-40", "text": "True or False: onCreateView is only called once for a fragment's entire lifecycle?", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["B"], "source": {"term": "20231", "pages": [25], "number": 40, "code": "7ge844"}, "note": "", "plain": true, "explanation": "Sai: vòng đời view của Fragment tách biệt vòng đời bản thân Fragment. View có thể bị hủy trong onDestroyView() rồi tạo lại, khiến onCreateView() được gọi nhiều lần trên cùng một Fragment. Cần tránh giữ tham chiếu binding của view cũ sau onDestroyView().", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-41", "text": "What is the function to open new activity from the current activity?", "type": "single", "options": [{"id": "A", "text": "newActivity"}, {"id": "B", "text": "beginActivity"}, {"id": "C", "text": "startActivity"}, {"id": "D", "text": "openActivity"}], "answers": ["C"], "source": {"term": "20231", "pages": [26], "number": 41, "code": "21d578"}, "plain": true, "explanation": "startActivity(intent) yêu cầu Android mở Activity được Intent xác định hoặc phân giải. Với explicit intent có thể viết Intent(this, TargetActivity::class.java). Các tên newActivity(), beginActivity() và openActivity() không phải phương thức mở Activity chuẩn của ngữ cảnh này.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-42", "text": "The res folder does not include which following resources?", "type": "single", "options": [{"id": "A", "text": "file to define dependence libraries used in project"}, {"id": "B", "text": "file to define strings, colors used in project"}, {"id": "C", "text": "file to define demensions used in project"}, {"id": "D", "text": "file to define the menu structure used in project"}], "answers": ["A"], "source": {"term": "20231", "pages": [26], "number": 42, "code": "b3debb"}, "plain": true, "explanation": "res chứa layout, drawable, menu và các giá trị như strings, colors, dimens. Thư viện phụ thuộc được khai báo trong cấu hình Gradle của module, không phải một tài nguyên trong res.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}, {"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-43", "text": "What are lambdas in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A lambda is an expression that describes a function. But instead of declaring a named function, you declare a function that has no name"}, {"id": "B", "text": "A lambda is a Class type in Kotlin"}, {"id": "C", "text": "A lambda is an Interface in Kotlin"}, {"id": "D", "text": "A lambda is a Data Type in Kotlin"}], "answers": ["A"], "source": {"term": "20231", "pages": [26], "number": 43, "code": "28779a"}, "plain": true, "explanation": "Lambda là biểu thức mô tả một hàm không có tên, ví dụ { x: Int -> x * 2 }. Có thể lưu nó trong biến kiểu hàm hoặc truyền làm đối số cho hàm bậc cao. Khi chỉ có một tham số và suy ra được kiểu, Kotlin cho phép dùng tên ngầm định it.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-2-44", "text": "Where to configure the home activity - the first activity to be run in your application?", "type": "single", "options": [{"id": "A", "text": "in the AndroidManifest.xml"}, {"id": "B", "text": "in the project level gradle file"}, {"id": "C", "text": "in the MainActivity.kt"}, {"id": "D", "text": "in the module level gradle file"}], "answers": ["A"], "source": {"term": "20231", "pages": [26], "number": 44, "code": "a5ec76"}, "note": "", "plain": true, "explanation": "Activity khởi chạy từ biểu tượng ứng dụng được khai báo trong AndroidManifest.xml với intent-filter kết hợp android.intent.action.MAIN và android.intent.category.LAUNCHER. MainActivity.kt chứa mã thực thi, còn Gradle cấu hình build; chúng không thay thế khai báo launcher component trong manifest.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-2-45", "text": "What is the default return type of any functions defined in Kotlin?", "type": "single", "options": [{"id": "A", "text": "Unit"}, {"id": "B", "text": "Double"}, {"id": "C", "text": "void"}, {"id": "D", "text": "Int"}], "answers": ["A"], "source": {"term": "20231", "pages": [27], "number": 45, "code": "d453f0"}, "note": "", "plain": true, "explanation": "Unit là kiểu trả về mặc định của hàm có thân khối khi không khai báo kiểu trả về, ví dụ fun log() { println(\"Hi\") }. Đề dùng từ “any” quá rộng: hàm thân biểu thức như fun twice(x: Int) = x * 2 được suy ra kiểu Int. Kotlin dùng Unit thay cho cách viết void của Java.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10"}]}, {"number": 3, "title": "20231 · Lượt 3 (tr. 28–41)", "questions": [{"id": "20231-3-1", "text": "Given following code, select the correct:\nval address = ___.parse(\"https://soict.hust.edu.vn\")\nval intent: Intent = Intent(Intent.ACTION_VIEW, ___)\nstartActivity(intent)", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [28], "number": 1, "code": "a20abd"}, "note": "", "fields": [["Uri"], ["address"]], "plain": true, "explanation": "Hai chỗ trống lần lượt là Uri và address: Uri.parse(...) biến URL thành Uri; Intent(Intent.ACTION_VIEW, address) yêu cầu mở địa chỉ đó. Trong ứng dụng thực tế cần xử lý trường hợp không có Activity nhận Intent. Tên Uri phải viết đúng hoa/thường và biến address phải khớp biến đã khai báo.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-2", "text": "What is the flexible point of Android devices compare to iOS ones?", "type": "single", "options": [{"id": "A", "text": "user data is more secured"}, {"id": "B", "text": "can connect to multiple peripheral devices such as mouse or keyboard"}, {"id": "C", "text": "backup and restore data easily with cloud services"}, {"id": "D", "text": "allow to install apps from third party sources (not from Google play store)"}], "answers": ["D"], "source": {"term": "20231", "pages": [28], "number": 2, "code": "ffcfbo"}, "note": "", "plain": true, "explanation": "Trong bối cảnh đề năm 2023, lựa chọn được hỏi là Android cho cài APK từ nguồn ngoài Google Play khi người dùng cho phép. Đây không phải khẳng định Android luôn bảo mật hơn iOS hoặc iOS không bao giờ có phân phối ngoài cửa hàng trong mọi khu vực/thời điểm. Cài từ nguồn ngoài cũng đòi hỏi đánh giá độ tin cậy của ứng dụng.", "references": [{"url": "https://developer.android.com/distribute/marketing-tools/alternative-distribution", "title": "Phân phối ứng dụng ngoài Google Play"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-3", "text": "Both Toast and Logcat can be used to debug the program, which expression bellow is\nwrong?", "type": "single", "options": [{"id": "A", "text": "Toast displays information at device while Logcat displays information at the host"}, {"id": "B", "text": "Logcat only display information that developer logs out"}, {"id": "C", "text": "Logcat can not be shown on computer without connection between the computer and the Android device"}, {"id": "D", "text": "Toast can be used to display some guidelines for user"}], "answers": ["B"], "source": {"term": "20231", "pages": [28], "number": 3, "code": "39f3d7"}, "note": "", "plain": true, "explanation": "Logcat hiển thị log từ ứng dụng và hệ thống trên máy phát triển, có thể lọc theo tag, package và mức độ. Nó không chỉ chứa các dòng do lập trình viên tự ghi. Toast là thông báo ngắn trên thiết bị. “Cần kết nối” ở đây bao gồm thiết bị/emulator đang kết nối; file log đã lưu vẫn có thể xem về sau.", "references": [{"url": "https://developer.android.com/studio/debug/logcat", "title": "Logcat"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-4", "text": "In the fragment lifecycle, which of the following tasks should be performed in\nonView Created()?", "type": "multi", "options": [{"id": "A", "text": "Inflating the layou X"}, {"id": "B", "text": "Binding view objects to properties in your fragment"}, {"id": "C", "text": "Configuring the options menu X"}, {"id": "D", "text": "Setting properties of individual views, such as a recycler view's adapter"}], "answers": ["B", "D"], "source": {"term": "20231", "pages": [29], "number": 4, "code": "67bd35"}, "note": "", "plain": true, "explanation": "onCreateView() tạo cây view; onViewCreated() được gọi sau khi cây view đã tồn tại. Vì vậy có thể lấy tham chiếu view, gắn dữ liệu và đặt adapter cho RecyclerView trong onViewCreated(). Không inflate layout lần nữa ở callback này; menu có cơ chế callback hoặc MenuProvider riêng.", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-5", "text": "How to handle the event that user press the button and hold for a while?", "type": "single", "options": [{"id": "A", "text": "setLongClickListener"}, {"id": "B", "text": "setOnLongClickListener"}, {"id": "C", "text": "setOnClickListener"}, {"id": "D", "text": "setOnLongTouchListener"}], "answers": ["B"], "source": {"term": "20231", "pages": [29], "number": 5, "code": "0367d7"}, "note": "", "plain": true, "explanation": "Nhấn giữ được xử lý bằng setOnLongClickListener. onLongClick(view) trả về true nếu sự kiện đã được xử lý. setOnClickListener xử lý thao tác nhấn thông thường; các tên setLongClickListener và setOnLongTouchListener trong đề không phải API tương ứng.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-6", "text": "What is the default return type of any functions defined in Kotlin?", "type": "single", "options": [{"id": "A", "text": "Unit"}, {"id": "B", "text": "Double"}, {"id": "C", "text": "void"}, {"id": "D", "text": "Int"}], "answers": ["A"], "source": {"term": "20231", "pages": [29], "number": 6, "code": "4d1306"}, "plain": true, "explanation": "Unit là kiểu trả về mặc định của hàm có thân khối khi không khai báo kiểu trả về, ví dụ fun log() { println(\"Hi\") }. Đề dùng từ “any” quá rộng: hàm thân biểu thức như fun twice(x: Int) = x * 2 được suy ra kiểu Int. Kotlin dùng Unit thay cho cách viết void của Java.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-7", "text": "Suppose we have an image named \"mobile.png\" in the res/drawable folder, and we have an\nImageView in the activity layout, which method could be used to set the image source for\nthe ImageView as the image mobile.png", "type": "single", "options": [{"id": "A", "text": "setImageResource(R.id.mobile)"}, {"id": "B", "text": "setImageResource(R.drawable.mobile)"}, {"id": "C", "text": "setImageDrawable(R.drawable.mobile)"}, {"id": "D", "text": "setImageResource(R.drawable.mobile.png)"}], "answers": ["B"], "source": {"term": "20231", "pages": [29, 30], "number": 7}, "note": "", "plain": true, "explanation": "setImageResource(R.drawable.mobile) nhận ID tài nguyên drawable dạng số nguyên. Không thêm đuôi .png trong R.drawable.mobile. R.id.mobile là ID view, còn setImageDrawable() cần một đối tượng Drawable, không nhận trực tiếp số ID tài nguyên như phương án trong đề.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-8", "text": "To make the EditText allows password characters (e.g., display * instead of the real character), you have to set the value of the inputType property as (type your answer with case sensitive) ___", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [30], "number": 8, "code": "5fde63"}, "fields": [["textPassword"]], "plain": true, "explanation": "Giá trị XML cần điền là textPassword, ví dụ android:inputType=\"textPassword\". Nó cấu hình kiểu nhập văn bản mật khẩu và cách che ký tự; numberPassword dùng cho mật khẩu dạng số. Che ký tự trên màn hình không đồng nghĩa với mã hóa hay lưu mật khẩu an toàn.", "references": [{"url": "https://developer.android.com/develop/ui/views/touch-and-input/keyboard-input/style", "title": "Kiểu nhập liệu"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-9", "text": "If we have some buttons in one Activity, and all the buttons set the event onClickListener to\nthe Activity by calling setOnClickListener(this). So, in the callback function onClick of the\nActivity, how do you know which button is clicked?", "type": "single", "options": [{"id": "A", "text": "based on the order of buttons inside the xmi layout file"}, {"id": "B", "text": "based on the name of each button"}, {"id": "C", "text": "based on the position of each button"}, {"id": "D", "text": "based on the id of each button"}], "answers": ["D"], "source": {"term": "20231", "pages": [30], "number": 9, "code": "5747c4"}, "plain": true, "explanation": "onClick nhận chính View đã phát sinh sự kiện. Dùng view.id rồi so sánh với R.id của từng nút để xác định nút được nhấn. Vị trí, thứ tự trong XML hay tên biến Kotlin không phải định danh sự kiện ổn định.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-10", "text": "What is the advantage of Android development environment compare to iOS development\nenvironment?", "type": "multi", "options": [{"id": "A", "text": "the Ul experience is better"}, {"id": "B", "text": "can develop app on several operating systems"}, {"id": "C", "text": "easier to test on real devices"}, {"id": "D", "text": "can use several IDEs for app development"}], "answers": [], "source": {"term": "20231", "pages": [30], "number": 10, "code": "83ca4e"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Android Studio chạy trên nhiều hệ điều hành máy tính, nên đây là một ưu điểm khách quan có thể kiểm chứng. Tuy nhiên “dễ thử thiết bị”, “dễ tiếp cận người dùng” hay trải nghiệm UI tốt hơn là so sánh phụ thuộc tiêu chí. Đề không nêu đủ tiêu chí và có thể có nhiều nhận định phù hợp; giữ câu để học kiến thức nhưng không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-11", "text": "Given following code:\nval intent = Intent([ ], Uri.parse(\"123456789\"))\nintent.putExtra(\"sms_body\", \"hello\")\nstartActivity(intent)\nwhat could be filled in the [ ]?", "type": "single", "options": [{"id": "A", "text": "Intent.ACTION_SEND_SMS"}, {"id": "B", "text": "Intent.ACTION_SEND"}, {"id": "C", "text": "Intent.ACTION_SEND_MULTIPLE"}, {"id": "D", "text": "Intent.ACTION_SENDTO"}], "answers": [], "source": {"term": "20231", "pages": [31], "number": 11, "code": "cb/eft"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Để mở ứng dụng nhắn SMS, dùng ACTION_SENDTO cùng Uri có scheme smsto:, ví dụ Uri.parse(\"smsto:123456789\"), rồi thêm sms_body. Chuỗi \"123456789\" trong đề thiếu scheme nên không bảo đảm tìm được ứng dụng xử lý. ACTION_SENDTO là ý định của câu hỏi, nhưng nguyên đoạn code chưa đủ đúng nên không dùng làm câu chấm điểm.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-12", "text": "Which of following is wrong about implicit intent?\n6 To call implicit, you have to know the class name of the destination activity", "type": "single", "options": [{"id": "A", "text": "Android runtime will open the app chooser if there exists more than one candidate for the implicit intent"}, {"id": "B", "text": "Android runtime receive the requests and try to find the matched application"}, {"id": "C", "text": "Android runtime keeps list of application registering to run the implicit intent"}], "answers": [], "source": {"term": "20231", "pages": [31], "number": 12, "code": "594387"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Implicit intent không cần biết tên lớp Activity đích, nên nhận định yêu cầu tên lớp là sai. Nhưng nhận định “có nhiều ứng dụng phù hợp thì luôn hiện chooser” cũng không đúng tuyệt đối: có thể đã có ứng dụng mặc định. Đề yêu cầu một lựa chọn trong khi có hơn một ý sai, và một bản OCR còn dính lựa chọn vào câu hỏi; không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-13", "text": "Suppose we write an application to survey the hobby of people (there are 5 hobbies to be\nsurveyed), one person may have several hobbies. Which input controls is suitable for this\npurpose?", "type": "single", "options": [{"id": "A", "text": "RadioButton"}, {"id": "B", "text": "Recycler View"}, {"id": "C", "text": "DropDownList"}, {"id": "D", "text": "ListView"}, {"id": "E", "text": "Checkbox"}], "answers": ["E"], "source": {"term": "20231", "pages": [31, 32], "number": 13, "code": "8441de"}, "note": "", "plain": true, "explanation": "CheckBox cho phép chọn độc lập nhiều sở thích cùng lúc. RadioButton trong một RadioGroup chỉ cho một lựa chọn, phù hợp câu hỏi loại trừ lẫn nhau. Số lượng sở thích không quyết định widget; điều quyết định ở đây là người dùng được chọn nhiều mục.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-14", "text": "What is the purpose of implicit intent?", "type": "single", "options": [{"id": "A", "text": "to close an activity in other application"}, {"id": "B", "text": "to open an service in current application"}, {"id": "C", "text": "to open an activity in other application"}, {"id": "D", "text": "to open an activity in current application"}], "answers": [], "source": {"term": "20231", "pages": [31, 32], "number": 14}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Implicit intent mô tả action/data mà không chỉ định lớp đích. Android tìm component phù hợp theo intent-filter, có thể ở cùng ứng dụng hoặc ứng dụng khác. Vì C và D đều có thể xảy ra trong khi đề yêu cầu một lựa chọn nên không chấm ép C; để mở màn hình nội bộ xác định, explicit intent thường phù hợp hơn.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-15", "text": "Which activity lifecycle method would be called if a dialog appears onscreen, partially\nobscuring an activity?", "type": "single", "options": [{"id": "A", "text": "onDestroy because the activity does not need to exist so long as it doesn't have focus."}, {"id": "B", "text": "onStop) because the activity does not need to respond to user input while the dialog is onscreen."}, {"id": "C", "text": "onResume) because the activity needed to respond to user input to display the dialog."}, {"id": "D", "text": "onPause) because the activity is still displayed, but no longer has focus."}], "answers": [], "source": {"term": "20231", "pages": [32], "number": 15, "code": "191935"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Đáp án onPause() chỉ đúng khi một Activity khác, chẳng hạn Activity có giao diện dạng dialog, mở lên và làm Activity hiện tại mất trạng thái resumed trong mô hình của đề. Dialog hoặc DialogFragment hiển thị ngay trong chính Activity không mặc nhiên gọi onPause() của Activity. Câu hỏi không phân biệt hai trường hợp nên không chấm một đáp án bắt buộc.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-16", "text": "The (fill in the blank with case sensitive) ___ method needs to be overridden in the host activity to ensure your app’s fragment-based navigation responds to the app’s \"Up\" button?", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [32], "number": 16, "code": "a69a40"}, "fields": [["onSupportNavigateUp", "onSupportNavigateUp()"]], "plain": true, "explanation": "Trong Activity dùng Navigation Component với app bar, ghi đè onSupportNavigateUp() và gọi NavController.navigateUp(appBarConfiguration), có thể fallback về super. Đây là xử lý nút Up trên app bar, khác với thao tác Back của hệ thống. Tên hàm cần điền là onSupportNavigateUp.", "references": [{"url": "https://developer.android.com/guide/navigation/integrations/ui#appbarconfiguration", "title": "NavigationUI · Nút Up"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-17", "text": "Which widget view could be used to make a clickable object with image content?", "type": "multi", "options": [{"id": "A", "text": "Button"}, {"id": "B", "text": "ImageButton"}, {"id": "C", "text": "Image View"}, {"id": "D", "text": "Image"}, {"id": "E", "text": "TextView"}], "answers": [], "source": {"term": "20231", "pages": [32], "number": 17, "code": "34ee2f"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "ImageButton là widget chuyên dùng cho nút có ảnh. Tuy nhiên ImageView cũng có thể nhận click listener, còn Button và TextView hỗ trợ compound drawable. Vì câu hỏi dùng “could be used” và không nói chỉ widget chuyên dụng nên có nhiều cách hiểu; không gán một đáp án duy nhất để chấm.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}, {"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}, {"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-18", "text": "The 'when' statement in Kotlin is similar to which statement in other programming\nlanguages?", "type": "single", "options": [{"id": "A", "text": "continue"}, {"id": "B", "text": "break"}, {"id": "C", "text": "switch"}, {"id": "D", "text": "if"}], "answers": ["C"], "source": {"term": "20231", "pages": [33], "number": 18, "code": "22d19e"}, "note": "", "plain": true, "explanation": "when là cấu trúc phân nhánh gần với switch trong Java, nhưng mạnh hơn: có thể kiểm tra khoảng, kiểu và dùng như biểu thức trả về giá trị. Nó không tự rơi xuống nhánh tiếp theo như switch kiểu cũ; không cần break để kết thúc mỗi nhánh.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Điều khiển luồng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-19", "text": "Which kind of menu will be opened if user presses and hold for a while?", "type": "single", "options": [{"id": "A", "text": "Instant Menu"}, {"id": "B", "text": "Context Menu"}, {"id": "C", "text": "Drawer Menu"}, {"id": "D", "text": "Option Menu"}], "answers": ["B"], "source": {"term": "20231", "pages": [33], "number": 19, "code": "18efed"}, "plain": true, "explanation": "Context menu thường mở khi người dùng nhấn giữ một view đã đăng ký context menu. Options menu nằm trên app bar/overflow; navigation drawer là ngăn điều hướng. Nhấn giữ không tự động sinh context menu cho mọi view: ứng dụng cần cấu hình hành vi này.", "references": [{"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-20", "text": "Why use the Material Components for Android library?", "type": "multi", "options": [{"id": "A", "text": "It provides widgets that follow the Material Design guidelines such as text fields and switches."}, {"id": "B", "text": "It makes your code compile faster."}, {"id": "C", "text": "It provides default Material themes that you can use directly or extend and then customize."}, {"id": "D", "text": "It automatically suggests ways for your app to look better."}, {"id": "E", "text": "It helps you more quickly build beautiful user experiences."}], "answers": ["A", "C", "E"], "source": {"term": "20231", "pages": [33, 34], "number": 20, "code": "fc4c3c"}, "note": "", "plain": true, "explanation": "Material Components cung cấp widget và theme theo Material Design, giúp triển khai giao diện nhất quán và tùy biến màu, hình dạng, kiểu chữ. Thư viện không bảo đảm biên dịch nhanh hơn và không tự động thiết kế lại giao diện cho bạn. Câu này nói về thư viện Material cho hệ View, cần phân biệt với các composable Material trong Compose.", "references": [{"url": "https://github.com/material-components/material-components-android/blob/master/docs/getting-started.md", "title": "Material Components for Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-21", "text": "How to shutdown/finish an activity?", "type": "single", "options": [{"id": "A", "text": "destroy()"}, {"id": "B", "text": "finish()"}, {"id": "C", "text": "dispose()"}, {"id": "D", "text": "finishActivity()"}], "answers": ["B"], "source": {"term": "20231", "pages": [33, 34], "number": 21}, "note": "", "plain": true, "explanation": "finish() yêu cầu kết thúc Activity hiện tại. Không gọi trực tiếp onDestroy(); hệ thống quản lý các callback vòng đời. finishActivity(requestCode) là API khác dành cho Activity con đã mở theo requestCode, không thay thế finish() trong câu hỏi này.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-22", "text": "What is the intent action to open a web page?", "type": "single", "options": [{"id": "A", "text": "Intent.ACTION_ACCESS_INTERNET"}, {"id": "B", "text": "Intent.ACTION_WEB_VIEW"}, {"id": "C", "text": "Intent.ACTION_MAIN"}, {"id": "D", "text": "Intent.ACTION_GET_CONTENT @ Intent. ACTION_VIEW"}], "answers": [], "source": {"term": "20231", "pages": [34], "number": 22, "code": "88c235"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Mở trang web bằng Intent.ACTION_VIEW cùng Uri http:// hoặc https://. ACTION_GET_CONTENT yêu cầu người dùng chọn dữ liệu, còn ACTION_MAIN mô tả điểm vào chính chứ không mở URL cụ thể. Một số bản OCR làm mất dấu gạch dưới hoặc dính lựa chọn; chỉ bản có lựa chọn đọc được rõ mới được chấm.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-23", "text": "Which of the following tasks can be performed in onCreate()?", "type": "multi", "options": [{"id": "A", "text": "Configuring views, such as setting the layout manager of a recycler view"}, {"id": "B", "text": "Determining the items to be shown in the options menu."}, {"id": "C", "text": "Setting the onClickListener for items in the options menu."}, {"id": "D", "text": "Getting extras from the intent that launched the activity."}], "answers": ["A", "D"], "source": {"term": "20231", "pages": [34], "number": 23, "code": "celalf"}, "note": "", "plain": true, "explanation": "Theo cách tổ chức vòng đời chuẩn, onCreate() khởi tạo view, cấu hình RecyclerView và đọc intent.extras. Options menu được tạo trong onCreateOptionsMenu(), còn thao tác chọn menu được xử lý qua onOptionsItemSelected() hoặc listener của MenuItem. Cụm “can be performed” trong đề được hiểu là nơi thích hợp theo quy ước, không phải giới hạn kỹ thuật tuyệt đối.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}, {"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-24", "text": "Select all answers that are true for this XML layout when displayed on the screen.\n<androidx.constraintlayout.widget.ConstraintLayout\n    android:layout_width=\"match_parent\"\n    android:layout_height=\"match_parent\">\n    <TextView\n        android:id=\"@+id/textViewA\"\n        android:layout_width=\"wrap_content\"\n        android:layout_height=\"wrap_content\"\n        android:text=\"A\"\n        app:layout_constraintStart_toStartOf=\"parent\"\n        app:layout_constraintTop_toTopOf=\"parent\" />\n    <TextView\n        android:id=\"@+id/textViewB\"\n        android:layout_width=\"wrap_content\"\n        android:layout_height=\"wrap_content\"\n        android:text=\"B\"\n        app:layout_constraintEnd_toEndOf=\"parent\"\n        app:layout_constraintTop_toTopOf=\"parent\" />\n</androidx.constraintlayout.widget.ConstraintLayout>", "type": "multi", "options": [{"id": "A", "text": "TextView A appears vertically stacked on top of TextView B."}, {"id": "B", "text": "The starting edge of TextView A is aligned to the starting edge of the parent view."}, {"id": "C", "text": "The starting edge of TextView B is aligned to the starting edge of the parent view."}, {"id": "D", "text": "TextView B is horizontally and vertically centered within the parent."}, {"id": "E", "text": "The tops of TextView A and TextView B are aligned to top of the parent view."}, {"id": "F", "text": "The width of TextView A matches the width of the parent ConstraintLayout."}], "answers": ["B", "E"], "source": {"term": "20231", "pages": [34, 35, 49], "number": 24, "code": "d5b023"}, "note": "", "plain": true, "explanation": "TextView A có start_toStartOf parent, nên cạnh start của A trùng cạnh start của cha. Cả A và B đều có top_toTopOf parent nên cạnh trên thẳng với cha. B được căn end, không phải start hoặc center. wrap_content của A không làm nó rộng bằng ConstraintLayout; do đó chọn các ý về cạnh start của A và cạnh top của cả hai view.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-25", "text": "What is the language to program Android natively (select all correct answers)?", "type": "multi", "options": [{"id": "A", "text": "Java"}, {"id": "B", "text": "HTML, CSS, Javascript"}, {"id": "C", "text": "Kotlin"}, {"id": "D", "text": "C/C++"}], "answers": ["A", "C", "D"], "source": {"term": "20231", "pages": [35], "number": 25, "code": "becOd"}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-26", "text": "If you override onCreateOptionMenu callback in your activity, which menu are you going to\ncreate?", "type": "single", "options": [{"id": "A", "text": "Popup Menu"}, {"id": "B", "text": "ActionBar Menu"}, {"id": "C", "text": "Context Menu"}, {"id": "D", "text": "Navigation Drawer Menu"}], "answers": ["B"], "source": {"term": "20231", "pages": [35], "number": 26, "code": "93ff6c"}, "note": "", "plain": true, "explanation": "Callback đúng tên là onCreateOptionsMenu(), dùng để tạo options menu, thường hiển thị trên app bar/action bar hoặc overflow. Context menu gắn với ngữ cảnh của một view; popup menu neo vào một view. Đề viết thiếu chữ s trong tên callback nhưng ý hỏi là options menu.", "references": [{"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-27", "text": "True or False: onCreateView is only called once for a fragment's entire lifecycle?", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["B"], "source": {"term": "20231", "pages": [36], "number": 27, "code": "2bde37"}, "plain": true, "explanation": "Sai: vòng đời view của Fragment tách biệt vòng đời bản thân Fragment. View có thể bị hủy trong onDestroyView() rồi tạo lại, khiến onCreateView() được gọi nhiều lần trên cùng một Fragment. Cần tránh giữ tham chiếu binding của view cũ sau onDestroyView().", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-28", "text": "What are correct callback functions of Android activity life cycle?", "type": "single", "options": [{"id": "A", "text": "onCreate(), onInit(), onStart(), onPause(), onStop(), onDestroy(), onResume()"}, {"id": "B", "text": "onCreate(), onStart(), onResume(), onPause(), onStop(), onRestart(), onDestroy()"}, {"id": "C", "text": "onCreate(), onStart(), onPause(), onResume(), onFinish(), onStop(), onDestroy()"}, {"id": "D", "text": "onCreate(), onStart(), onActivityStarted(), onResume(), onPause(), onStop(), onActivityDestroy(), onDestroy()"}], "answers": ["B"], "source": {"term": "20231", "pages": [36], "number": 28, "code": "5b0cff"}, "plain": true, "explanation": "Các callback trong lựa chọn đúng là onCreate, onStart, onResume, onPause, onStop, onRestart và onDestroy. onRestart dùng khi Activity đã stopped quay lại. Danh sách trong đáp án là tập callback, không phải thứ tự chạy từ trái sang phải; onInit, onFinish và onActivityDestroy không thuộc tập callback Activity chuẩn đó.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-29", "text": "Which of the following is a benefit of using fragments?", "type": "multi", "options": [{"id": "A", "text": "Navigation between fragments allows for more sophisticated user interface patterns, such as tab bars."}, {"id": "B", "text": "Using multiple fragments within an activity allows for an adaptive layout across multiple screen sizes."}, {"id": "C", "text": "The same fragments can be reused across multiple activities."}, {"id": "D", "text": "Fragment is more lightweight than ACtivity sothat we should use Fragment rather than"}], "answers": [], "source": {"term": "20231", "pages": [36], "number": 29, "code": "3699cd"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Fragment cho phép tái sử dụng phần giao diện, kết hợp nhiều phần trong layout thích ứng và tổ chức các luồng điều hướng. Các ý về điều hướng, layout thích ứng và tái sử dụng mô tả các lợi ích đó. Fragment không thay thế Activity trong mọi trường hợp. Vì phương án D bị cắt giữa câu ở bản đang có, chưa đủ thông tin để chấm toàn bộ câu nhiều lựa chọn.", "references": [{"url": "https://developer.android.com/guide/fragments", "title": "Fragment"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-30", "text": "Which is a possible way/language to develop Android application?", "type": "multi", "options": [{"id": "A", "text": "Native approach: Java/Kotlin"}, {"id": "B", "text": "Web-based approach"}, {"id": "C", "text": "Universal Windows Platform (UWP) approach"}, {"id": "D", "text": "Object C"}, {"id": "E", "text": "Flutter"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [36, 37], "number": 30, "code": "fbc87"}, "note": "", "plain": true, "explanation": "Java/Kotlin là hướng native thông dụng; giao diện web có thể được đóng gói hoặc tích hợp qua WebView; Flutter cũng hỗ trợ xuất ứng dụng Android. UWP là nền tảng của Microsoft, còn Objective-C không phải lựa chọn Android native được hỏi ở đây. Các phương án đúng mô tả nhiều hướng phát triển, không chỉ một ngôn ngữ.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}, {"url": "https://developer.android.com/develop/ui/views/layout/webapps/webview", "title": "WebView"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-31", "text": "Where to configure the home activity - the first activity to be run in your application?", "type": "single", "options": [{"id": "A", "text": "in the AndroidManifest.xml"}, {"id": "B", "text": "in the project level gradle file"}, {"id": "C", "text": "in the MainActivity.kt"}, {"id": "D", "text": "in the module level gradle file"}], "answers": ["A"], "source": {"term": "20231", "pages": [37], "number": 31, "code": "2bcb"}, "plain": true, "explanation": "Activity khởi chạy từ biểu tượng ứng dụng được khai báo trong AndroidManifest.xml với intent-filter kết hợp android.intent.action.MAIN và android.intent.category.LAUNCHER. MainActivity.kt chứa mã thực thi, còn Gradle cấu hình build; chúng không thay thế khai báo launcher component trong manifest.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-32", "text": "Which of following components belong to android native library?\n1) Webkit\n2) OpenGL\n3) SQLite\n4) Dalvik\n5) OpenUI", "type": "single", "options": [{"id": "A", "text": "1,3,4"}, {"id": "B", "text": "1,2,3"}, {"id": "C", "text": "1,2,5"}, {"id": "D", "text": "3,4,5"}], "answers": ["B"], "source": {"term": "20231", "pages": [37], "number": 32, "code": "a93"}, "note": "", "plain": true, "explanation": "Theo mô hình kiến trúc Android truyền thống của đề, OpenGL ES, SQLite và các thư viện web thuộc nhóm thư viện native. Dalvik là máy ảo thực thi bytecode, không phải một thư viện native trong cách phân lớp này; Android hiện đại dùng ART. OpenUI không phải thành phần chuẩn trong danh sách được hỏi.", "references": [{"url": "https://source.android.com/docs/core/architecture", "title": "Kiến trúc Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-33", "text": "Fill in the blank\nThe ___ is called when you create an instance of a class.", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [37], "number": 33, "code": "fa"}, "note": "", "fields": [["constructor"]], "plain": true, "explanation": "Constructor được dùng khi tạo instance của lớp và khởi tạo các giá trị cần thiết. Kotlin có primary constructor và có thể có secondary constructor; các khối init cũng chạy trong quá trình khởi tạo. Đây không phải lời gọi một phương thức Activity như onCreate().", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-34", "text": "The RadioGroup class is directly inherited from which class?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "RelativeLayout"}, {"id": "C", "text": "android.widget.view"}, {"id": "D", "text": "ConstrainLayout"}, {"id": "E", "text": "ViewGroup"}], "answers": ["A"], "source": {"term": "20231", "pages": [38], "number": 34, "code": "d"}, "note": "", "plain": true, "explanation": "RadioGroup kế thừa trực tiếp android.widget.LinearLayout; LinearLayout tiếp tục kế thừa ViewGroup. Vì hỏi lớp cha trực tiếp nên chọn LinearLayout, không chọn ViewGroup. Điều này cũng giải thích tại sao RadioGroup có thuộc tính orientation để sắp nút ngang hoặc dọc.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-35", "text": "Android typically takes name of some popular cakes to name the Android version.\nFrom which version, cakes' name is not taken for Android version?\nAndroid 11", "type": "single", "options": [{"id": "A", "text": "Android 9"}, {"id": "B", "text": "Android 10"}, {"id": "C", "text": "Android 8"}], "answers": [], "source": {"term": "20231", "pages": [38], "number": 35, "code": "2a74aa"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Google chuyển cách gọi phiên bản công khai sang số bắt đầu từ Android 10, sau Android 9 Pie. Điều này không có nghĩa mọi tên mã nội bộ liên quan món tráng miệng đều biến mất. Một bản OCR có “Android 11” lẫn vào phần câu hỏi; bản đó được giữ để đối chiếu và không chấm.", "references": [{"url": "https://blog.google/products-and-platforms/platforms/android/evolving-android-brand/", "title": "Google · Tên Android 10"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-36", "text": "What is the function to open new activity from the current activity?", "type": "single", "options": [{"id": "A", "text": "newActivity"}, {"id": "B", "text": "beginActivity"}, {"id": "C", "text": "startActivity"}, {"id": "D", "text": "openActivity"}], "answers": ["C"], "source": {"term": "20231", "pages": [38], "number": 36, "code": "2f49e7"}, "plain": true, "explanation": "startActivity(intent) yêu cầu Android mở Activity được Intent xác định hoặc phân giải. Với explicit intent có thể viết Intent(this, TargetActivity::class.java). Các tên newActivity(), beginActivity() và openActivity() không phải phương thức mở Activity chuẩn của ngữ cảnh này.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-37", "text": "Which of the following is false about intents?", "type": "single", "options": [{"id": "A", "text": "Intents are performed using the startActivity method."}, {"id": "B", "text": "An implicit intent always results in the system asking the user which app to open"}, {"id": "C", "text": "Explicit intents require you to specify the class of the activity you want to show."}, {"id": "D", "text": "Both implicit and explicit intents allow your app to launch another activity."}], "answers": ["B"], "source": {"term": "20231", "pages": [38, 39], "number": 37, "code": "dfb247"}, "note": "", "plain": true, "explanation": "Phát biểu sai theo ngữ cảnh mở Activity là “implicit intent luôn hỏi người dùng chọn ứng dụng”. Hệ thống có thể mở thẳng ứng dụng mặc định hoặc ứng dụng duy nhất phù hợp. Explicit intent chỉ định component; implicit intent mô tả action/data. Intent còn dùng cho service và broadcast, nên startActivity() không phải API cho mọi loại Intent.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-38", "text": "When is the current Activity reset, i.e., the onCreate callback is called again?", "type": "multi", "options": [{"id": "A", "text": "user rotates the phone"}, {"id": "B", "text": "user changes the language of the phone"}, {"id": "C", "text": "user presses the home button and opens another app"}, {"id": "D", "text": "the phone is going to out of battery"}], "answers": ["A", "B"], "source": {"term": "20231", "pages": [39], "number": 38, "code": "c12143"}, "note": "", "plain": true, "explanation": "Theo hành vi mặc định, xoay màn hình hoặc đổi ngôn ngữ là thay đổi cấu hình và có thể làm Activity bị hủy rồi tạo lại, gọi lại onCreate(). Bấm Home thường chỉ đưa Activity về nền. Ngoại lệ: ứng dụng tự xử lý cấu hình qua configChanges hoặc hệ thống khôi phục sau khi tiến trình bị hủy; vì vậy các lựa chọn được chấm theo trường hợp mặc định của đề.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-39", "text": "What are lambdas in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A lambda is an expression that describes a function. But instead of declaring a named function, you declare a function that has no name"}, {"id": "B", "text": "A lambda is a Class type in Kotlin"}, {"id": "C", "text": "A lambda is an Interface in Kotlin"}, {"id": "D", "text": "A lambda is a Data Type in Kotlin"}], "answers": ["A"], "source": {"term": "20231", "pages": [39], "number": 39, "code": "ad4df3"}, "note": "", "plain": true, "explanation": "Lambda là biểu thức mô tả một hàm không có tên, ví dụ { x: Int -> x * 2 }. Có thể lưu nó trong biến kiểu hàm hoặc truyền làm đối số cho hàm bậc cao. Khi chỉ có một tham số và suy ra được kiểu, Kotlin cho phép dùng tên ngầm định it.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-40", "text": "Which is the direct parent class of the Button class?", "type": "single", "options": [{"id": "A", "text": "android.widget.View"}, {"id": "B", "text": "android.view.TextView"}, {"id": "C", "text": "android.view.View"}, {"id": "D", "text": "android.widget.TextView"}], "answers": ["D"], "source": {"term": "20231", "pages": [39, 40], "number": 40, "code": "bcaab4"}, "note": "", "plain": true, "explanation": "android.widget.Button kế thừa trực tiếp android.widget.TextView. TextView lại kế thừa android.view.View. Chú ý cả tên lớp và package: android.view.TextView và android.widget.View trong các phương án là tên không đúng.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-41", "text": "In case the activity has too many input controls so that the layout height is over the height\nof the phone's screen, which ViewGroup should be used?", "type": "single", "options": [{"id": "A", "text": "ScrollView"}, {"id": "B", "text": "LinearLayout"}, {"id": "C", "text": "HorizontalScrollView"}, {"id": "D", "text": "VerticalScrollView"}], "answers": ["A"], "source": {"term": "20231", "pages": [39, 40], "number": 41}, "note": "", "plain": true, "explanation": "ScrollView cho phép cuộn nội dung theo chiều dọc khi nội dung cao hơn màn hình. Nó chỉ có một view con trực tiếp; thường đặt một LinearLayout chứa các trường nhập bên trong. HorizontalScrollView dùng cho chiều ngang, còn LinearLayout tự nó không cung cấp cuộn.", "references": [{"url": "https://developer.android.com/reference/android/widget/ScrollView", "title": "ScrollView"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-42", "text": "What is the purpose of using RadioGroup?", "type": "multi", "options": [{"id": "A", "text": "to group RadioButton objects"}, {"id": "B", "text": "to arrange RadioButton objects by rows or by columns"}, {"id": "C", "text": "to replace the LinearLayout"}, {"id": "D", "text": "to make a RadioButton acts like a CheckBox"}, {"id": "E", "text": "to identify which RadioButton is selected"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [40], "number": 42, "code": "d696bb"}, "note": "", "plain": true, "explanation": "RadioGroup gom các RadioButton để chỉ chọn một nút trong nhóm; getCheckedRadioButtonId() cho biết nút đang chọn. Nó kế thừa LinearLayout nên có thể bố trí ngang hoặc dọc. Nó không biến RadioButton thành CheckBox và không phải phương án thay thế LinearLayout nói chung.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-43", "text": "Which of the following statements about app icons are true?", "type": "multi", "options": [{"id": "A", "text": "It is sufficient to provide a single bitmap image of your app icon in your project to make it appear high quality on a range of Android devices."}, {"id": "B", "text": "mdpi, hdpi, xhdpi, xxhdpi, and xxxhdpi are density qualifiers for resource directories to indicate that these are resources to be used on devices with a specific screen density."}, {"id": "C", "text": "Adaptive icons are made up of a foreground and background layer, and an OEM mask will be applied on top of them."}, {"id": "D", "text": "Vector drawables only work for a certain screen density and should not be scaled."}], "answers": ["B", "C"], "source": {"term": "20231", "pages": [40], "number": 43, "code": "08c62c"}, "plain": true, "explanation": "Nhóm mật độ đúng là mdpi, hdpi, xhdpi, xxhdpi, xxxhdpi; “dpi” đứng riêng trong bản OCR là lỗi mất chữ x. Adaptive icon có các lớp foreground/background và có thể được launcher áp mặt nạ; thiết bị mới còn hỗ trợ lớp monochrome. Bitmap cần xét mật độ màn hình, còn vector có thể co giãn. Phương án đã được sửa lỗi OCR trước khi chấm các ý về mật độ và lớp adaptive icon.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}, {"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-3-44", "text": "Overdiding the callback onSavelnstanceState is not suitable in which situation?", "type": "single", "options": [{"id": "A", "text": "save some states of Activity and restore latter when there is a device configuration changed"}, {"id": "B", "text": "save some states of Activity and restore latter when user rotates the device screen"}, {"id": "C", "text": "save some states of Activity and restore latter when user changes the language of the device"}, {"id": "D", "text": "store data into SD card to permanently use latter"}], "answers": ["D"], "source": {"term": "20231", "pages": [40, 41], "number": 44, "code": "21237a"}, "note": "", "plain": true, "explanation": "onSaveInstanceState() lưu trạng thái UI nhỏ để tái tạo Activity, chẳng hạn sau khi xoay màn hình. Nó không thay thế cơ sở dữ liệu, file hay DataStore để lưu dữ liệu lâu dài, và không bảo đảm được gọi trong mọi tình huống đóng ứng dụng. Vì vậy lưu dữ liệu vĩnh viễn ra thẻ nhớ không phải mục đích phù hợp.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle#saras", "title": "Lưu và khôi phục trạng thái"}], "reviewedOn": "2026-11-10"}, {"id": "20231-3-45", "text": "If you activity has the name: SampleActivity, what is the name of the binding class which is\ngenerated automatically by Android when you configure your application as data binding enable?", "type": "single", "options": [{"id": "A", "text": "sample_activity_binding"}, {"id": "B", "text": "ActivitySampleBinding"}, {"id": "C", "text": "activity_sample_binding"}, {"id": "D", "text": "SampleActivityBinding"}], "answers": [], "source": {"term": "20231", "pages": [41], "number": 45, "code": "a23808"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Tên lớp binding được suy ra từ tên file layout, không phải tên Activity. activity_sample.xml tạo ActivitySampleBinding; sample_activity.xml tạo SampleActivityBinding. Vì đề chỉ cho SampleActivity mà không cho file XML nên không đủ dữ kiện để chọn giữa hai lớp binding này.", "references": [{"url": "https://developer.android.com/topic/libraries/data-binding/generated-binding", "title": "Lớp binding sinh tự động"}], "reviewedOn": "2026-11-10"}]}, {"number": 4, "title": "20231 · Lượt 4 (tr. 42–54)", "questions": [{"id": "20231-4-1", "text": "Which of following components belong to android native library?\n1) Webkit\n2) OpenGL\n3) SQLite\n4) Dalvik\n5) OpenUI", "type": "single", "options": [{"id": "A", "text": "1,3,4"}, {"id": "B", "text": "1,2,3"}, {"id": "C", "text": "1,2,5"}, {"id": "D", "text": "3,4,5"}], "answers": ["B"], "source": {"term": "20231", "pages": [42], "number": 1}, "note": "", "plain": true, "explanation": "Theo mô hình kiến trúc Android truyền thống của đề, OpenGL ES, SQLite và các thư viện web thuộc nhóm thư viện native. Dalvik là máy ảo thực thi bytecode, không phải một thư viện native trong cách phân lớp này; Android hiện đại dùng ART. OpenUI không phải thành phần chuẩn trong danh sách được hỏi.", "references": [{"url": "https://source.android.com/docs/core/architecture", "title": "Kiến trúc Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-2", "text": "The Radio Group class is directly inherited from which class?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "RelativeLayout"}, {"id": "C", "text": "android.widget.view"}, {"id": "D", "text": "ConstrainLayout"}, {"id": "E", "text": "ViewGroup"}], "answers": ["A"], "source": {"term": "20231", "pages": [42], "number": 2, "code": "020c37"}, "plain": true, "explanation": "RadioGroup kế thừa trực tiếp android.widget.LinearLayout; LinearLayout tiếp tục kế thừa ViewGroup. Vì hỏi lớp cha trực tiếp nên chọn LinearLayout, không chọn ViewGroup. Điều này cũng giải thích tại sao RadioGroup có thuộc tính orientation để sắp nút ngang hoặc dọc.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-3", "text": "Which widget view could be used to make a clickable object with image content?", "type": "multi", "options": [{"id": "A", "text": "Button"}, {"id": "B", "text": "ImageButton"}, {"id": "C", "text": "Image View"}, {"id": "D", "text": "Image"}, {"id": "E", "text": "TextView"}], "answers": [], "source": {"term": "20231", "pages": [42, 43], "number": 3, "code": "d9b0eb"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "ImageButton là widget chuyên dùng cho nút có ảnh. Tuy nhiên ImageView cũng có thể nhận click listener, còn Button và TextView hỗ trợ compound drawable. Vì câu hỏi dùng “could be used” và không nói chỉ widget chuyên dụng nên có nhiều cách hiểu; không gán một đáp án duy nhất để chấm.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}, {"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}, {"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-4", "text": "An activity contains the following code in onCreate(). What will happen when this code is\nexecuted, if the intent property is null?\nval message = intent.extras?.getString(\"message\").toString()", "type": "single", "options": [{"id": "A", "text": "The app will not crash because the extras property is accessed safely using?."}, {"id": "B", "text": "The app will crash because it attempted to access a null object."}, {"id": "C", "text": "The app will not crash because the extras property is accessed unsafely using?."}, {"id": "D", "text": "The app will crash because it attempted to access the extras property on a null object."}], "answers": [], "source": {"term": "20231", "pages": [43], "number": 4}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Nếu intent thực sự null như giả thiết, intent.extras truy cập receiver null trước khi gặp dấu ?. nên có thể lỗi. Muốn bảo vệ cả chuỗi phải dùng intent?.extras?.getString(\"message\"). toString() trên giá trị nullable có thể tạo chuỗi \"null\". Hai lựa chọn mô tả crash trong đề trùng nghĩa, nên không chấm ép một lựa chọn.", "references": [{"url": "https://kotlinlang.org/docs/null-safety.html", "title": "Kotlin · Null safety"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-5", "text": "What is the intent action to open a web page?", "type": "single", "options": [{"id": "A", "text": "Intent.ACTION_ACCESS_INTERNET"}, {"id": "B", "text": "Intent.ACTION_WEB_VIEW"}, {"id": "C", "text": "Intent.ACTION_MAIN"}, {"id": "D", "text": "Intent.ACTION_GET_CONTENT"}, {"id": "E", "text": "Intent.ACTION_VIEW"}], "answers": ["E"], "source": {"term": "20231", "pages": [43], "number": 5, "code": "5df115"}, "plain": true, "explanation": "Mở trang web bằng Intent.ACTION_VIEW cùng Uri http:// hoặc https://. ACTION_GET_CONTENT yêu cầu người dùng chọn dữ liệu, còn ACTION_MAIN mô tả điểm vào chính chứ không mở URL cụ thể. Một số bản OCR làm mất dấu gạch dưới hoặc dính lựa chọn; chỉ bản có lựa chọn đọc được rõ mới được chấm.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-6", "text": "What is the language to program Android natively (select all correct answers)?", "type": "multi", "options": [{"id": "A", "text": "Java"}, {"id": "B", "text": "HTML, CSS, Javascript"}, {"id": "C", "text": "Kotlin"}, {"id": "D", "text": "C/C++"}], "answers": ["A", "C", "D"], "source": {"term": "20231", "pages": [43], "number": 6, "code": "59a05d"}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-7", "text": "What is the flexible point of Android devices compare to iOS ones?", "type": "single", "options": [{"id": "A", "text": "user data is more secured"}, {"id": "B", "text": "can connect to multiple peripheral devices such as mouse or keyboard"}, {"id": "C", "text": "backup and restore data easily with cloud services"}, {"id": "D", "text": "allow to install apps from third party sources (not from Google play store)"}], "answers": ["D"], "source": {"term": "20231", "pages": [43, 44], "number": 7, "code": "f815c6"}, "note": "", "plain": true, "explanation": "Trong bối cảnh đề năm 2023, lựa chọn được hỏi là Android cho cài APK từ nguồn ngoài Google Play khi người dùng cho phép. Đây không phải khẳng định Android luôn bảo mật hơn iOS hoặc iOS không bao giờ có phân phối ngoài cửa hàng trong mọi khu vực/thời điểm. Cài từ nguồn ngoài cũng đòi hỏi đánh giá độ tin cậy của ứng dụng.", "references": [{"url": "https://developer.android.com/distribute/marketing-tools/alternative-distribution", "title": "Phân phối ứng dụng ngoài Google Play"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-8", "text": "Where to configure the home activity - the first activity to be run in your application?", "type": "single", "options": [{"id": "A", "text": "in the AndroidManifest.xml"}, {"id": "B", "text": "in the project level gradle file"}, {"id": "C", "text": "in the MainActivity.kt"}, {"id": "D", "text": "in the module level gradle file"}], "answers": ["A"], "source": {"term": "20231", "pages": [44], "number": 8}, "note": "", "plain": true, "explanation": "Activity khởi chạy từ biểu tượng ứng dụng được khai báo trong AndroidManifest.xml với intent-filter kết hợp android.intent.action.MAIN và android.intent.category.LAUNCHER. MainActivity.kt chứa mã thực thi, còn Gradle cấu hình build; chúng không thay thế khai báo launcher component trong manifest.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-9", "text": "What are lambdas in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A lambda is an expression that describes a function. But instead of declaring a named function, you declare a function that has no name"}, {"id": "B", "text": "A lambda is a Class type in Kotlin"}, {"id": "C", "text": "A lambda is an Interface in Kotlin"}, {"id": "D", "text": "A lambda is a Data Type in Kotlin"}], "answers": ["A"], "source": {"term": "20231", "pages": [44], "number": 9, "code": "fdeбea"}, "plain": true, "explanation": "Lambda là biểu thức mô tả một hàm không có tên, ví dụ { x: Int -> x * 2 }. Có thể lưu nó trong biến kiểu hàm hoặc truyền làm đối số cho hàm bậc cao. Khi chỉ có một tham số và suy ra được kiểu, Kotlin cho phép dùng tên ngầm định it.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-10", "text": "Both Toast and Logcat can be used to debug the program, which expression bellow is\nwrong?", "type": "single", "options": [{"id": "A", "text": "Toast displays information at device while Logcat displays information at the host"}, {"id": "B", "text": "Logcat only display information that developer logs out"}, {"id": "C", "text": "Logcat can not be shown on computer without connection between the computer and the Android device"}, {"id": "D", "text": "Toast can be used to display some guidelines for user"}], "answers": ["B"], "source": {"term": "20231", "pages": [44], "number": 10, "code": "f32524"}, "plain": true, "explanation": "Logcat hiển thị log từ ứng dụng và hệ thống trên máy phát triển, có thể lọc theo tag, package và mức độ. Nó không chỉ chứa các dòng do lập trình viên tự ghi. Toast là thông báo ngắn trên thiết bị. “Cần kết nối” ở đây bao gồm thiết bị/emulator đang kết nối; file log đã lưu vẫn có thể xem về sau.", "references": [{"url": "https://developer.android.com/studio/debug/logcat", "title": "Logcat"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-11", "text": "Overdiding the callback onSavelnstanceState is not suitable in which situation?", "type": "single", "options": [{"id": "A", "text": "save some states of Activity and restore latter when there is a device configuration changed"}, {"id": "B", "text": "save some states of Activity and restore latter when user rotates the device screen"}, {"id": "C", "text": "save some states of Activity and restore latter when user changes the language of the device"}, {"id": "D", "text": "store data into SD card to permanently use latter"}], "answers": ["D"], "source": {"term": "20231", "pages": [44, 45], "number": 11}, "note": "", "plain": true, "explanation": "onSaveInstanceState() lưu trạng thái UI nhỏ để tái tạo Activity, chẳng hạn sau khi xoay màn hình. Nó không thay thế cơ sở dữ liệu, file hay DataStore để lưu dữ liệu lâu dài, và không bảo đảm được gọi trong mọi tình huống đóng ứng dụng. Vì vậy lưu dữ liệu vĩnh viễn ra thẻ nhớ không phải mục đích phù hợp.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle#saras", "title": "Lưu và khôi phục trạng thái"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-12", "text": "Which of the following are true about abstract classes?", "type": "multi", "options": [{"id": "A", "text": "They can be extended by subclasses and implementations can be provided for abstract members of the class."}, {"id": "B", "text": "They have an implementation for all of their properties and functions."}, {"id": "C", "text": "They may have abstract properties or abstract functions."}, {"id": "D", "text": "They can be instantiated"}, {"id": "E", "text": "They are not fully implemented and cannot be instantiated."}, {"id": "F", "text": "They need to be marked with the open keyword to be extended."}], "answers": ["A", "C"], "source": {"term": "20231", "pages": [45], "number": 12}, "note": "", "plain": true, "explanation": "Theo nghĩa chặt của các phát biểu, chọn các ý: lớp con có thể kế thừa và triển khai thành viên abstract; lớp abstract có thể khai báo thuộc tính hoặc hàm abstract. Lớp abstract không khởi tạo trực tiếp và tự cho phép kế thừa, không cần open. Phương án ghép “not fully implemented and cannot be instantiated” quá mạnh: một lớp abstract có thể không có thành viên abstract, nên phần “not fully implemented” không luôn đúng.", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-13", "text": "If you activity has the name: SampleActivity, what is the name of the binding class which is\ngenerated automatically by Android when you configure your application as data binding enable?", "type": "single", "options": [{"id": "A", "text": "sample_activity_binding"}, {"id": "B", "text": "ActivitySampleBinding"}, {"id": "C", "text": "activity_sample_binding"}, {"id": "D", "text": "SampleActivityBinding"}], "answers": [], "source": {"term": "20231", "pages": [45], "number": 13, "code": "64aa59"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Tên lớp binding được suy ra từ tên file layout, không phải tên Activity. activity_sample.xml tạo ActivitySampleBinding; sample_activity.xml tạo SampleActivityBinding. Vì đề chỉ cho SampleActivity mà không cho file XML nên không đủ dữ kiện để chọn giữa hai lớp binding này.", "references": [{"url": "https://developer.android.com/topic/libraries/data-binding/generated-binding", "title": "Lớp binding sinh tự động"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-14", "text": "Which of the following tasks can be performed in onCreate()?", "type": "multi", "options": [{"id": "A", "text": "Configuring views, such as setting the layout manager of a recycler view"}, {"id": "B", "text": "Determining the items to be shown in the options menu."}, {"id": "C", "text": "Setting the onClickListener for items in the options menu."}, {"id": "D", "text": "Getting extras from the intent that launched the activity."}], "answers": ["A", "D"], "source": {"term": "20231", "pages": [45, 46], "number": 14, "code": "fc80d5"}, "note": "", "plain": true, "explanation": "Theo cách tổ chức vòng đời chuẩn, onCreate() khởi tạo view, cấu hình RecyclerView và đọc intent.extras. Options menu được tạo trong onCreateOptionsMenu(), còn thao tác chọn menu được xử lý qua onOptionsItemSelected() hoặc listener của MenuItem. Cụm “can be performed” trong đề được hiểu là nơi thích hợp theo quy ước, không phải giới hạn kỹ thuật tuyệt đối.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}, {"url": "https://developer.android.com/develop/ui/views/components/menus", "title": "Menu trong Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-15", "text": "Given following code, select the correct:\nval address = ___.parse(\"https://soict.hust.edu.vn\")\nval intent: Intent = Intent(Intent.ACTION_VIEW, ___)\nstartActivity(intent)", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [46], "number": 15}, "note": "", "fields": [["Uri"], ["address"]], "plain": true, "explanation": "Hai chỗ trống lần lượt là Uri và address: Uri.parse(...) biến URL thành Uri; Intent(Intent.ACTION_VIEW, address) yêu cầu mở địa chỉ đó. Trong ứng dụng thực tế cần xử lý trường hợp không có Activity nhận Intent. Tên Uri phải viết đúng hoa/thường và biến address phải khớp biến đã khai báo.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-16", "text": "Which of the following is true about Gradle?", "type": "multi", "options": [{"id": "A", "text": "Gradle is an automated build system used by Android Studio to build your apps."}, {"id": "B", "text": "Gradle handles installing your app on a device"}, {"id": "C", "text": "Your app's build.gradle file is written in XML."}, {"id": "D", "text": "You can configure Android-specific options for your project in your app's build. gradle file."}, {"id": "E", "text": "The gradle configuration for your project cannot change after you initially create the project."}], "answers": ["A", "B", "D"], "source": {"term": "20231", "pages": [46], "number": 16, "code": "5775e0"}, "plain": true, "explanation": "Gradle tự động hóa build Android và có các task như installDebug để cài bản debug lên thiết bị phù hợp. build.gradle dùng Groovy DSL; build.gradle.kts dùng Kotlin DSL, không phải XML. Cấu hình module chứa các tùy chọn Android và dependencies, và có thể chỉnh sửa sau khi tạo dự án.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-17", "text": "Which of the following statements about app icons are true?", "type": "multi", "options": [{"id": "A", "text": "It is sufficient to provide a single bitmap image of your app icon in your project to make it appear high quality on a range of Android devices."}, {"id": "B", "text": "mdpi, hdpi, xhdpi, xxhdpi, and xxxhdpi are density qualifiers for resource directories to indicate that these are resources to be used on devices with a specific screen density."}, {"id": "C", "text": "Adaptive icons are made up of a foreground and background layer, and an OEM mask will be applied on top of them."}, {"id": "D", "text": "Vector drawables only work for a certain screen density and should not be scaled."}], "answers": ["B", "C"], "source": {"term": "20231", "pages": [46, 47], "number": 17, "code": "167926"}, "note": "", "plain": true, "explanation": "Nhóm mật độ đúng là mdpi, hdpi, xhdpi, xxhdpi, xxxhdpi; “dpi” đứng riêng trong bản OCR là lỗi mất chữ x. Adaptive icon có các lớp foreground/background và có thể được launcher áp mặt nạ; thiết bị mới còn hỗ trợ lớp monochrome. Bitmap cần xét mật độ màn hình, còn vector có thể co giãn. Phương án đã được sửa lỗi OCR trước khi chấm các ý về mật độ và lớp adaptive icon.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}, {"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-18", "text": "What is the function to open new activity from the current activity?", "type": "single", "options": [{"id": "A", "text": "newActivity"}, {"id": "B", "text": "beginActivity"}, {"id": "C", "text": "startActivity"}, {"id": "D", "text": "openActivity"}], "answers": ["C"], "source": {"term": "20231", "pages": [47], "number": 18}, "note": "", "plain": true, "explanation": "startActivity(intent) yêu cầu Android mở Activity được Intent xác định hoặc phân giải. Với explicit intent có thể viết Intent(this, TargetActivity::class.java). Các tên newActivity(), beginActivity() và openActivity() không phải phương thức mở Activity chuẩn của ngữ cảnh này.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-19", "text": "Fill in the blank\nThe ___ is called when you create an instance of a class.", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [47], "number": 19, "code": "23f10d"}, "fields": [["constructor"]], "plain": true, "explanation": "Constructor được dùng khi tạo instance của lớp và khởi tạo các giá trị cần thiết. Kotlin có primary constructor và có thể có secondary constructor; các khối init cũng chạy trong quá trình khởi tạo. Đây không phải lời gọi một phương thức Activity như onCreate().", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-20", "text": "What is the purpose of using RadioGroup?", "type": "multi", "options": [{"id": "A", "text": "to group RadioButton objects"}, {"id": "B", "text": "to arrange RadioButton objects by rows or by columns"}, {"id": "C", "text": "to replace the LinearLayout"}, {"id": "D", "text": "to make a RadioButton acts like a CheckBox"}, {"id": "E", "text": "to identify which RadioButton is selected"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [47], "number": 20, "code": "d2268d"}, "note": "", "plain": true, "explanation": "RadioGroup gom các RadioButton để chỉ chọn một nút trong nhóm; getCheckedRadioButtonId() cho biết nút đang chọn. Nó kế thừa LinearLayout nên có thể bố trí ngang hoặc dọc. Nó không biến RadioButton thành CheckBox và không phải phương án thay thế LinearLayout nói chung.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-21", "text": "What is the purpose of implicit intent?", "type": "single", "options": [{"id": "A", "text": "to close an activity in other application"}, {"id": "B", "text": "to open an service in current application"}, {"id": "C", "text": "to open an activity in other application"}, {"id": "D", "text": "to open an activity in current application"}], "answers": [], "source": {"term": "20231", "pages": [47, 48], "number": 21}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Implicit intent mô tả action/data mà không chỉ định lớp đích. Android tìm component phù hợp theo intent-filter, có thể ở cùng ứng dụng hoặc ứng dụng khác. Vì C và D đều có thể xảy ra trong khi đề yêu cầu một lựa chọn nên không chấm ép C; để mở màn hình nội bộ xác định, explicit intent thường phù hợp hơn.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-22", "text": "Why use the Material Components for Android library?", "type": "multi", "options": [{"id": "A", "text": "It provides widgets that follow the Material Design guidelines such as text fields and switches."}, {"id": "B", "text": "It makes your code compile faster."}, {"id": "C", "text": "It provides default Material themes that you can use directly or extend and then customize."}, {"id": "D", "text": "It automatically suggests ways for your app to look better."}, {"id": "E", "text": "It helps you more quickly build beautiful user experiences."}], "answers": ["A", "C", "E"], "source": {"term": "20231", "pages": [48], "number": 22}, "note": "", "plain": true, "explanation": "Material Components cung cấp widget và theme theo Material Design, giúp triển khai giao diện nhất quán và tùy biến màu, hình dạng, kiểu chữ. Thư viện không bảo đảm biên dịch nhanh hơn và không tự động thiết kế lại giao diện cho bạn. Câu này nói về thư viện Material cho hệ View, cần phân biệt với các composable Material trong Compose.", "references": [{"url": "https://github.com/material-components/material-components-android/blob/master/docs/getting-started.md", "title": "Material Components for Android"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-23", "text": "Which is the direct parent class of the Button class?", "type": "single", "options": [{"id": "A", "text": "android.widget.View"}, {"id": "B", "text": "android.view.TextView"}, {"id": "C", "text": "android.view.View"}, {"id": "D", "text": "android.widget.TextView"}], "answers": ["D"], "source": {"term": "20231", "pages": [48], "number": 23, "code": "ca2599"}, "note": "", "plain": true, "explanation": "android.widget.Button kế thừa trực tiếp android.widget.TextView. TextView lại kế thừa android.view.View. Chú ý cả tên lớp và package: android.view.TextView và android.widget.View trong các phương án là tên không đúng.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-24", "text": "The (fill in the blank with case sensitive) ___ method needs to be overridden in the host activity to ensure your app’s fragment-based navigation responds to the app’s \"Up\" button?", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [48], "number": 24, "code": "7dc5ec"}, "fields": [["onSupportNavigateUp", "onSupportNavigateUp()"]], "plain": true, "explanation": "Trong Activity dùng Navigation Component với app bar, ghi đè onSupportNavigateUp() và gọi NavController.navigateUp(appBarConfiguration), có thể fallback về super. Đây là xử lý nút Up trên app bar, khác với thao tác Back của hệ thống. Tên hàm cần điền là onSupportNavigateUp.", "references": [{"url": "https://developer.android.com/guide/navigation/integrations/ui#appbarconfiguration", "title": "NavigationUI · Nút Up"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-25", "text": "What are correct callback functions of Android activity life cycle?", "type": "single", "options": [{"id": "A", "text": "onCreate(), onInit(), onStart(), onPause(), onStop(), onDestroy(), onResume()"}, {"id": "B", "text": "onCreate(), onStart(), onResume(), onPause(), onStop(), onRestart(), onDestroy()"}, {"id": "C", "text": "onCreate(), onStart(), onPause(), onResume(), onFinish(), onStop(), onDestroy()"}, {"id": "D", "text": "onCreate(), onStart(), onActivityStarted(), onResume(), onPause(), onStop(), onActivityDestroy(), onDestroy()"}], "answers": ["B"], "source": {"term": "20231", "pages": [48, 49], "number": 25}, "note": "", "plain": true, "explanation": "Các callback trong lựa chọn đúng là onCreate, onStart, onResume, onPause, onStop, onRestart và onDestroy. onRestart dùng khi Activity đã stopped quay lại. Danh sách trong đáp án là tập callback, không phải thứ tự chạy từ trái sang phải; onInit, onFinish và onActivityDestroy không thuộc tập callback Activity chuẩn đó.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-26", "text": "Which value of the property scaleType of the ImageView allows us to keep remaining the\naspect ratio (the image will not be croped)?", "type": "single", "options": [{"id": "A", "text": "centerinside"}, {"id": "B", "text": "fitXY"}, {"id": "C", "text": "centerCrop"}, {"id": "D", "text": "center"}], "answers": ["A"], "source": {"term": "20231", "pages": [49], "number": 26}, "note": "", "plain": true, "explanation": "centerInside giữ tỉ lệ và thu nhỏ ảnh khi cần để toàn bộ ảnh nằm trong vùng hiển thị. fitXY có thể kéo méo; centerCrop phủ kín vùng nhìn bằng cách cắt ảnh; center giữ kích thước gốc nên ảnh lớn có thể bị cắt. Tên XML chính xác là centerInside, phân biệt chữ hoa chữ thường.", "references": [{"url": "https://developer.android.com/reference/android/widget/ImageView.ScaleType", "title": "ImageView.ScaleType"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-27", "text": "Select all answers that are true for this XML layout when displayed on the screen.\n<androidx.constraintlayout.widget.ConstraintLayout\n    android:layout_width=\"match_parent\"\n    android:layout_height=\"match_parent\">\n    <TextView\n        android:id=\"@+id/textViewA\"\n        android:layout_width=\"wrap_content\"\n        android:layout_height=\"wrap_content\"\n        android:text=\"A\"\n        app:layout_constraintStart_toStartOf=\"parent\"\n        app:layout_constraintTop_toTopOf=\"parent\" />\n    <TextView\n        android:id=\"@+id/textViewB\"\n        android:layout_width=\"wrap_content\"\n        android:layout_height=\"wrap_content\"\n        android:text=\"B\"\n        app:layout_constraintEnd_toEndOf=\"parent\"\n        app:layout_constraintTop_toTopOf=\"parent\" />\n</androidx.constraintlayout.widget.ConstraintLayout>", "type": "multi", "options": [{"id": "A", "text": "TextView A appears vertically stacked on top of TextView B."}, {"id": "B", "text": "The starting edge of TextView A is aligned to the starting edge of the parent view."}, {"id": "C", "text": "The starting edge of TextView B is aligned to the starting edge of the parent view."}, {"id": "D", "text": "TextView B is horizontally and vertically centered within the parent."}, {"id": "E", "text": "The tops of TextView A and TextView B are aligned to top of the parent view."}, {"id": "F", "text": "The width of TextView A matches the width of the parent ConstraintLayout."}], "answers": ["B", "E"], "source": {"term": "20231", "pages": [49, 50], "number": 27, "code": "0e8ea2"}, "plain": true, "explanation": "TextView A có start_toStartOf parent, nên cạnh start của A trùng cạnh start của cha. Cả A và B đều có top_toTopOf parent nên cạnh trên thẳng với cha. B được căn end, không phải start hoặc center. wrap_content của A không làm nó rộng bằng ConstraintLayout; do đó chọn các ý về cạnh start của A và cạnh top của cả hai view.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-28", "text": "How to handle the event that user press the button and hold for a while?", "type": "single", "options": [{"id": "A", "text": "setLongClickListener"}, {"id": "B", "text": "setOnLongClickListener"}, {"id": "C", "text": "setOnClickListener"}, {"id": "D", "text": "setOnLongTouchListener"}], "answers": ["B"], "source": {"term": "20231", "pages": [50], "number": 28}, "note": "", "plain": true, "explanation": "Nhấn giữ được xử lý bằng setOnLongClickListener. onLongClick(view) trả về true nếu sự kiện đã được xử lý. setOnClickListener xử lý thao tác nhấn thông thường; các tên setLongClickListener và setOnLongTouchListener trong đề không phải API tương ứng.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-29", "text": "If we have some buttons in one Activity, and all the buttons set the event onClickListener to\nthe Activity by calling setOnClickListener(this). So, in the callback function onClick of the\nActivity, how do you know which button is clicked?", "type": "single", "options": [{"id": "A", "text": "based on the order of buttons inside the xmi layout file"}, {"id": "B", "text": "based on the name of each button"}, {"id": "C", "text": "based on the position of each button"}, {"id": "D", "text": "based on the id of each button"}], "answers": ["D"], "source": {"term": "20231", "pages": [50], "number": 29, "code": "8296f8"}, "plain": true, "explanation": "onClick nhận chính View đã phát sinh sự kiện. Dùng view.id rồi so sánh với R.id của từng nút để xác định nút được nhấn. Vị trí, thứ tự trong XML hay tên biến Kotlin không phải định danh sự kiện ổn định.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-30", "text": "Which activity lifecycle method would be called if a dialog appears onscreen, partially\nobscuring an activity?", "type": "single", "options": [{"id": "A", "text": "onDestroy because the activity does not need to exist so long as it doesn't have focus."}, {"id": "B", "text": "onStop) because the activity does not need to respond to user input while the dialog is onscreen."}, {"id": "C", "text": "onResume) because the activity needed to respond to user input to display the dialog."}, {"id": "D", "text": "onPause) because the activity is still displayed, but no longer has focus."}], "answers": [], "source": {"term": "20231", "pages": [50], "number": 30, "code": "11261"}, "plain": true, "explanation": "Đáp án onPause() chỉ đúng khi một Activity khác, chẳng hạn Activity có giao diện dạng dialog, mở lên và làm Activity hiện tại mất trạng thái resumed trong mô hình của đề. Dialog hoặc DialogFragment hiển thị ngay trong chính Activity không mặc nhiên gọi onPause() của Activity. Câu hỏi không phân biệt hai trường hợp nên không chấm một đáp án bắt buộc.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích."}, {"id": "20231-4-31", "text": "True or False: onCreateView is only called once for a fragment's entire lifecycle?", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["B"], "source": {"term": "20231", "pages": [50, 51], "number": 31, "code": "57a5"}, "note": "", "plain": true, "explanation": "Sai: vòng đời view của Fragment tách biệt vòng đời bản thân Fragment. View có thể bị hủy trong onDestroyView() rồi tạo lại, khiến onCreateView() được gọi nhiều lần trên cùng một Fragment. Cần tránh giữ tham chiếu binding của view cũ sau onDestroyView().", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-32", "text": "Suppose we have an image named \"mobile.png\" in the res/drawable folder, and we have an\nImageView in the activity layout, which method could be used to set the image source for\nthe ImageView as the image mobile.png", "type": "single", "options": [{"id": "A", "text": "setImageResource(R.id.mobile)"}, {"id": "B", "text": "setImageResource(R.drawable.mobile)"}, {"id": "C", "text": "setImageDrawable(R.drawable.mobile)"}, {"id": "D", "text": "setImageResource(R.drawable.mobile.png)"}], "answers": ["B"], "source": {"term": "20231", "pages": [51], "number": 32, "code": "e2f"}, "note": "", "plain": true, "explanation": "setImageResource(R.drawable.mobile) nhận ID tài nguyên drawable dạng số nguyên. Không thêm đuôi .png trong R.drawable.mobile. R.id.mobile là ID view, còn setImageDrawable() cần một đối tượng Drawable, không nhận trực tiếp số ID tài nguyên như phương án trong đề.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-33", "text": "How to shutdown/finish an activity?", "type": "single", "options": [{"id": "A", "text": "destroy()"}, {"id": "B", "text": "finish()"}, {"id": "C", "text": "dispose()"}, {"id": "D", "text": "finishActivity()"}], "answers": ["B"], "source": {"term": "20231", "pages": [51], "number": 33, "code": "f7"}, "note": "", "plain": true, "explanation": "finish() yêu cầu kết thúc Activity hiện tại. Không gọi trực tiếp onDestroy(); hệ thống quản lý các callback vòng đời. finishActivity(requestCode) là API khác dành cho Activity con đã mở theo requestCode, không thay thế finish() trong câu hỏi này.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-34", "text": "Which of following is wrong about implicit intent?", "type": "single", "options": [{"id": "A", "text": "To call implicit, you have to know the class name of the destination activity"}, {"id": "B", "text": "Android runtime will open the app chooser if there exists more than one candidate for the implicit intent"}, {"id": "C", "text": "Android runtime receive the requests and try to find the matched application"}, {"id": "D", "text": "Android runtime keeps list of application registering to run the implicit intent"}], "answers": [], "source": {"term": "20231", "pages": [51], "number": 34, "code": "a"}, "plain": true, "explanation": "Implicit intent không cần biết tên lớp Activity đích, nên nhận định yêu cầu tên lớp là sai. Nhưng nhận định “có nhiều ứng dụng phù hợp thì luôn hiện chooser” cũng không đúng tuyệt đối: có thể đã có ứng dụng mặc định. Đề yêu cầu một lựa chọn trong khi có hơn một ý sai, và một bản OCR còn dính lựa chọn vào câu hỏi; không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích."}, {"id": "20231-4-35", "text": "The 'when' statement in Kotlin is similar to which statement in other programming\nlanguages?", "type": "single", "options": [{"id": "A", "text": "continue"}, {"id": "B", "text": "break"}, {"id": "C", "text": "switch"}, {"id": "D", "text": "if"}], "answers": ["C"], "source": {"term": "20231", "pages": [51, 52], "number": 35, "code": "3032b0"}, "note": "", "plain": true, "explanation": "when là cấu trúc phân nhánh gần với switch trong Java, nhưng mạnh hơn: có thể kiểm tra khoảng, kiểu và dùng như biểu thức trả về giá trị. Nó không tự rơi xuống nhánh tiếp theo như switch kiểu cũ; không cần break để kết thúc mỗi nhánh.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Điều khiển luồng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-36", "text": "Which of the following is a benefit of using fragments?", "type": "multi", "options": [{"id": "A", "text": "Navigation between fragments allows for more sophisticated user interface patterns, such as tab bars."}, {"id": "B", "text": "Using multiple fragments within an activity allows for an adaptive layout across multiple screen sizes."}, {"id": "C", "text": "The same fragments can be reused across multiple activities."}, {"id": "D", "text": "Fragment is more lightweight than ACtivity sothat we should use Fragment rather than"}], "answers": [], "source": {"term": "20231", "pages": [52], "number": 36}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Fragment cho phép tái sử dụng phần giao diện, kết hợp nhiều phần trong layout thích ứng và tổ chức các luồng điều hướng. Các ý về điều hướng, layout thích ứng và tái sử dụng mô tả các lợi ích đó. Fragment không thay thế Activity trong mọi trường hợp. Vì phương án D bị cắt giữa câu ở bản đang có, chưa đủ thông tin để chấm toàn bộ câu nhiều lựa chọn.", "references": [{"url": "https://developer.android.com/guide/fragments", "title": "Fragment"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-37", "text": "Given following code:\nval intent = Intent([ ], Uri.parse(\"123456789\"))\nintent.putExtra(\"sms_body\", \"hello\")\nstartActivity(intent)\nwhat could be filled in the [ ]?", "type": "single", "options": [{"id": "A", "text": "Intent.ACTION_SEND_SMS"}, {"id": "B", "text": "Intent.ACTION_SEND"}, {"id": "C", "text": "Intent.ACTION_SEND_MULTIPLE"}, {"id": "D", "text": "Intent.ACTION_SENDTO"}], "answers": [], "source": {"term": "20231", "pages": [52], "number": 37, "code": "fbb3e2"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Để mở ứng dụng nhắn SMS, dùng ACTION_SENDTO cùng Uri có scheme smsto:, ví dụ Uri.parse(\"smsto:123456789\"), rồi thêm sms_body. Chuỗi \"123456789\" trong đề thiếu scheme nên không bảo đảm tìm được ứng dụng xử lý. ACTION_SENDTO là ý định của câu hỏi, nhưng nguyên đoạn code chưa đủ đúng nên không dùng làm câu chấm điểm.", "references": [{"url": "https://developer.android.com/guide/components/intents-common", "title": "Các intent thường dùng"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-38", "text": "What is the default return type of any functions defined in Kotlin?", "type": "single", "options": [{"id": "A", "text": "Unit"}, {"id": "B", "text": "Double"}, {"id": "C", "text": "void"}, {"id": "D", "text": "Int"}], "answers": ["A"], "source": {"term": "20231", "pages": [52], "number": 38, "code": "cba607"}, "plain": true, "explanation": "Unit là kiểu trả về mặc định của hàm có thân khối khi không khai báo kiểu trả về, ví dụ fun log() { println(\"Hi\") }. Đề dùng từ “any” quá rộng: hàm thân biểu thức như fun twice(x: Int) = x * 2 được suy ra kiểu Int. Kotlin dùng Unit thay cho cách viết void của Java.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-39", "text": "Which is a possible way/language to develop Android application?", "type": "multi", "options": [{"id": "A", "text": "Native approach: Java/Kotlin"}, {"id": "B", "text": "Web-based approach"}, {"id": "C", "text": "Universal Windows Platform (UWP) approach"}, {"id": "D", "text": "Object C"}, {"id": "E", "text": "Flutter"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [53], "number": 39, "code": "fcfdf5"}, "note": "", "plain": true, "explanation": "Java/Kotlin là hướng native thông dụng; giao diện web có thể được đóng gói hoặc tích hợp qua WebView; Flutter cũng hỗ trợ xuất ứng dụng Android. UWP là nền tảng của Microsoft, còn Objective-C không phải lựa chọn Android native được hỏi ở đây. Các phương án đúng mô tả nhiều hướng phát triển, không chỉ một ngôn ngữ.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}, {"url": "https://developer.android.com/develop/ui/views/layout/webapps/webview", "title": "WebView"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-40", "text": "When is the current Activity reset, i.e., the onCreate callback is called again?", "type": "multi", "options": [{"id": "A", "text": "user rotates the phone"}, {"id": "B", "text": "user changes the language of the phone"}, {"id": "C", "text": "user presses the home button and opens another app"}, {"id": "D", "text": "the phone is going to out of battery"}], "answers": ["A", "B"], "source": {"term": "20231", "pages": [53], "number": 40, "code": "a73d85"}, "plain": true, "explanation": "Theo hành vi mặc định, xoay màn hình hoặc đổi ngôn ngữ là thay đổi cấu hình và có thể làm Activity bị hủy rồi tạo lại, gọi lại onCreate(). Bấm Home thường chỉ đưa Activity về nền. Ngoại lệ: ứng dụng tự xử lý cấu hình qua configChanges hoặc hệ thống khôi phục sau khi tiến trình bị hủy; vì vậy các lựa chọn được chấm theo trường hợp mặc định của đề.", "references": [{"url": "https://developer.android.com/guide/components/activities/activity-lifecycle", "title": "Vòng đời Activity"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-41", "text": "Which of the following is not a challange for Android application development?", "type": "single", "options": [{"id": "A", "text": "The deverloper may have to use different development tools in different OS"}, {"id": "B", "text": "The application must have compatibility with several different versions of Android"}, {"id": "C", "text": "The application mus be designed for multiple resolutions"}, {"id": "D", "text": "Source code and user's data must be secured"}], "answers": ["A"], "source": {"term": "20231", "pages": [53], "number": 41, "code": "c0b309"}, "plain": true, "explanation": "Android Studio có bản cho nhiều hệ điều hành máy tính; việc bắt buộc dùng các công cụ khác nhau theo hệ điều hành, hoặc chỉ được lập trình trên một hệ điều hành, không phải hạn chế Android trong đề. Tương thích phiên bản Android, kích thước/độ phân giải màn hình và bảo vệ dữ liệu đều là các vấn đề thực tế cần xử lý.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-42", "text": "In the fragment lifecycle, which of the following tasks should be performed in\nonViewCreated() ?", "type": "multi", "options": [{"id": "A", "text": "Inflating the layout"}, {"id": "B", "text": "Binding view objects to properties in your fragment"}, {"id": "C", "text": "Configuring the options menu"}, {"id": "D", "text": "Setting properties of individual views, such as a recycler view's adapter"}], "answers": ["B", "D"], "source": {"term": "20231", "pages": [53, 54], "number": 42, "code": "183869"}, "note": "", "plain": true, "explanation": "onCreateView() tạo cây view; onViewCreated() được gọi sau khi cây view đã tồn tại. Vì vậy có thể lấy tham chiếu view, gắn dữ liệu và đặt adapter cho RecyclerView trong onViewCreated(). Không inflate layout lần nữa ở callback này; menu có cơ chế callback hoặc MenuProvider riêng.", "references": [{"url": "https://developer.android.com/guide/fragments/lifecycle", "title": "Vòng đời Fragment"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-43", "text": "To make the EditText allows password characters (e.g., display * instead of the real character), you have to set the value of the inputType property as (type your answer with case sensitive) ___", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [54], "number": 43}, "note": "", "fields": [["textPassword"]], "plain": true, "explanation": "Giá trị XML cần điền là textPassword, ví dụ android:inputType=\"textPassword\". Nó cấu hình kiểu nhập văn bản mật khẩu và cách che ký tự; numberPassword dùng cho mật khẩu dạng số. Che ký tự trên màn hình không đồng nghĩa với mã hóa hay lưu mật khẩu an toàn.", "references": [{"url": "https://developer.android.com/develop/ui/views/touch-and-input/keyboard-input/style", "title": "Kiểu nhập liệu"}], "reviewedOn": "2026-11-10"}, {"id": "20231-4-44", "text": "Suppose we write an application to survey the hobby of people (there are 5 hobbies to be\nsurveyed), one person may have several hobbies. Which input controls is suitable for this\npurpose?", "type": "single", "options": [{"id": "A", "text": "RadioButton"}, {"id": "B", "text": "Recycler View"}, {"id": "C", "text": "DropDownList"}, {"id": "D", "text": "ListView"}, {"id": "E", "text": "Checkbox"}], "answers": ["E"], "source": {"term": "20231", "pages": [54], "number": 44, "code": "d90db2"}, "plain": true, "explanation": "CheckBox cho phép chọn độc lập nhiều sở thích cùng lúc. RadioButton trong một RadioGroup chỉ cho một lựa chọn, phù hợp câu hỏi loại trừ lẫn nhau. Số lượng sở thích không quyết định widget; điều quyết định ở đây là người dùng được chọn nhiều mục.", "references": [{"url": "https://developer.android.com/reference/android/widget/RadioGroup", "title": "RadioGroup"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20231-4-45", "text": "What is the advantage of Android development environment compare to iOS development\nenvironment?", "type": "multi", "options": [{"id": "A", "text": "the Ul experience is better"}, {"id": "B", "text": "can develop app on several operating systems"}, {"id": "C", "text": "easier to test on real devices"}, {"id": "D", "text": "can use several IDEs for app development"}], "answers": [], "source": {"term": "20231", "pages": [54], "number": 45, "code": "49000c"}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Android Studio chạy trên nhiều hệ điều hành máy tính, nên đây là một ưu điểm khách quan có thể kiểm chứng. Tuy nhiên “dễ thử thiết bị”, “dễ tiếp cận người dùng” hay trải nghiệm UI tốt hơn là so sánh phụ thuộc tiêu chí. Đề không nêu đủ tiêu chí và có thể có nhiều nhận định phù hợp; giữ câu để học kiến thức nhưng không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10"}]}, {"number": 5, "title": "20241 · Lớp 154043 · A (tr. 1–2)", "questions": [{"id": "20241-1-1", "text": "Lớp Button được kế thừa trực tiếp từ lớp nào?", "type": "single", "options": [{"id": "A", "text": "android.view.View"}, {"id": "B", "text": "android.widget.TextView"}, {"id": "C", "text": "android.widget.View"}, {"id": "D", "text": "android.view.TextView"}], "answers": ["B"], "source": {"term": "20241", "pages": [1], "number": 1}, "plain": true, "explanation": "android.widget.Button kế thừa trực tiếp android.widget.TextView. TextView lại kế thừa android.view.View. Chú ý cả tên lớp và package: android.view.TextView và android.widget.View trong các phương án là tên không đúng.", "references": [{"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-2", "text": "Phát biểu nào không phải là một thách thức khi lập trình ứng dụng trên nền tảng Android?", "type": "single", "options": [{"id": "A", "text": "Ứng dụng cần tương thích với các phiên bản hệ điều hành khác nhau."}, {"id": "B", "text": "Ứng dụng cần thiết kế phù hợp với nhiều độ phân giải khác nhau."}, {"id": "C", "text": "Lập trình viên chỉ sử dụng công cụ lập trình trên một hệ điều hành nhất định."}, {"id": "D", "text": "Mã nguồn và dữ liệu người dùng cần được bảo mật."}], "answers": ["C"], "source": {"term": "20241", "pages": [1], "number": 2}, "plain": true, "explanation": "Android Studio có bản cho nhiều hệ điều hành máy tính; việc bắt buộc dùng các công cụ khác nhau theo hệ điều hành, hoặc chỉ được lập trình trên một hệ điều hành, không phải hạn chế Android trong đề. Tương thích phiên bản Android, kích thước/độ phân giải màn hình và bảo vệ dữ liệu đều là các vấn đề thực tế cần xử lý.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-3", "text": "Công cụ Layout Editor trong Android Studio được sử dụng phù hợp nhất với kiểu layout nào?", "type": "single", "options": [{"id": "A", "text": "FrameLayout"}, {"id": "B", "text": "ConstraintLayout"}, {"id": "C", "text": "LinearLayout"}, {"id": "D", "text": "RelativeLayout"}], "answers": ["B"], "source": {"term": "20241", "pages": [1], "number": 3}, "plain": true, "explanation": "ConstraintLayout được hỗ trợ trực quan mạnh trong Layout Editor để tạo và điều chỉnh các ràng buộc. Layout Editor vẫn làm việc với các layout khác; câu hỏi dùng “phù hợp nhất” trong nhóm lựa chọn, không có nghĩa chỉ ConstraintLayout mới chỉnh được bằng công cụ này.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-4", "text": "Ký tự R trong \"R.layout.activity_main\" tham chiếu đến thành phần nào trong Android?", "type": "single", "options": [{"id": "A", "text": "Resource"}, {"id": "B", "text": "Room"}, {"id": "C", "text": "Receiver"}, {"id": "D", "text": "Runnable"}], "answers": ["A"], "source": {"term": "20241", "pages": [1], "number": 4}, "plain": true, "explanation": "R là lớp tài nguyên được công cụ build sinh tự động. R.layout.activity_main là ID của tài nguyên layout tên activity_main; R.string, R.drawable và R.id là các nhóm ID khác. R không phải Room, Receiver hay Runnable.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-5", "text": "Trong Kotlin, từ khóa nào được sử dụng để mô tả một hàm hoặc một thuộc tính có thể được viết chồng?", "type": "single", "options": [{"id": "A", "text": "override"}, {"id": "B", "text": "open"}, {"id": "C", "text": "final"}, {"id": "D", "text": "abstract"}], "answers": ["B"], "source": {"term": "20241", "pages": [1], "number": 5}, "note": "", "plain": true, "explanation": "open đặt ở khai báo lớp cha để cho phép kế thừa hoặc ghi đè thành viên vốn final mặc định. override đặt ở khai báo lớp con đang thực hiện ghi đè. Thành viên abstract vốn đã cho phép override; trong lựa chọn của câu hỏi này, open là từ khóa thể hiện chủ đích “có thể được viết chồng”.", "references": [{"url": "https://kotlinlang.org/docs/inheritance.html", "title": "Kotlin · Kế thừa"}], "reviewedOn": "2026-11-10"}, {"id": "20241-1-6", "text": "Giả sử có đoạn khởi tạo như sau:\nval textView = findViewById<TextView>(R.id.textView)\nval count = 123\nLệnh nào dưới đây có thể gây lỗi khi chạy chương trình?", "type": "single", "options": [{"id": "A", "text": "textView.text = \"\" + count"}, {"id": "B", "text": "textView.text = \"$count\""}, {"id": "C", "text": "textView.setText(count)"}, {"id": "D", "text": "textView.text = count.toString()"}], "answers": ["C"], "source": {"term": "20241", "pages": [1], "number": 6}, "plain": true, "explanation": "TextView.setText(Int) hiểu số nguyên là ID tài nguyên chuỗi, không phải số cần hiển thị. Vì vậy setText(count) với count = 123 có thể gây Resources.NotFoundException. Dùng count.toString(), \"$count\" hoặc nối chuỗi để chọn overload nhận văn bản.", "references": [{"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-7", "text": "Đối tượng nào không hiển thị được nội dung là ảnh?", "type": "single", "options": [{"id": "A", "text": "ImageView"}, {"id": "B", "text": "TextView"}, {"id": "C", "text": "Button"}, {"id": "D", "text": "ImageButton"}], "answers": [], "source": {"term": "20241", "pages": [1], "number": 7}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Không có lựa chọn duy nhất phù hợp với cách hỏi: ImageView và ImageButton hiển thị ảnh, còn TextView và Button đều hỗ trợ compound drawable ở cạnh văn bản. Nếu chỉ nói đến ảnh làm nội dung chính thì đề phải nêu rõ. Không chấm một widget là tuyệt đối “không hiển thị được ảnh”.", "references": [{"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}, {"url": "https://developer.android.com/reference/android/widget/Button", "title": "Button"}], "reviewedOn": "2026-11-10"}, {"id": "20241-1-8", "text": "Trong Kotlin, dấu chấm phẩy (;) được sử dụng trong trường hợp nào?", "type": "single", "options": [{"id": "A", "text": "Kết thúc mỗi dòng lệnh"}, {"id": "B", "text": "Kết thúc mỗi câu lệnh"}, {"id": "C", "text": "Ngăn cách các câu lệnh trên cùng một dòng"}, {"id": "D", "text": "Kotlin không sử dụng dấu chấm phẩy"}], "answers": ["C"], "source": {"term": "20241", "pages": [1], "number": 8}, "plain": true, "explanation": "Kotlin thường không cần dấu chấm phẩy cuối dòng; dấu ; dùng để phân tách nhiều câu lệnh viết trên cùng một dòng. Ví dụ val a = 1; println(a). Đây là lựa chọn phù hợp nhất của đề; không suy ra Kotlin cấm dấu ; cuối câu lệnh. Bản bị cắt mất lựa chọn đúng không được chấm.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-9", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nfun main() {\n    println(calc(6, 4))\n}\nfun calc(x: Int, y: Int) = x % y", "type": "single", "options": [{"id": "A", "text": "Đoạn chương trình bị lỗi cú pháp"}, {"id": "B", "text": "10"}, {"id": "C", "text": "2"}, {"id": "D", "text": "1"}], "answers": ["C"], "source": {"term": "20241", "pages": [2], "number": 9}, "plain": true, "explanation": "calc(6, 4) tính phần dư 6 % 4 bằng 2. Với thân biểu thức = x % y, Kotlin suy ra kiểu trả về Int nên việc không ghi : Int không phải lỗi. Không nhầm % với phép chia nguyên 6 / 4 cho kết quả 1.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-10", "text": "Ở cửa sổ Project trong phần mềm Android Studio, chức năng hiển thị nào chỉ liệt kê 4 thành phần cơ bản của một dự án (AndroidManifest, mã nguồn Kotlin, các thư mục tài nguyên, các file gradle)?", "type": "single", "options": [{"id": "A", "text": "Production"}, {"id": "B", "text": "Android"}, {"id": "C", "text": "Project Files"}, {"id": "D", "text": "Packages"}], "answers": ["B"], "source": {"term": "20241", "pages": [2], "number": 10}, "plain": true, "explanation": "Chế độ Android trong cửa sổ Project gom file theo các nhóm quen thuộc như manifests, mã nguồn, res và Gradle Scripts. Đây là cách hiển thị logic phục vụ lập trình Android, không phải cấu trúc thư mục vật lý nguyên bản như Project. Tên và cách nhóm có thể khác nhẹ theo phiên bản Android Studio.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/declaring-layout", "title": "Layout trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-11", "text": "Từ khóa \"val\" được sử dụng với mục đích gì?", "type": "single", "options": [{"id": "A", "text": "Định nghĩa một biến không thay đổi được giá trị"}, {"id": "B", "text": "Định nghĩa một lớp"}, {"id": "C", "text": "Định nghĩa một biến có thể thay đổi giá trị"}, {"id": "D", "text": "Định nghĩa một hàm"}], "answers": ["A"], "source": {"term": "20241", "pages": [2], "number": 11}, "plain": true, "explanation": "val khai báo một tham chiếu chỉ được gán một lần; var cho phép gán lại. Điều này không đồng nghĩa đối tượng mà val trỏ tới luôn bất biến: val list = mutableListOf(1) vẫn cho phép list.add(2). Trong câu hỏi nhập môn, chọn phương án biến không gán lại giá trị.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-12", "text": "Thuộc tính layout_weight chỉ được sử dụng cho kiểu layout nào?", "type": "single", "options": [{"id": "A", "text": "FrameLayout"}, {"id": "B", "text": "ConstraintLayout"}, {"id": "C", "text": "LinearLayout"}, {"id": "D", "text": "RelativeLayout"}], "answers": ["C"], "source": {"term": "20241", "pages": [2], "number": 12}, "plain": true, "explanation": "Trong nhóm layout của đề, layout_weight thuộc LinearLayout.LayoutParams và phân chia phần không gian còn lại theo tỉ lệ trọng số. Với chiều ngang thường đặt layout_width=\"0dp\" cho các view chia đều. Không nhầm thuộc tính này với chain weight của ConstraintLayout.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/linear", "title": "LinearLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-13", "text": "Giả sử file my_font.ttf đã được sao chép vào thư mục font trong thư mục res. Để thiết lập font chữ cho đối tượng TextView thì thuộc tính nào cần được khai báo trong file XML?", "type": "single", "options": [{"id": "A", "text": "android:textFont=\"@font/my_font\""}, {"id": "B", "text": "android:fontFamily=\"@font/my_font\""}, {"id": "C", "text": "android:font=\"@font/my_font\""}, {"id": "D", "text": "android:typeface=\"@font/my_font\""}], "answers": ["B"], "source": {"term": "20241", "pages": [2], "number": 13}, "plain": true, "explanation": "Dùng android:fontFamily=\"@font/my_font\" để tham chiếu font đặt trong res/font/my_font.ttf. android:typeface không phải cách tham chiếu file font tùy chỉnh này. Trong Kotlin có thể lấy Typeface bằng ResourcesCompat.getFont(...) rồi gán cho TextView.", "references": [{"url": "https://developer.android.com/develop/ui/views/text-and-emoji/fonts-in-xml", "title": "Font trong XML"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-14", "text": "Tập tin cấu hình nào chứa thông tin phiên bản và các dependencies của ứng dụng?", "type": "single", "options": [{"id": "A", "text": "AndroidManifest.xml"}, {"id": "B", "text": "proguard-rules.pro"}, {"id": "C", "text": "build.gradle"}, {"id": "D", "text": "settings.gradle"}], "answers": ["C"], "source": {"term": "20241", "pages": [2], "number": 14}, "plain": true, "explanation": "File build.gradle của module, hoặc build.gradle.kts với Kotlin DSL, khai báo các cấu hình như versionCode/versionName và dependencies. AndroidManifest.xml mô tả component/quyền; proguard-rules.pro cấu hình thu gọn/làm rối. Dự án hiện đại còn có version catalog nên không nhất thiết mọi giá trị phiên bản đều viết trực tiếp trong một file.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-15", "text": "Mệnh đề \"when\" trong Kotlin giống với mệnh đề nào trong ngôn ngữ Java?", "type": "single", "options": [{"id": "A", "text": "while"}, {"id": "B", "text": "switch"}, {"id": "C", "text": "if"}, {"id": "D", "text": "continue"}], "answers": ["B"], "source": {"term": "20241", "pages": [2], "number": 15}, "plain": true, "explanation": "when là cấu trúc phân nhánh gần với switch trong Java, nhưng mạnh hơn: có thể kiểm tra khoảng, kiểu và dùng như biểu thức trả về giá trị. Nó không tự rơi xuống nhánh tiếp theo như switch kiểu cũ; không cần break để kết thúc mỗi nhánh.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Điều khiển luồng"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-16", "text": "File nào được sử dụng để thiết kế giao diện trong Android?", "type": "single", "options": [{"id": "A", "text": "MainActivity.kt"}, {"id": "B", "text": "AndroidManifest.xml"}, {"id": "C", "text": "activity_main.xml"}, {"id": "D", "text": "build.gradle"}], "answers": ["C"], "source": {"term": "20241", "pages": [2], "number": 16}, "plain": true, "explanation": "Trong hệ giao diện Android View dùng XML, activity_main.xml mô tả layout và được Activity nạp vào. MainActivity.kt chứa logic, AndroidManifest.xml khai báo ứng dụng, còn Gradle cấu hình build. Với Jetpack Compose có thể mô tả UI bằng Kotlin thay vì file layout XML; đáp án ở đây theo hệ View của đề.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/declaring-layout", "title": "Layout trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-17", "text": "Phương thức nào dùng để thêm văn bản vào cuối nội dung hiện có trong TextView?", "type": "single", "options": [{"id": "A", "text": "append()"}, {"id": "B", "text": "insertText()"}, {"id": "C", "text": "addText()"}, {"id": "D", "text": "appendText()"}], "answers": ["A"], "source": {"term": "20241", "pages": [2], "number": 17}, "plain": true, "explanation": "TextView.append(...) thêm văn bản vào cuối nội dung hiện có; setText(...) thay toàn bộ nội dung. Ví dụ textView.append(\" thêm\") giữ phần chữ trước đó. Các tên insertText, addText và appendText trong lựa chọn không phải API TextView tương ứng.", "references": [{"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-18", "text": "Thuộc tính layout_alignParentLeft chỉ được sử dụng cho kiểu layout nào?", "type": "single", "options": [{"id": "A", "text": "RelativeLayout"}, {"id": "B", "text": "LinearLayout"}, {"id": "C", "text": "FrameLayout"}, {"id": "D", "text": "ConstraintLayout"}], "answers": ["A"], "source": {"term": "20241", "pages": [2], "number": 18}, "plain": true, "explanation": "layout_alignParentLeft là quy tắc do RelativeLayout.LayoutParams xử lý, căn cạnh trái view theo cạnh trái vùng nội dung cha. Với ứng dụng hỗ trợ ngôn ngữ RTL nên cân nhắc layout_alignParentStart. Thuộc tính layout_* được layout cha diễn giải, không phải mọi layout đều hiểu cùng một thuộc tính.", "references": [{"url": "https://developer.android.com/reference/android/widget/RelativeLayout.LayoutParams", "title": "RelativeLayout.LayoutParams"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-19", "text": "Giả sử bên trong RelativeLayout có đối tượng được định nghĩa như sau:\n<TextView android:layout_width=\"wrap_content\"\n    android:layout_height=\"wrap_content\"\n    android:layout_alignParentRight=\"true\"\n    android:layout_alignParentLeft=\"true\"\n    android:text=\"Hello\"/>\nHỏi chiều rộng thực tế của đối tượng là bao nhiêu?", "type": "single", "options": [{"id": "A", "text": "Bằng với chiều rộng RelativeLayout"}, {"id": "B", "text": "Bằng 0dp"}, {"id": "C", "text": "Vừa đủ để chứa chuỗi \"Hello\""}, {"id": "D", "text": "Các đáp án đều không đúng"}], "answers": ["A"], "source": {"term": "20241", "pages": [2], "number": 19}, "plain": true, "explanation": "Hai quy tắc alignParentLeft và alignParentRight ghim hai cạnh ngang của view vào hai cạnh vùng nội dung RelativeLayout, nên chiều rộng bị kéo theo khoảng giữa chúng dù khai báo wrap_content. Với giả thiết cha không padding và view không margin, nó rộng bằng cha. Nếu có padding/margin thì cần trừ phần đó; câu hỏi không cung cấp các giá trị này.", "references": [{"url": "https://developer.android.com/reference/android/widget/RelativeLayout.LayoutParams", "title": "RelativeLayout.LayoutParams"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-1-20", "text": "Kiểu layout nào thường được sử dụng chỉ để chứa 1 đối tượng bên trong?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "FrameLayout"}, {"id": "C", "text": "RelativeLayout"}, {"id": "D", "text": "ConstraintLayout"}], "answers": ["B"], "source": {"term": "20241", "pages": [2], "number": 20}, "plain": true, "explanation": "FrameLayout thường dùng làm vùng chứa một view chính hoặc xếp chồng các view. Nó vẫn cho phép nhiều con, nên câu hỏi nói “thường” chứ không phải giới hạn bắt buộc chỉ một view. LinearLayout xếp theo hàng/cột; RelativeLayout và ConstraintLayout diễn tả quan hệ vị trí.", "references": [{"url": "https://developer.android.com/reference/android/widget/FrameLayout", "title": "FrameLayout"}], "reviewedOn": "2026-11-10", "note": ""}]}, {"number": 6, "title": "20241 · Đề ảnh cắt · A (tr. 3–8)", "questions": [{"id": "20241-2-1", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nvar s = 0\nrepeat(5) { s += it }\nprintln(s)", "type": "single", "options": [{"id": "A", "text": "10"}, {"id": "B", "text": "Đoạn chương trình bị lỗi cú pháp"}, {"id": "C", "text": "15"}, {"id": "D", "text": "6"}], "answers": ["A"], "source": {"term": "20241", "pages": [3], "number": 1}, "plain": true, "explanation": "repeat(5) chạy lambda 5 lần với it lần lượt là 0, 1, 2, 3, 4. Vì s bắt đầu bằng 0 nên tổng là 0 + 1 + 2 + 3 + 4 = 10. Không dùng 1 đến 5, và biến s phải là var vì được cập nhật mỗi lượt.", "references": [{"url": "https://kotlinlang.org/api/core/kotlin-stdlib/kotlin/repeat.html", "title": "Kotlin · repeat"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-2", "text": "Phương thức nào được sử dụng để xử lý sự kiện nhấn và giữ nút trong một khoảng thời gian?", "type": "single", "options": [{"id": "A", "text": "setOnClickListener"}, {"id": "B", "text": "setOnLongTouchListener"}, {"id": "C", "text": "setOnLongClickListener"}, {"id": "D", "text": "setLongClickListener"}], "answers": ["C"], "source": {"term": "20241", "pages": [3], "number": 2}, "plain": true, "explanation": "Nhấn giữ được xử lý bằng setOnLongClickListener. onLongClick(view) trả về true nếu sự kiện đã được xử lý. setOnClickListener xử lý thao tác nhấn thông thường; các tên setLongClickListener và setOnLongTouchListener trong đề không phải API tương ứng.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-3", "text": "File strings.xml chứa các tài nguyên chuỗi ký tự nằm trong thư mục nào?", "type": "single", "options": [{"id": "A", "text": "res/strings"}, {"id": "B", "text": "res/xml"}, {"id": "C", "text": "res/drawable"}, {"id": "D", "text": "res/values"}], "answers": ["D"], "source": {"term": "20241", "pages": [3], "number": 3}, "plain": true, "explanation": "Chuỗi trong strings.xml được đặt trong res/values; bản dịch có thể đặt trong values-vi, values-en và các thư mục có qualifier khác. Tên file strings.xml là quy ước quen dùng, còn loại tài nguyên được nhận biết từ phần tử string trong XML. res/strings không phải thư mục tài nguyên chuỗi chuẩn.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-4", "text": "Phương án nào được sử dụng để tạo và khai báo các giá trị của mảng trong Kotlin?", "type": "single", "options": [{"id": "A", "text": "val a = {1, 2, 3, 4, 5}"}, {"id": "B", "text": "val a = [1, 2, 3, 4, 5]"}, {"id": "C", "text": "val a = array(1, 2, 3, 4, 5)"}, {"id": "D", "text": "val a = arrayOf(1, 2, 3, 4, 5)"}], "answers": ["D"], "source": {"term": "20241", "pages": [4], "number": 4}, "plain": true, "explanation": "arrayOf(1, 2, 3, 4, 5) tạo Array<Int> và khởi tạo các phần tử. Dấu [ ] dùng khi truy cập phần tử, không dùng trực tiếp làm literal mảng kiểu JavaScript trong Kotlin. Với mảng số nguyên chuyên biệt có thể dùng intArrayOf(...).", "references": [{"url": "https://kotlinlang.org/docs/arrays.html", "title": "Kotlin · Mảng"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-5", "text": "Trong trường hợp giao diện có nhiều đối tượng làm cho chiều cao của layout lớn hơn chiều cao của màn hình thiết bị, đối tượng nào sau đây được sử dụng cho phép người dùng duyệt được toàn bộ nội dung của layout?", "type": "single", "options": [{"id": "A", "text": "ConstraintLayout"}, {"id": "B", "text": "ScrollView"}, {"id": "C", "text": "LinearLayout"}, {"id": "D", "text": "HorizontalScrollView"}], "answers": ["B"], "source": {"term": "20241", "pages": [4], "number": 5}, "plain": true, "explanation": "ScrollView cho phép cuộn nội dung theo chiều dọc khi nội dung cao hơn màn hình. Nó chỉ có một view con trực tiếp; thường đặt một LinearLayout chứa các trường nhập bên trong. HorizontalScrollView dùng cho chiều ngang, còn LinearLayout tự nó không cung cấp cuộn.", "references": [{"url": "https://developer.android.com/reference/android/widget/ScrollView", "title": "ScrollView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-6", "text": "Kiểu layout nào phù hợp nhất để thiết kế giao diện cho các màn hình phức tạp, cần phải kiểm soát vị trí của nhiều đối tượng giao diện?", "type": "single", "options": [{"id": "A", "text": "ConstraintLayout"}, {"id": "B", "text": "LinearLayout"}, {"id": "C", "text": "RelativeLayout"}, {"id": "D", "text": "FrameLayout"}], "answers": ["A"], "source": {"term": "20241", "pages": [4], "number": 6}, "plain": true, "explanation": "ConstraintLayout cho phép ràng buộc cạnh, baseline, tỉ lệ và chain để xây dựng màn hình phức tạp với cây view tương đối phẳng. Không phải mọi giao diện đều cần nó: LinearLayout hoặc FrameLayout vẫn phù hợp trường hợp đơn giản. Trong nhóm lựa chọn của đề, ConstraintLayout đáp ứng rõ nhất yêu cầu kiểm soát nhiều vị trí.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-7", "text": "Giả sử bên trong RelativeLayout có đối tượng được định nghĩa như sau:\n<TextView android:layout_width=\"wrap_content\"\n    android:layout_height=\"wrap_content\"\n    android:layout_alignParentRight=\"true\"\n    android:layout_alignParentLeft=\"true\"\n    android:text=\"Hello\"/>\nHỏi chiều rộng thực tế của đối tượng là bao nhiêu?", "type": "single", "options": [{"id": "A", "text": "Vừa đủ để chứa chuỗi \"Hello\""}, {"id": "B", "text": "Bằng 0dp"}, {"id": "C", "text": "Bằng với chiều rộng RelativeLayout"}, {"id": "D", "text": "Các đáp án đều không đúng"}], "answers": ["C"], "source": {"term": "20241", "pages": [4], "number": 7}, "plain": true, "explanation": "Hai quy tắc alignParentLeft và alignParentRight ghim hai cạnh ngang của view vào hai cạnh vùng nội dung RelativeLayout, nên chiều rộng bị kéo theo khoảng giữa chúng dù khai báo wrap_content. Với giả thiết cha không padding và view không margin, nó rộng bằng cha. Nếu có padding/margin thì cần trừ phần đó; câu hỏi không cung cấp các giá trị này.", "references": [{"url": "https://developer.android.com/reference/android/widget/RelativeLayout.LayoutParams", "title": "RelativeLayout.LayoutParams"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-8", "text": "Kiểu layout nào thường được sử dụng chỉ để chứa 1 đối tượng bên trong?", "type": "single", "options": [{"id": "A", "text": "ConstraintLayout"}, {"id": "B", "text": "LinearLayout"}, {"id": "C", "text": "RelativeLayout"}, {"id": "D", "text": "FrameLayout"}], "answers": ["D"], "source": {"term": "20241", "pages": [4], "number": 8}, "plain": true, "explanation": "FrameLayout thường dùng làm vùng chứa một view chính hoặc xếp chồng các view. Nó vẫn cho phép nhiều con, nên câu hỏi nói “thường” chứ không phải giới hạn bắt buộc chỉ một view. LinearLayout xếp theo hàng/cột; RelativeLayout và ConstraintLayout diễn tả quan hệ vị trí.", "references": [{"url": "https://developer.android.com/reference/android/widget/FrameLayout", "title": "FrameLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-9", "text": "Các lớp widget (Button, TextView, EditText, ...) kế thừa thuộc tính id từ lớp nào?", "type": "single", "options": [{"id": "A", "text": "android.view.View"}, {"id": "B", "text": "android.widget.TextView"}, {"id": "C", "text": "java.lang.Object"}, {"id": "D", "text": "android.view.ViewGroup"}], "answers": ["A"], "source": {"term": "20241", "pages": [5], "number": 9}, "plain": true, "explanation": "id được khai báo trong android.view.View, là lớp nền của các widget như TextView, Button và EditText. TextView truyền tiếp khả năng này qua kế thừa; ViewGroup cũng là một View nhưng không phải lớp mà mọi widget văn bản kế thừa trực tiếp. Trong XML dùng android:id để đặt ID.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-10", "text": "Android là hệ điều hành dựa trên nền tảng nào?", "type": "single", "options": [{"id": "A", "text": "Ubuntu"}, {"id": "B", "text": "Windows"}, {"id": "C", "text": "Linux"}, {"id": "D", "text": "macOS"}], "answers": ["C"], "source": {"term": "20241", "pages": [5], "number": 10}, "plain": true, "explanation": "Android dùng Linux kernel làm nền tảng hệ điều hành, bên trên là các lớp như HAL, thư viện native, runtime và framework. Android không phải Ubuntu; cả hai có thể dùng nhân Linux nhưng khác nền tảng và hệ ứng dụng. Vì vậy đáp án là Linux, không phải tên một hệ điều hành máy tính khác.", "references": [{"url": "https://source.android.com/docs/core/architecture", "title": "Kiến trúc Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-11", "text": "Giả sử file my_font.ttf đã được sao chép vào thư mục font trong thư mục res. Để thiết lập font chữ cho đối tượng TextView thì thuộc tính nào cần được khai báo trong file XML?", "type": "single", "options": [{"id": "A", "text": "android:textFont=\"@font/my_font\""}, {"id": "B", "text": "android:typeface=\"@font/my_font\""}, {"id": "C", "text": "android:fontFamily=\"@font/my_font\""}, {"id": "D", "text": "android:font=\"@font/my_font\""}], "answers": ["C"], "source": {"term": "20241", "pages": [5], "number": 11}, "plain": true, "explanation": "Dùng android:fontFamily=\"@font/my_font\" để tham chiếu font đặt trong res/font/my_font.ttf. android:typeface không phải cách tham chiếu file font tùy chỉnh này. Trong Kotlin có thể lấy Typeface bằng ResourcesCompat.getFont(...) rồi gán cho TextView.", "references": [{"url": "https://developer.android.com/develop/ui/views/text-and-emoji/fonts-in-xml", "title": "Font trong XML"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-12", "text": "Từ khóa \"val\" được sử dụng với mục đích gì?", "type": "single", "options": [{"id": "A", "text": "Định nghĩa một lớp"}, {"id": "B", "text": "Định nghĩa một hàm"}, {"id": "C", "text": "Định nghĩa một biến có thể thay đổi giá trị"}, {"id": "D", "text": "Định nghĩa một biến không thay đổi được giá trị"}], "answers": ["D"], "source": {"term": "20241", "pages": [5, 6], "number": 12}, "plain": true, "explanation": "val khai báo một tham chiếu chỉ được gán một lần; var cho phép gán lại. Điều này không đồng nghĩa đối tượng mà val trỏ tới luôn bất biến: val list = mutableListOf(1) vẫn cho phép list.add(2). Trong câu hỏi nhập môn, chọn phương án biến không gán lại giá trị.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-13", "text": "Phát biểu nào không phải là một thách thức khi lập trình ứng dụng trên nền tảng Android?", "type": "single", "options": [{"id": "A", "text": "Lập trình viên chỉ sử dụng công cụ lập trình trên một hệ điều hành nhất định."}, {"id": "B", "text": "Mã nguồn và dữ liệu người dùng cần được bảo mật."}, {"id": "C", "text": "Ứng dụng cần tương thích với các phiên bản hệ điều hành khác nhau."}, {"id": "D", "text": "Ứng dụng cần thiết kế phù hợp với nhiều độ phân giải khác nhau."}], "answers": ["A"], "source": {"term": "20241", "pages": [5, 6], "number": 13}, "plain": true, "explanation": "Android Studio có bản cho nhiều hệ điều hành máy tính; việc bắt buộc dùng các công cụ khác nhau theo hệ điều hành, hoặc chỉ được lập trình trên một hệ điều hành, không phải hạn chế Android trong đề. Tương thích phiên bản Android, kích thước/độ phân giải màn hình và bảo vệ dữ liệu đều là các vấn đề thực tế cần xử lý.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-14", "text": "Trong ConstraintLayout để thiết lập 2 đối tượng Button có chiều rộng đều bằng một nửa chiều rộng của layout thì tính năng nào sau đây được sử dụng?", "type": "single", "options": [{"id": "A", "text": "layout weight"}, {"id": "B", "text": "horizontal chain"}, {"id": "C", "text": "horizontal bias"}, {"id": "D", "text": "vertical chain"}], "answers": ["B"], "source": {"term": "20241", "pages": [6], "number": 14}, "plain": true, "explanation": "Tạo horizontal chain cho hai Button, đặt chiều rộng 0dp (match constraints) và trọng số ngang bằng nhau để chia đều khoảng rộng khả dụng. Chỉ tạo chain mà vẫn để wrap_content thì chưa bảo đảm mỗi nút rộng một nửa. Horizontal bias điều chỉnh vị trí, không tự chia kích thước đều; layout_weight là thuộc tính của LinearLayout.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-15", "text": "Phát biểu nào không đúng về Gradle trong Android Studio?", "type": "single", "options": [{"id": "A", "text": "Các cấu hình đặc thù của Android (ví dụ phiên bản SDK) liên quan đến ứng dụng được thiết lập trong file build.gradle."}, {"id": "B", "text": "File build.gradle được mô tả bằng ngôn ngữ XML."}, {"id": "C", "text": "Gradle là hệ thống tự động dịch ứng dụng được sử dụng trong Android Studio."}, {"id": "D", "text": "Gradle thực hiện việc cài đặt ứng dụng trên thiết bị."}], "answers": ["B"], "source": {"term": "20241", "pages": [5, 7], "number": 15}, "plain": true, "explanation": "Gradle tự động hóa build Android và có các task như installDebug để cài bản debug lên thiết bị phù hợp. build.gradle dùng Groovy DSL; build.gradle.kts dùng Kotlin DSL, không phải XML. Cấu hình module chứa các tùy chọn Android và dependencies, và có thể chỉnh sửa sau khi tạo dự án.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-16", "text": "Trong Kotlin, giá trị nào sẽ được in ra màn hình sau khi đoạn chương trình sau được thực hiện?\nval i = 10\nprintln(\"${i++}\")", "type": "single", "options": [{"id": "A", "text": "Đoạn chương trình bị lỗi cú pháp"}, {"id": "B", "text": "10"}, {"id": "C", "text": "11"}, {"id": "D", "text": "$11"}], "answers": ["A"], "source": {"term": "20241", "pages": [5, 7], "number": 16}, "plain": true, "explanation": "i được khai báo bằng val nên không được gán lại. Toán tử i++ cần cập nhật i, vì vậy đoạn code không biên dịch dù nằm trong string template. Nếu dùng var i = 10 thì phép tăng hậu tố in 10 trước rồi mới tăng i thành 11.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-17", "text": "Công cụ nào trong Android Studio được sử dụng để quản lý phiên bản Android được sử dụng để lập trình?", "type": "single", "options": [{"id": "A", "text": "SDK Manager"}, {"id": "B", "text": "Project Structure"}, {"id": "C", "text": "Resource Manager"}, {"id": "D", "text": "Device Manager"}], "answers": ["A"], "source": {"term": "20241", "pages": [7, 8], "number": 17}, "plain": true, "explanation": "SDK Manager cài đặt và quản lý SDK Platforms, Build Tools và các công cụ Android. Device Manager quản lý thiết bị ảo, còn Project Structure cấu hình dự án/module. Có nhiều SDK được cài không tự thay compileSdk của dự án; giá trị đó vẫn nằm trong cấu hình build.", "references": [{"url": "https://developer.android.com/studio/intro/update#sdk-manager", "title": "SDK Manager"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-18", "text": "Thuộc tính text trong EditText là đối tượng thuộc lớp nào?", "type": "single", "options": [{"id": "A", "text": "CharSequence"}, {"id": "B", "text": "Editable"}, {"id": "C", "text": "TextView"}, {"id": "D", "text": "String"}], "answers": ["B"], "source": {"term": "20241", "pages": [7, 8], "number": 18}, "plain": true, "explanation": "EditText.getText() trả về Editable, là giao diện văn bản có thể chỉnh sửa. Editable cũng là một CharSequence, nhưng trong các lựa chọn câu hỏi muốn kiểu trả về cụ thể của EditText. Muốn lấy String có thể gọi editText.text.toString().", "references": [{"url": "https://developer.android.com/reference/android/widget/EditText#getText()", "title": "EditText.getText"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-19", "text": "Giả sử có đoạn lệnh khởi tạo như sau:\nval textView = findViewById<TextView>(R.id.textView)\nval stringId = R.string.app_name\nLệnh nào sau đây thiết lập nội dung của textView là chuỗi app_name được khai báo trong file strings.xml?", "type": "single", "options": [{"id": "A", "text": "textView.text = stringId.toString()"}, {"id": "B", "text": "textView.setText(stringId)"}, {"id": "C", "text": "textView.setText(stringId.toString())"}, {"id": "D", "text": "textView.text = \"$stringId\""}], "answers": ["B"], "source": {"term": "20241", "pages": [8], "number": 19}, "plain": true, "explanation": "R.string.app_name là số ID của tài nguyên chuỗi. textView.setText(stringId) dùng overload nhận resource ID để nạp nội dung app_name. Gọi stringId.toString() hoặc \"$stringId\" chỉ tạo chuỗi chữ số của ID, không lấy nội dung tài nguyên; cách khác đúng là getString(stringId).", "references": [{"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-20", "text": "Trong Kotlin, dấu chấm phẩy (;) được sử dụng trong trường hợp nào?", "type": "single", "options": [{"id": "A", "text": "Kotlin không sử dụng dấu chấm phẩy"}, {"id": "B", "text": "Kết thúc mỗi dòng lệnh"}, {"id": "C", "text": "Kết thúc mỗi câu lệnh"}], "answers": [], "source": {"term": "20241", "pages": [8], "number": 20}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Kotlin thường không cần dấu chấm phẩy cuối dòng; dấu ; dùng để phân tách nhiều câu lệnh viết trên cùng một dòng. Ví dụ val a = 1; println(a). Đây là lựa chọn phù hợp nhất của đề; không suy ra Kotlin cấm dấu ; cuối câu lệnh. Bản bị cắt mất lựa chọn đúng không được chấm.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10"}]}, {"number": 7, "title": "20241 · Đề tr. 9–10 · A", "questions": [{"id": "20241-3-1", "text": "Thuộc tính text trong EditText là đối tượng thuộc lớp nào?", "type": "single", "options": [{"id": "A", "text": "TextView"}, {"id": "B", "text": "CharSequence"}, {"id": "C", "text": "String"}, {"id": "D", "text": "Editable"}], "answers": ["D"], "source": {"term": "20241", "pages": [9], "number": 1}, "plain": true, "explanation": "EditText.getText() trả về Editable, là giao diện văn bản có thể chỉnh sửa. Editable cũng là một CharSequence, nhưng trong các lựa chọn câu hỏi muốn kiểu trả về cụ thể của EditText. Muốn lấy String có thể gọi editText.text.toString().", "references": [{"url": "https://developer.android.com/reference/android/widget/EditText#getText()", "title": "EditText.getText"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-2", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nvar s = 0\nrepeat(5) { s += it }\nprintln(s)", "type": "single", "options": [{"id": "A", "text": "15"}, {"id": "B", "text": "10"}, {"id": "C", "text": "6"}, {"id": "D", "text": "Đoạn chương trình bị lỗi cú pháp"}], "answers": ["B"], "source": {"term": "20241", "pages": [9], "number": 2}, "plain": true, "explanation": "repeat(5) chạy lambda 5 lần với it lần lượt là 0, 1, 2, 3, 4. Vì s bắt đầu bằng 0 nên tổng là 0 + 1 + 2 + 3 + 4 = 10. Không dùng 1 đến 5, và biến s phải là var vì được cập nhật mỗi lượt.", "references": [{"url": "https://kotlinlang.org/api/core/kotlin-stdlib/kotlin/repeat.html", "title": "Kotlin · repeat"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-3", "text": "Thuộc tính nào trong file XML được sử dụng để gán ID cho một đối tượng giao diện?", "type": "single", "options": [{"id": "A", "text": "android:id"}, {"id": "B", "text": "android:ID"}, {"id": "C", "text": "layout:id"}, {"id": "D", "text": "app:id"}], "answers": ["A"], "source": {"term": "20241", "pages": [9], "number": 3}, "plain": true, "explanation": "android:id là thuộc tính đặt định danh view, ví dụ android:id=\"@+id/title\". Dấu + tạo khai báo ID nếu chưa có; @id/title tham chiếu ID đã tồn tại. XML phân biệt chữ hoa chữ thường, nên android:ID khác android:id và không phải thuộc tính đúng.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}, {"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-4", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nfun main() {\n    process(\"SoICT\") { it.uppercase() }\n}\nfun process(s: String, method: (String) -> String) {\n    println(method(s).lowercase())\n}", "type": "single", "options": [{"id": "A", "text": "SoICT"}, {"id": "B", "text": "soict"}, {"id": "C", "text": "SOICT"}, {"id": "D", "text": "Đoạn chương trình bị lỗi cú pháp"}], "answers": ["B"], "source": {"term": "20241", "pages": [9], "number": 4}, "plain": true, "explanation": "Lambda { it.uppercase() } biến \"SoICT\" thành \"SOICT\". Hàm process nhận kết quả đó rồi gọi lowercase() trước khi println, nên kết quả cuối cùng là \"soict\". Đây là hàm bậc cao vì method có kiểu (String) -> String.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-5", "text": "Giả sử file \"mobile.png\" nằm trong thư mục res/drawable và một đối tượng ImageView trong giao diện, phương thức nào được sử dụng để thiết lập ảnh cho ImageView là file \"mobile.png\"?", "type": "single", "options": [{"id": "A", "text": "setImageResource(R.drawable.mobile.png)"}, {"id": "B", "text": "setImageResource(R.drawable.mobile)"}, {"id": "C", "text": "setImageDrawable(R.drawable.mobile)"}, {"id": "D", "text": "setImageResource(R.id.mobile)"}], "answers": ["B"], "source": {"term": "20241", "pages": [9], "number": 5}, "plain": true, "explanation": "setImageResource(R.drawable.mobile) nhận ID tài nguyên drawable dạng số nguyên. Không thêm đuôi .png trong R.drawable.mobile. R.id.mobile là ID view, còn setImageDrawable() cần một đối tượng Drawable, không nhận trực tiếp số ID tài nguyên như phương án trong đề.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-6", "text": "Phát biểu nào không phải là ưu điểm của việc phát triển ứng dụng trên nền tảng Android so với nền tảng iOS?", "type": "single", "options": [{"id": "A", "text": "Có thể sử dụng các công cụ IDE khác nhau"}, {"id": "B", "text": "Có thể dễ dàng tiếp cận với người dùng"}, {"id": "C", "text": "Có thể sử dụng máy tính chạy các hệ điều hành khác nhau"}, {"id": "D", "text": "Thử nghiệm trên nhiều thiết bị vật lý dễ dàng"}], "answers": [], "source": {"term": "20241", "pages": [9], "number": 6}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "Android Studio chạy trên nhiều hệ điều hành máy tính, nên đây là một ưu điểm khách quan có thể kiểm chứng. Tuy nhiên “dễ thử thiết bị”, “dễ tiếp cận người dùng” hay trải nghiệm UI tốt hơn là so sánh phụ thuộc tiêu chí. Đề không nêu đủ tiêu chí và có thể có nhiều nhận định phù hợp; giữ câu để học kiến thức nhưng không chấm ép một đáp án.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10"}, {"id": "20241-3-7", "text": "Thuộc tính layout_gravity của đối tượng view không tự căn chỉnh theo cả 2 hướng khi đặt đối tượng bên trong loại layout nào?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "GridLayout"}, {"id": "C", "text": "RelativeLayout"}, {"id": "D", "text": "FrameLayout"}], "answers": [], "source": {"term": "20241", "pages": [9], "number": 7}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "LinearLayout chỉ dùng layout_gravity để căn theo trục không phải trục sắp xếp; RelativeLayout dùng các quy tắc layout_align... thay vì layout_gravity. Vì cách hỏi “không tự căn chỉnh theo cả 2 hướng” có thể chỉ một trục hoặc không hỗ trợ thuộc tính, có nhiều cách hiểu. Đề thiếu điều kiện nên không chấm ép một loại layout.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/linear", "title": "LinearLayout"}, {"url": "https://developer.android.com/reference/android/widget/RelativeLayout.LayoutParams", "title": "RelativeLayout.LayoutParams"}, {"url": "https://developer.android.com/reference/android/widget/FrameLayout", "title": "FrameLayout"}], "reviewedOn": "2026-11-10"}, {"id": "20241-3-8", "text": "Android là hệ điều hành dựa trên nền tảng nào?", "type": "single", "options": [{"id": "A", "text": "Windows"}, {"id": "B", "text": "macOS"}, {"id": "C", "text": "Linux"}, {"id": "D", "text": "Ubuntu"}], "answers": ["C"], "source": {"term": "20241", "pages": [9], "number": 8}, "plain": true, "explanation": "Android dùng Linux kernel làm nền tảng hệ điều hành, bên trên là các lớp như HAL, thư viện native, runtime và framework. Android không phải Ubuntu; cả hai có thể dùng nhân Linux nhưng khác nền tảng và hệ ứng dụng. Vì vậy đáp án là Linux, không phải tên một hệ điều hành máy tính khác.", "references": [{"url": "https://source.android.com/docs/core/architecture", "title": "Kiến trúc Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-9", "text": "Trong ConstraintLayout để thiết lập 2 đối tượng Button có chiều rộng đều bằng một nửa chiều rộng của layout thì tính năng nào sau đây được sử dụng?", "type": "single", "options": [{"id": "A", "text": "vertical chain"}, {"id": "B", "text": "horizontal chain"}, {"id": "C", "text": "horizontal bias"}, {"id": "D", "text": "layout weight"}], "answers": ["B"], "source": {"term": "20241", "pages": [10], "number": 9}, "plain": true, "explanation": "Tạo horizontal chain cho hai Button, đặt chiều rộng 0dp (match constraints) và trọng số ngang bằng nhau để chia đều khoảng rộng khả dụng. Chỉ tạo chain mà vẫn để wrap_content thì chưa bảo đảm mỗi nút rộng một nửa. Horizontal bias điều chỉnh vị trí, không tự chia kích thước đều; layout_weight là thuộc tính của LinearLayout.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-10", "text": "Từ khóa \"val\" được sử dụng với mục đích gì?", "type": "single", "options": [{"id": "A", "text": "Định nghĩa một biến có thể thay đổi giá trị"}, {"id": "B", "text": "Định nghĩa một biến không thay đổi được giá trị"}, {"id": "C", "text": "Định nghĩa một lớp"}, {"id": "D", "text": "Định nghĩa một hàm"}], "answers": ["B"], "source": {"term": "20241", "pages": [10], "number": 10}, "plain": true, "explanation": "val khai báo một tham chiếu chỉ được gán một lần; var cho phép gán lại. Điều này không đồng nghĩa đối tượng mà val trỏ tới luôn bất biến: val list = mutableListOf(1) vẫn cho phép list.add(2). Trong câu hỏi nhập môn, chọn phương án biến không gán lại giá trị.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-11", "text": "Giả sử file my_font.ttf đã được sao chép vào thư mục font trong thư mục res. Để thiết lập font chữ cho đối tượng TextView thì thuộc tính nào cần được khai báo trong file XML?", "type": "single", "options": [{"id": "A", "text": "android:font=\"@font/my_font\""}, {"id": "B", "text": "android:textFont=\"@font/my_font\""}, {"id": "C", "text": "android:fontFamily=\"@font/my_font\""}, {"id": "D", "text": "android:typeface=\"@font/my_font\""}], "answers": ["C"], "source": {"term": "20241", "pages": [10], "number": 11}, "plain": true, "explanation": "Dùng android:fontFamily=\"@font/my_font\" để tham chiếu font đặt trong res/font/my_font.ttf. android:typeface không phải cách tham chiếu file font tùy chỉnh này. Trong Kotlin có thể lấy Typeface bằng ResourcesCompat.getFont(...) rồi gán cho TextView.", "references": [{"url": "https://developer.android.com/develop/ui/views/text-and-emoji/fonts-in-xml", "title": "Font trong XML"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-12", "text": "Đáp án nào là định nghĩa về lambda trong Kotlin?", "type": "single", "options": [{"id": "A", "text": "Là một kiểu dữ liệu"}, {"id": "B", "text": "Là một lớp"}, {"id": "C", "text": "Là một biểu thức mô tả một hàm không bao gồm tên hàm"}, {"id": "D", "text": "Là một giao diện (Interface)"}], "answers": ["C"], "source": {"term": "20241", "pages": [10], "number": 12}, "plain": true, "explanation": "Lambda là biểu thức mô tả một hàm không có tên, ví dụ { x: Int -> x * 2 }. Có thể lưu nó trong biến kiểu hàm hoặc truyền làm đối số cho hàm bậc cao. Khi chỉ có một tham số và suy ra được kiểu, Kotlin cho phép dùng tên ngầm định it.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-13", "text": "Thuộc tính layout_weight chỉ được sử dụng cho kiểu layout nào?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "FrameLayout"}, {"id": "C", "text": "RelativeLayout"}, {"id": "D", "text": "ConstraintLayout"}], "answers": ["A"], "source": {"term": "20241", "pages": [10], "number": 13}, "plain": true, "explanation": "Trong nhóm layout của đề, layout_weight thuộc LinearLayout.LayoutParams và phân chia phần không gian còn lại theo tỉ lệ trọng số. Với chiều ngang thường đặt layout_width=\"0dp\" cho các view chia đều. Không nhầm thuộc tính này với chain weight của ConstraintLayout.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/linear", "title": "LinearLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-14", "text": "Phương thức nào được sử dụng để xử lý sự kiện nhấn và giữ nút trong một khoảng thời gian?", "type": "single", "options": [{"id": "A", "text": "setOnLongTouchListener"}, {"id": "B", "text": "setOnClickListener"}, {"id": "C", "text": "setLongClickListener"}, {"id": "D", "text": "setOnLongClickListener"}], "answers": ["D"], "source": {"term": "20241", "pages": [10], "number": 14}, "plain": true, "explanation": "Nhấn giữ được xử lý bằng setOnLongClickListener. onLongClick(view) trả về true nếu sự kiện đã được xử lý. setOnClickListener xử lý thao tác nhấn thông thường; các tên setLongClickListener và setOnLongTouchListener trong đề không phải API tương ứng.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-15", "text": "Kiểu layout nào phù hợp nhất để thiết kế giao diện cho các màn hình phức tạp, cần phải kiểm soát vị trí của nhiều đối tượng giao diện?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "RelativeLayout"}, {"id": "C", "text": "ConstraintLayout"}, {"id": "D", "text": "FrameLayout"}], "answers": ["C"], "source": {"term": "20241", "pages": [10], "number": 15}, "plain": true, "explanation": "ConstraintLayout cho phép ràng buộc cạnh, baseline, tỉ lệ và chain để xây dựng màn hình phức tạp với cây view tương đối phẳng. Không phải mọi giao diện đều cần nó: LinearLayout hoặc FrameLayout vẫn phù hợp trường hợp đơn giản. Trong nhóm lựa chọn của đề, ConstraintLayout đáp ứng rõ nhất yêu cầu kiểm soát nhiều vị trí.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-16", "text": "Trong Kotlin, dấu chấm phẩy (;) được sử dụng trong trường hợp nào?", "type": "single", "options": [{"id": "A", "text": "Kết thúc mỗi câu lệnh"}, {"id": "B", "text": "Kotlin không sử dụng dấu chấm phẩy"}, {"id": "C", "text": "Ngăn cách các câu lệnh trên cùng một dòng"}, {"id": "D", "text": "Kết thúc mỗi dòng lệnh"}], "answers": ["C"], "source": {"term": "20241", "pages": [10], "number": 16}, "plain": true, "explanation": "Kotlin thường không cần dấu chấm phẩy cuối dòng; dấu ; dùng để phân tách nhiều câu lệnh viết trên cùng một dòng. Ví dụ val a = 1; println(a). Đây là lựa chọn phù hợp nhất của đề; không suy ra Kotlin cấm dấu ; cuối câu lệnh. Bản bị cắt mất lựa chọn đúng không được chấm.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-17", "text": "Phát biểu nào sau đây không đúng về Logcat trong Android Studio?", "type": "single", "options": [{"id": "A", "text": "Logcat có chức năng lọc dữ liệu theo thẻ hoặc theo tên gói của ứng dụng"}, {"id": "B", "text": "Logcat hiển thị thông tin trên màn hình của ứng dụng trên thiết bị Android"}, {"id": "C", "text": "Cần có kết nối giữa máy tính và thiết bị Android để hiển thị dữ liệu"}, {"id": "D", "text": "Logcat hiển thị thông tin trên máy tính của lập trình viên"}], "answers": ["B"], "source": {"term": "20241", "pages": [10], "number": 17}, "plain": true, "explanation": "Logcat hiển thị log từ ứng dụng và hệ thống trên máy phát triển, có thể lọc theo tag, package và mức độ. Nó không chỉ chứa các dòng do lập trình viên tự ghi. Toast là thông báo ngắn trên thiết bị. “Cần kết nối” ở đây bao gồm thiết bị/emulator đang kết nối; file log đã lưu vẫn có thể xem về sau.", "references": [{"url": "https://developer.android.com/studio/debug/logcat", "title": "Logcat"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-18", "text": "Giả sử bên trong RelativeLayout có đối tượng được định nghĩa như sau:\n<TextView android:layout_width=\"wrap_content\"\n    android:layout_height=\"wrap_content\"\n    android:layout_alignParentRight=\"true\"\n    android:layout_alignParentLeft=\"true\"\n    android:text=\"Hello\"/>\nHỏi chiều rộng thực tế của đối tượng là bao nhiêu?", "type": "single", "options": [{"id": "A", "text": "Vừa đủ để chứa chuỗi \"Hello\""}, {"id": "B", "text": "Bằng với chiều rộng RelativeLayout"}, {"id": "C", "text": "Bằng 0dp"}, {"id": "D", "text": "Các đáp án đều không đúng"}], "answers": ["B"], "source": {"term": "20241", "pages": [10], "number": 18}, "plain": true, "explanation": "Hai quy tắc alignParentLeft và alignParentRight ghim hai cạnh ngang của view vào hai cạnh vùng nội dung RelativeLayout, nên chiều rộng bị kéo theo khoảng giữa chúng dù khai báo wrap_content. Với giả thiết cha không padding và view không margin, nó rộng bằng cha. Nếu có padding/margin thì cần trừ phần đó; câu hỏi không cung cấp các giá trị này.", "references": [{"url": "https://developer.android.com/reference/android/widget/RelativeLayout.LayoutParams", "title": "RelativeLayout.LayoutParams"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-19", "text": "Ngôn ngữ lập trình nào không được sử dụng để lập trình ứng dụng Android dạng native?", "type": "single", "options": [{"id": "A", "text": "C++"}, {"id": "B", "text": "Kotlin"}, {"id": "C", "text": "Java"}, {"id": "D", "text": "JavaScript"}], "answers": ["D"], "source": {"term": "20241", "pages": [10], "number": 19}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-20", "text": "Trong mã nguồn Kotlin, thuộc tính nào dùng để thay đổi phông chữ của văn bản trong TextView?", "type": "single", "options": [{"id": "A", "text": "textStyle"}, {"id": "B", "text": "typeface"}, {"id": "C", "text": "textFont"}, {"id": "D", "text": "fontFamily"}], "answers": ["B"], "source": {"term": "20241", "pages": [10], "number": 20}, "plain": true, "explanation": "Trong Kotlin, textView.typeface tương ứng getter/setter Typeface của TextView và dùng để thay phông chữ. textStyle điều khiển kiểu đậm/nghiêng; fontFamily là tên thuộc tính XML thường dùng chứ không phải thuộc tính Kotlin tương ứng trong nhóm này. Có thể gán textView.typeface = ResourcesCompat.getFont(context, R.font.my_font).", "references": [{"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}], "reviewedOn": "2026-11-10", "note": ""}]}, {"number": 8, "title": "20241 · Lớp 151903 · A (tr. 11–12)", "questions": [{"id": "20241-4-1", "text": "Từ khóa \"val\" được sử dụng với mục đích gì?", "type": "single", "options": [{"id": "A", "text": "Định nghĩa một lớp"}, {"id": "B", "text": "Định nghĩa một biến không thay đổi được giá trị"}, {"id": "C", "text": "Định nghĩa một hàm"}, {"id": "D", "text": "Định nghĩa một biến có thể thay đổi giá trị"}], "answers": ["B"], "source": {"term": "20241", "pages": [11], "number": 1}, "plain": true, "explanation": "val khai báo một tham chiếu chỉ được gán một lần; var cho phép gán lại. Điều này không đồng nghĩa đối tượng mà val trỏ tới luôn bất biến: val list = mutableListOf(1) vẫn cho phép list.add(2). Trong câu hỏi nhập môn, chọn phương án biến không gán lại giá trị.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-2", "text": "Các lớp layout LinearLayout, RelativeLayout, ConstraintLayout được kế thừa trực tiếp từ lớp nào?", "type": "single", "options": [{"id": "A", "text": "android.widget.FrameLayout"}, {"id": "B", "text": "android.view.ViewGroup"}, {"id": "C", "text": "android.view.View"}, {"id": "D", "text": "android.view.Layout"}], "answers": ["B"], "source": {"term": "20241", "pages": [11], "number": 2}, "plain": true, "explanation": "LinearLayout, RelativeLayout và androidx.constraintlayout.widget.ConstraintLayout đều kế thừa trực tiếp ViewGroup. ViewGroup tiếp tục kế thừa View và quản lý các view con. FrameLayout là một layout khác cùng nhóm, không phải lớp cha trực tiếp chung của ba lớp được hỏi.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/declaring-layout", "title": "Layout trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-3", "text": "Giả sử ảnh có kích thước 200px x 200px và đối tượng ImageView có kích thước 100px x 100px. Với cách thiết lập nào của thuộc tính scaleType của đối tượng ImageView sẽ có kết quả hiển thị khác với các cách còn lại?", "type": "single", "options": [{"id": "A", "text": "scaleType=\"centerCrop\""}, {"id": "B", "text": "scaleType=\"center\""}, {"id": "C", "text": "scaleType=\"centerInside\""}, {"id": "D", "text": "scaleType=\"fitXY\""}], "answers": ["B"], "source": {"term": "20241", "pages": [11], "number": 3}, "note": "", "plain": true, "explanation": "Đáp án là center. Với ảnh 200×200 và vùng nhìn 100×100, center giữ kích thước gốc nên chỉ thấy phần giữa ảnh. centerCrop, centerInside và fitXY đều đưa ảnh vuông này về 100×100 nên cho cùng kết quả trong giả thiết không padding và không tác động mật độ tài nguyên. Nhận định cũ cho rằng centerInside cũng khác trong bài này là không đúng.", "references": [{"url": "https://developer.android.com/reference/android/widget/ImageView.ScaleType", "title": "ImageView.ScaleType"}], "reviewedOn": "2026-11-10"}, {"id": "20241-4-4", "text": "Phương thức nào được sử dụng để xử lý sự kiện nhấn và giữ nút trong một khoảng thời gian?", "type": "single", "options": [{"id": "A", "text": "setLongClickListener"}, {"id": "B", "text": "setOnLongTouchListener"}, {"id": "C", "text": "setOnClickListener"}, {"id": "D", "text": "setOnLongClickListener"}], "answers": ["D"], "source": {"term": "20241", "pages": [11], "number": 4}, "plain": true, "explanation": "Nhấn giữ được xử lý bằng setOnLongClickListener. onLongClick(view) trả về true nếu sự kiện đã được xử lý. setOnClickListener xử lý thao tác nhấn thông thường; các tên setLongClickListener và setOnLongTouchListener trong đề không phải API tương ứng.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-5", "text": "Trong Kotlin, câu lệnh nào được sử dụng để khai báo biến kiểu số thực float với giá trị khởi tạo là 3.14?", "type": "single", "options": [{"id": "A", "text": "val x = 3.14"}, {"id": "B", "text": "float x = 3.14"}, {"id": "C", "text": "double x = 3.14"}, {"id": "D", "text": "val x = 3.14f"}], "answers": ["D"], "source": {"term": "20241", "pages": [11], "number": 5}, "plain": true, "explanation": "3.14 mặc định là literal Double; thêm hậu tố f hoặc F để tạo Float, như val x = 3.14f. Kotlin không dùng cú pháp float x hoặc double x kiểu Java. Float có độ chính xác thấp hơn Double nên không chỉ khác tên kiểu.", "references": [{"url": "https://kotlinlang.org/docs/numbers.html", "title": "Kotlin · Kiểu số"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-6", "text": "Ngôn ngữ lập trình nào không được sử dụng để lập trình ứng dụng Android dạng native?", "type": "single", "options": [{"id": "A", "text": "C++"}, {"id": "B", "text": "Java"}, {"id": "C", "text": "JavaScript"}, {"id": "D", "text": "Kotlin"}], "answers": ["C"], "source": {"term": "20241", "pages": [11], "number": 6}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-7", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nfun main() {\n    process(\"SoICT\") { it.uppercase() }\n}\nfun process(s: String, method: (String) -> String) {\n    println(method(s).lowercase())\n}", "type": "single", "options": [{"id": "A", "text": "soict"}, {"id": "B", "text": "SOICT"}, {"id": "C", "text": "SoICT"}, {"id": "D", "text": "Đoạn chương trình bị lỗi cú pháp"}], "answers": ["A"], "source": {"term": "20241", "pages": [11], "number": 7}, "plain": true, "explanation": "Lambda { it.uppercase() } biến \"SoICT\" thành \"SOICT\". Hàm process nhận kết quả đó rồi gọi lowercase() trước khi println, nên kết quả cuối cùng là \"soict\". Đây là hàm bậc cao vì method có kiểu (String) -> String.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-8", "text": "Giả sử có đoạn khởi tạo như sau:\nval textView = findViewById<TextView>(R.id.textView)\nval count = 123\nLệnh nào dưới đây có thể gây lỗi khi chạy chương trình?", "type": "single", "options": [{"id": "A", "text": "textView.text = count.toString()"}, {"id": "B", "text": "textView.setText(count)"}, {"id": "C", "text": "textView.text = \"\" + count"}, {"id": "D", "text": "textView.text = \"$count\""}], "answers": ["B"], "source": {"term": "20241", "pages": [11], "number": 8}, "plain": true, "explanation": "TextView.setText(Int) hiểu số nguyên là ID tài nguyên chuỗi, không phải số cần hiển thị. Vì vậy setText(count) với count = 123 có thể gây Resources.NotFoundException. Dùng count.toString(), \"$count\" hoặc nối chuỗi để chọn overload nhận văn bản.", "references": [{"url": "https://developer.android.com/reference/android/widget/TextView", "title": "TextView"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-9", "text": "Thuộc tính layout_gravity của đối tượng view không tự căn chỉnh theo cả 2 hướng khi đặt đối tượng bên trong loại layout nào?", "type": "single", "options": [{"id": "A", "text": "RelativeLayout"}, {"id": "B", "text": "GridLayout"}, {"id": "C", "text": "LinearLayout"}, {"id": "D", "text": "FrameLayout"}], "answers": [], "source": {"term": "20241", "pages": [12], "number": 9}, "note": "Câu chưa đủ điều kiện để chấm điểm. Xác nhận để xem phân tích.", "plain": true, "explanation": "LinearLayout chỉ dùng layout_gravity để căn theo trục không phải trục sắp xếp; RelativeLayout dùng các quy tắc layout_align... thay vì layout_gravity. Vì cách hỏi “không tự căn chỉnh theo cả 2 hướng” có thể chỉ một trục hoặc không hỗ trợ thuộc tính, có nhiều cách hiểu. Đề thiếu điều kiện nên không chấm ép một loại layout.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/linear", "title": "LinearLayout"}, {"url": "https://developer.android.com/reference/android/widget/RelativeLayout.LayoutParams", "title": "RelativeLayout.LayoutParams"}, {"url": "https://developer.android.com/reference/android/widget/FrameLayout", "title": "FrameLayout"}], "reviewedOn": "2026-11-10"}, {"id": "20241-4-10", "text": "Trong Kotlin, dấu chấm phẩy (;) được sử dụng trong trường hợp nào?", "type": "single", "options": [{"id": "A", "text": "Kết thúc mỗi câu lệnh"}, {"id": "B", "text": "Kotlin không sử dụng dấu chấm phẩy"}, {"id": "C", "text": "Ngăn cách các câu lệnh trên cùng một dòng"}, {"id": "D", "text": "Kết thúc mỗi dòng lệnh"}], "answers": ["C"], "source": {"term": "20241", "pages": [12], "number": 10}, "plain": true, "explanation": "Kotlin thường không cần dấu chấm phẩy cuối dòng; dấu ; dùng để phân tách nhiều câu lệnh viết trên cùng một dòng. Ví dụ val a = 1; println(a). Đây là lựa chọn phù hợp nhất của đề; không suy ra Kotlin cấm dấu ; cuối câu lệnh. Bản bị cắt mất lựa chọn đúng không được chấm.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-11", "text": "File strings.xml chứa các tài nguyên chuỗi ký tự nằm trong thư mục nào?", "type": "single", "options": [{"id": "A", "text": "res/xml"}, {"id": "B", "text": "res/values"}, {"id": "C", "text": "res/drawable"}, {"id": "D", "text": "res/strings"}], "answers": ["B"], "source": {"term": "20241", "pages": [12], "number": 11}, "plain": true, "explanation": "Chuỗi trong strings.xml được đặt trong res/values; bản dịch có thể đặt trong values-vi, values-en và các thư mục có qualifier khác. Tên file strings.xml là quy ước quen dùng, còn loại tài nguyên được nhận biết từ phần tử string trong XML. res/strings không phải thư mục tài nguyên chuỗi chuẩn.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-12", "text": "Các lớp widget (Button, TextView, EditText, ...) kế thừa thuộc tính id từ lớp nào?", "type": "single", "options": [{"id": "A", "text": "android.widget.TextView"}, {"id": "B", "text": "java.lang.Object"}, {"id": "C", "text": "android.view.ViewGroup"}, {"id": "D", "text": "android.view.View"}], "answers": ["D"], "source": {"term": "20241", "pages": [12], "number": 12}, "plain": true, "explanation": "id được khai báo trong android.view.View, là lớp nền của các widget như TextView, Button và EditText. TextView truyền tiếp khả năng này qua kế thừa; ViewGroup cũng là một View nhưng không phải lớp mà mọi widget văn bản kế thừa trực tiếp. Trong XML dùng android:id để đặt ID.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-13", "text": "Đối tượng Layout nào cung cấp cách sắp xếp các view con bằng cách sử dụng các ràng buộc như start_toStartOf và end_toEndOf?", "type": "single", "options": [{"id": "A", "text": "LinearLayout"}, {"id": "B", "text": "ConstraintLayout"}, {"id": "C", "text": "FrameLayout"}, {"id": "D", "text": "RelativeLayout"}], "answers": ["B"], "source": {"term": "20241", "pages": [12], "number": 13}, "plain": true, "explanation": "Các thuộc tính start_toStartOf và end_toEndOf là ràng buộc của ConstraintLayout, thường có tiền tố app:layout_constraint... trong XML. Chúng xác định quan hệ giữa cạnh của view và cạnh view khác/parent. Dùng start/end hỗ trợ hướng bố cục tốt hơn left/right khi có ngôn ngữ RTL.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/constraint-layout", "title": "ConstraintLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-14", "text": "Thuộc tính layout_weight chỉ được sử dụng cho kiểu layout nào?", "type": "single", "options": [{"id": "A", "text": "RelativeLayout"}, {"id": "B", "text": "FrameLayout"}, {"id": "C", "text": "LinearLayout"}, {"id": "D", "text": "ConstraintLayout"}], "answers": ["C"], "source": {"term": "20241", "pages": [12], "number": 14}, "plain": true, "explanation": "Trong nhóm layout của đề, layout_weight thuộc LinearLayout.LayoutParams và phân chia phần không gian còn lại theo tỉ lệ trọng số. Với chiều ngang thường đặt layout_width=\"0dp\" cho các view chia đều. Không nhầm thuộc tính này với chain weight của ConstraintLayout.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/linear", "title": "LinearLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-15", "text": "Ở cửa sổ Project trong phần mềm Android Studio, chức năng hiển thị nào chỉ liệt kê 4 thành phần cơ bản của một dự án (AndroidManifest, mã nguồn Kotlin, các thư mục tài nguyên, các file gradle)?", "type": "single", "options": [{"id": "A", "text": "Android"}, {"id": "B", "text": "Project Files"}, {"id": "C", "text": "Packages"}, {"id": "D", "text": "Production"}], "answers": ["A"], "source": {"term": "20241", "pages": [12], "number": 15}, "plain": true, "explanation": "Chế độ Android trong cửa sổ Project gom file theo các nhóm quen thuộc như manifests, mã nguồn, res và Gradle Scripts. Đây là cách hiển thị logic phục vụ lập trình Android, không phải cấu trúc thư mục vật lý nguyên bản như Project. Tên và cách nhóm có thể khác nhẹ theo phiên bản Android Studio.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/declaring-layout", "title": "Layout trong Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-16", "text": "Thành phần nào được sử dụng để xử lý các tác vụ nền, không có giao diện người dùng trong Android?", "type": "single", "options": [{"id": "A", "text": "Service"}, {"id": "B", "text": "Activity"}, {"id": "C", "text": "Fragment"}, {"id": "D", "text": "ViewModel"}], "answers": ["A"], "source": {"term": "20241", "pages": [12], "number": 16}, "plain": true, "explanation": "Service là component không cung cấp UI, phù hợp đáp án phân loại component trong đề. Nó không tự tạo luồng nền: callback Service mặc định chạy trên main thread, nên tác vụ nặng cần cơ chế xử lý riêng. Android hiện đại giới hạn background service; công việc trì hoãn cần cân nhắc WorkManager, còn công việc người dùng thấy có thể cần foreground service.", "references": [{"url": "https://developer.android.com/develop/background-work/services", "title": "Service"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-17", "text": "Phương án nào được sử dụng để tạo và khai báo các giá trị của mảng trong Kotlin?", "type": "single", "options": [{"id": "A", "text": "val a = array(1, 2, 3, 4, 5)"}, {"id": "B", "text": "val a = [1, 2, 3, 4, 5]"}, {"id": "C", "text": "val a = arrayOf(1, 2, 3, 4, 5)"}, {"id": "D", "text": "val a = {1, 2, 3, 4, 5}"}], "answers": ["C"], "source": {"term": "20241", "pages": [12], "number": 17}, "plain": true, "explanation": "arrayOf(1, 2, 3, 4, 5) tạo Array<Int> và khởi tạo các phần tử. Dấu [ ] dùng khi truy cập phần tử, không dùng trực tiếp làm literal mảng kiểu JavaScript trong Kotlin. Với mảng số nguyên chuyên biệt có thể dùng intArrayOf(...).", "references": [{"url": "https://kotlinlang.org/docs/arrays.html", "title": "Kotlin · Mảng"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-18", "text": "Kiểu layout nào thường được sử dụng chỉ để chứa 1 đối tượng bên trong?", "type": "single", "options": [{"id": "A", "text": "ConstraintLayout"}, {"id": "B", "text": "FrameLayout"}, {"id": "C", "text": "LinearLayout"}, {"id": "D", "text": "RelativeLayout"}], "answers": ["B"], "source": {"term": "20241", "pages": [12], "number": 18}, "plain": true, "explanation": "FrameLayout thường dùng làm vùng chứa một view chính hoặc xếp chồng các view. Nó vẫn cho phép nhiều con, nên câu hỏi nói “thường” chứ không phải giới hạn bắt buộc chỉ một view. LinearLayout xếp theo hàng/cột; RelativeLayout và ConstraintLayout diễn tả quan hệ vị trí.", "references": [{"url": "https://developer.android.com/reference/android/widget/FrameLayout", "title": "FrameLayout"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-19", "text": "Thư mục res không chứa loại tài nguyên nào sau đây?", "type": "single", "options": [{"id": "A", "text": "File định nghĩa cấu trúc menu"}, {"id": "B", "text": "File định nghĩa các thư viện"}, {"id": "C", "text": "File định nghĩa chuỗi ký tự, các giá trị màu"}, {"id": "D", "text": "File định nghĩa các kích thước"}], "answers": ["B"], "source": {"term": "20241", "pages": [12], "number": 19}, "plain": true, "explanation": "res chứa layout, drawable, menu và các giá trị như strings, colors, dimens. Thư viện phụ thuộc được khai báo trong cấu hình Gradle của module, không phải một tài nguyên trong res.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}, {"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-20", "text": "Trong một activity, nếu các đối tượng nút bấm đều thiết lập với phương thức setOnClickListener(this), thì trong phương thức callback onClick, làm thế nào để xác định nút bấm nào đã được nhấn?", "type": "single", "options": [{"id": "A", "text": "Dựa vào vị trí của nút trên màn hình"}, {"id": "B", "text": "Dựa vào tên của nút"}, {"id": "C", "text": "Dựa vào thứ tự khai báo trong file XML"}, {"id": "D", "text": "Dựa vào định danh của nút"}], "answers": ["D"], "source": {"term": "20241", "pages": [12], "number": 20}, "plain": true, "explanation": "onClick nhận chính View đã phát sinh sự kiện. Dùng view.id rồi so sánh với R.id của từng nút để xác định nút được nhấn. Vị trí, thứ tự trong XML hay tên biến Kotlin không phải định danh sự kiện ổn định.", "references": [{"url": "https://developer.android.com/reference/android/view/View", "title": "View"}], "reviewedOn": "2026-11-10", "note": ""}]}];
